//! `reframe_clip` — one clip framed on the current canvas (road map
//! "creator-jobs" VR2a2 and VR2b1, spec §11 VR-26, VR-27). The planner is
//! `reframe.rs`'s (VR-20…VR-24), the writing `reframe_compose.rs`'s (the
//! path composed into the base and the actions the clip already carries,
//! VR-27) and `reframe_cover.rs`'s (`keep`, the backdrop, VR-25); this
//! module reads the arguments, refuses in VR-26's order, and finishes.
//! `replace: true` strips `x`, `y` and `scale` from the ends and fits the
//! base before planning, for every follow but `keep`.
//!
//! **What reads what.** The FOLLOWING kinds (`subject`, `face`, `person`,
//! `salient`) plan over `subjects`; `center` and `fit` are `fixed_framing`;
//! `keep` is `set_canvas`'s rescale on the base. `layout` (VR5b, spec §11
//! VR-53) re-lays a camera's switches and its screen's on the current
//! canvas through `reframe_layout.rs`, reading no `zoom`, `where_empty`,
//! `backdrop`, `replace` or `subjects` and skipping refusals (5) and (6) as
//! `keep` does. Only `keep` and `layout` read `from_*`
//! (every other placement is measured from a canvas centre, so the source
//! size cancels), `fit` and `keep` ignore `zoom`, and only the following
//! kinds read `where_empty` and `subjects`; a value that cannot be read is
//! an `Err` whatever the follow. `cursor` (VR5, spec §11 VR-50) plans over
//! `subjects.cursor` with `reframe_cursor.rs`'s planner and reads no
//! `where_empty`; a face follow never reads the cursor, and a clip whose
//! media has a cursor file is never followed by faces (VR-51).
//!
//! `speaker` (VR6a, spec §11 VR-60, VR-61) frames a wide shot on whoever
//! speaks: it reads `subjects` (its faces' `mouth` and its `turns`) and
//! `mics`, `mic_faces`, `zoom`, `where_empty`, `backdrop` and `replace` as
//! `face` does, and plans through `reframe_speaker.rs`; its subject-free
//! refusals (the microphones', `mic_faces`') come here after (5)–(6) and
//! before `subjects`' values, and the rest are the planner's sentences after
//! "no subjects". No other follow reads `mics` or `mic_faces`.
//!
//! **Why "no subjects" is refused LAST.** The tool fills `subjects` from the
//! analysis cache (VR-28) and first tries the op without them: every other
//! refusal must answer that trial, so only a clip that could be framed waits
//! for an analysis. [`no_subjects`] is the sentence both sides know.
//!
//! **`subjects` is read strictly** (`reframe_subjects.rs`, its reader and
//! [`check_subjects`]).

use serde::{Deserialize, Serialize};

use crate::model::{
    Action, Clip, DuringMotion, EdgeMotion, MediaKind, Project, Source, VideoProps,
};
use crate::outcome::Outcome;
use crate::recipe_matte::matte_target;
use crate::reframe::{
    fixed_framing, in_clip_time, plan_framing, FramingRequest, Subjects, WhereEmpty, FRAMING_TUNING,
};
use crate::reframe_cursor::{cursor_in_clip_time, plan_cursor_framing};
use crate::reframe_speaker::{mics_refusal, plan_speaker_framing};
use crate::reframe_subjects::check_subjects;
use crate::reframe_tracks::Follow;

/// What a framing follows (VR-26).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FramingFollow {
    Subject,
    Face,
    Person,
    Salient,
    Cursor,
    Layout,
    Speaker,
    Center,
    Fit,
    Keep,
}

impl FramingFollow {
    fn following(self) -> Option<Follow> {
        match self {
            Self::Subject => Some(Follow::Subject),
            Self::Face => Some(Follow::Face),
            Self::Person => Some(Follow::Person),
            Self::Salient => Some(Follow::Salient),
            Self::Cursor | Self::Layout | Self::Speaker | Self::Center | Self::Fit | Self::Keep => {
                None
            }
        }
    }

    /// The kinds that read `subjects`: the following kinds, `cursor` and
    /// `speaker`.
    fn reads_subjects(self) -> bool {
        self.following().is_some() || matches!(self, Self::Cursor | Self::Speaker)
    }
}

/// The most samples `subjects` may hold, and boxes of a kind per sample.
pub const MAX_SUBJECT_SAMPLES: usize = 100_000;
pub const MAX_SUBJECT_BOXES: usize = 8;

/// `reframe_clip`'s arguments, in the row's order.
#[derive(Debug, Clone, PartialEq)]
pub struct Reframe {
    pub clip: u32,
    pub follow: FramingFollow,
    pub zoom: Option<f64>,
    pub where_empty: Option<WhereEmpty>,
    pub from_width: Option<u32>,
    pub from_height: Option<u32>,
    pub backdrop: Option<u32>,
    pub replace: Option<bool>,
    pub mics: Option<Vec<u32>>,
    pub mic_faces: Option<Vec<u32>>,
    pub subjects: Option<Subjects>,
}

/// Refusal (10)'s sentence (VR-26), which the tool matches to know a clip
/// waits only for its analysis (VR-28, `AgentServer+Framing.swift`).
pub fn no_subjects(clip: u32) -> String {
    format!("clip {clip} has no subjects to follow; analyze it first")
}

/// VR-50 (h): `cursor` on a media clip whose media has no cursor file.
pub fn no_cursor_file(clip: u32) -> String {
    format!(
        "clip {clip}'s media has no cursor file, so there is no cursor to follow; frame it with \
         subject, center, fit or keep"
    )
}

/// VR-51: a following kind on a media clip whose media has a cursor file.
pub fn cursor_not_faces(clip: u32) -> String {
    format!(
        "clip {clip}'s media has a cursor file, so it follows the cursor, not faces; frame it \
         with cursor, center, fit or keep"
    )
}

impl Project {
    /// The op (spec §11 VR-26; this module's doc, and `edit.rs`'s row).
    pub fn reframe_clip(&self, r: &Reframe) -> Result<Outcome, String> {
        let clip = self.require_clip(r.clip)?.clone();
        if let Some(z) = r
            .zoom
            .filter(|z| !(z.is_finite() && (1.0..=4.0).contains(z)))
        {
            return Err(format!("zoom must be between 1 and 4 times fill, not {z}"));
        }
        for (key, value) in [("from_width", r.from_width), ("from_height", r.from_height)] {
            if value == Some(0) {
                return Err(format!("{key} must be greater than 0, not 0"));
            }
        }
        if let Some(track) = r.backdrop {
            self.require_track(track)?;
        }
        if r.follow == FramingFollow::Speaker {
            for &mic in r.mics.iter().flatten() {
                self.require_clip(mic)?;
            }
        }
        match self.refusal(&clip, r) {
            Some(why) => Ok(Outcome::Refused(why)),
            None => self.reframed(&clip, r),
        }
    }

    /// Refusals (1)–(6) and (8) of VR-26, in order ((7) removed by VR-27),
    /// VR-50's and VR-51's after the nest and still refusals.
    fn refusal(&self, clip: &Clip, r: &Reframe) -> Option<String> {
        let id = clip.id;
        let keep = r.follow == FramingFollow::Keep;
        let following = r.follow.reads_subjects();
        let kind = match clip.source {
            Source::Text => "text",
            Source::Shape => "shape",
            Source::Graphic => "graphic",
            Source::Adjustment => "adjustment",
            _ => "",
        };
        if !kind.is_empty() {
            return (!keep).then(|| {
                format!(
                    "clip {id} is a {kind} clip, with no picture to frame; only keep reframes it"
                )
            });
        }
        let picture = match clip.source {
            Source::Media { media, .. } | Source::Still { media, .. } => self
                .media(media)
                .is_some_and(|m| m.has_video && m.kind == MediaKind::Video),
            _ => true,
        };
        let Some((mw, mh)) = self.source_size(clip).filter(|_| picture) else {
            return Some(format!("clip {id}'s media has no picture to frame"));
        };
        let video = clip.video.clone().unwrap_or_default();
        let crop = video.crop;
        if !(mw - crop.l - crop.r > 0.0
            && mh - crop.t - crop.b > 0.0
            && video.scale.is_finite()
            && video.scale > 0.0)
        {
            return Some(no_picture(id));
        }
        if following {
            match clip.source {
                Source::Nest { .. } => {
                    return Some(format!(
                        "clip {id} shows a nest, which has no subjects to follow; frame it with \
                         center, fit or keep"
                    ))
                }
                Source::Still { .. } | Source::Image { .. } => {
                    return Some(format!(
                        "clip {id} shows a still picture, which has no subjects to follow; frame \
                         it with center, fit or keep"
                    ))
                }
                Source::Media { media, .. } => {
                    let cursor = self.media(media).is_some_and(|m| m.cursor.is_some());
                    if r.follow == FramingFollow::Cursor && !cursor {
                        return Some(no_cursor_file(id));
                    }
                    if r.follow != FramingFollow::Cursor && cursor {
                        return Some(cursor_not_faces(id));
                    }
                }
                _ => {}
            }
        }
        // `layout` re-lays switches that passed CO-62 when made (VR-53 (c)).
        if !keep && r.follow != FramingFollow::Layout {
            if let Some(why) = self.matte_refusal(clip) {
                return Some(why);
            }
            if let Some(why) = turn_refusal(id, clip, &video) {
                return Some(why);
            }
        }
        if r.follow == FramingFollow::Speaker {
            let (mics, faces) = (r.mics.as_deref(), r.mic_faces.as_deref());
            if let Some(why) = mics_refusal(self, id, mics, faces) {
                return Some(why);
            }
        }
        if following {
            if let Some(Err(why)) = r.subjects.as_ref().map(check_subjects) {
                return Some(why);
            }
        }
        None
    }

    /// Refusal (5): a matte track's clip, or one a matte cuts.
    fn matte_refusal(&self, clip: &Clip) -> Option<String> {
        let id = clip.id;
        let index = self.track_index(clip.track)?;
        if self.tracks[index].matte.is_none() {
            let front = self.tracks.get(index + 1)?;
            return (matte_target(&self.tracks, front.id) == Some(clip.track)).then(|| {
                format!(
                    "clip {id} is cut by the matte on track {}, which framing would move it \
                     out of; only keep reframes it",
                    front.id
                )
            });
        }
        Some(format!(
            "clip {id} is on a matte track, which framing would move; only keep reframes it"
        ))
    }

    /// Planned, refused (9) and (10), written and finished.
    fn reframed(&self, clip: &Clip, r: &Reframe) -> Result<Outcome, String> {
        let id = clip.id;
        let zoom = r.zoom.unwrap_or(1.0);
        let canvas = (self.canvas.width, self.canvas.height);
        let from = (r.from_width, r.from_height);
        let from = (from.0.unwrap_or(canvas.0), from.1.unwrap_or(canvas.1));
        match r.follow {
            FramingFollow::Keep => return self.finish(self.kept(id, from)),
            FramingFollow::Layout => return self.relaid(id, from),
            _ => {}
        }
        // VR-27 (g): the strip and the Fit base come before the plan.
        let stripped;
        let source = if r.replace == Some(true) {
            stripped = self.replaced(id);
            &stripped
        } else {
            self
        };
        let path = match (r.follow, r.follow.following()) {
            (FramingFollow::Center, _) => fixed_framing(source, id, WhereEmpty::Center, zoom),
            (FramingFollow::Fit, _) => fixed_framing(source, id, WhereEmpty::Fit, 1.0),
            (FramingFollow::Speaker, _) => {
                let Some(subjects) = &r.subjects else {
                    return Ok(Outcome::Refused(no_subjects(id)));
                };
                let mics = r.mics.as_deref().unwrap_or(&[]);
                let empty = r.where_empty.unwrap_or_default();
                let faces = r.mic_faces.as_deref();
                match plan_speaker_framing(source, id, subjects, mics, faces, zoom, empty) {
                    Ok(path) => Some(path),
                    Err(why) => return Ok(Outcome::Refused(why)),
                }
            }
            (FramingFollow::Cursor, _) => {
                let Some(subjects) = &r.subjects else {
                    return Ok(Outcome::Refused(no_subjects(id)));
                };
                plan_cursor_framing(source, id, &subjects.cursor, zoom)
            }
            (_, Some(follow)) => {
                let Some(subjects) = &r.subjects else {
                    return Ok(Outcome::Refused(no_subjects(id)));
                };
                let request = FramingRequest {
                    follow,
                    zoom,
                    from_width: canvas.0,
                    from_height: canvas.1,
                    where_empty: r.where_empty.unwrap_or_default(),
                };
                plan_framing(source, id, subjects, &request, &FRAMING_TUNING)
            }
            (_, None) => None,
        };
        // No path is unreached: every arm the planner has is refused above.
        let Some(path) = path else {
            return Ok(Outcome::Refused(no_picture(id)));
        };
        let backdrop = r.backdrop.filter(|_| path.shows_fit);
        let original = Clip {
            video: Some(clip.video.clone().unwrap_or_default()),
            ..clip.clone()
        };
        if let Some(track) = backdrop {
            if let Err(why) = self.blurred_copy(&original, 0, 0) {
                return Ok(Outcome::Refused(why));
            }
            if self.track_index(track) >= self.track_index(clip.track) {
                return Ok(Outcome::Refused(format!(
                    "track {track} is not behind clip {id}'s track, so a backdrop there would \
                     cover it"
                )));
            }
        }
        if let (Some(_), Some(subjects)) = (r.follow.following(), &r.subjects) {
            if in_clip_time(clip, self, subjects).0.is_empty() {
                return Ok(Outcome::Refused(no_subjects(id)));
            }
        }
        if let (FramingFollow::Cursor, Some(subjects)) = (r.follow, &r.subjects) {
            if cursor_in_clip_time(clip, self, &subjects.cursor).is_empty() {
                return Ok(Outcome::Refused(no_subjects(id)));
            }
        }
        let (mut next, _) = source.composed(id, &path);
        if let Some(track) = backdrop {
            next = next.with_backdrop(&original, track)?;
        }
        self.finish(next)
    }
}

/// Refusal (2)'s crop sentence.
fn no_picture(id: u32) -> String {
    format!("clip {id}'s crop or scale leaves no picture to frame")
}

/// Refusal (6): a turned base, an action end turning the clip, or a spin.
fn turn_refusal(id: u32, clip: &Clip, video: &VideoProps) -> Option<String> {
    let upright = "framing works on an upright picture; only keep reframes it";
    if video.rotation != 0.0 {
        return Some(format!(
            "clip {id} is turned {}°, and {upright}",
            video.rotation
        ));
    }
    let turning = |a: &&Action| {
        a.end["video"]["rotation"]
            .as_f64()
            .is_some_and(|r| r != 0.0)
    };
    if let Some(action) = clip.actions.iter().find(turning) {
        return Some(format!(
            "clip {id}'s action {} turns it, and {upright}",
            action.id
        ));
    }
    let spins = video.motion.as_ref().is_some_and(|m| {
        [m.r#in, m.out]
            .iter()
            .flatten()
            .any(|e| e.kind == EdgeMotion::Spin)
            || m.during.is_some_and(|d| d.kind == DuringMotion::Spin)
    });
    spins.then(|| format!("clip {id} spins in its motion, and {upright}"))
}
//! The framing path's keys (road map "creator-jobs" VR2a1 and VR2a2, spec
//! §11 VR-23, VR-24): what the chosen subject per sample becomes as keys of
//! F. VR-23's moves — the median-filtered subject point, the dead zone, the
//! speed, the spacing — moved here whole from `reframe.rs`, which keeps the
//! frames, the composition and the mapping into clip time; VR-24 adds what
//! a real recording needs beyond them:
//!
//! - **a hard cut at each shot change** — a one-frame `linear` segment
//!   ending exactly on the first canvas frame that shows the new shot, onto
//!   the new shot's subject's median over its first second;
//! - **loss** — a subject gone is held [`LOSS_HOLD`], then another subject is
//!   followed, or the framing eases over [`EMPTY_EASE`] to the `where_empty`
//!   state and the path goes EMPTY;
//! - **return** — from EMPTY once a subject has been seen for
//!   [`RETURN_SEEN`];
//! - **two people** framed together when both boxes, widened by
//!   [`PAIR_WIDEN`], fit the window.
//!
//! No move or ease ends after the frame before a cut, and a cut counts as a
//! move's end for VR-23's spacing. Every key is on the canvas's grid and the
//! keys are strictly increasing.

use crate::actions::ease;
use crate::model::Curve;
use crate::reframe::{
    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
};
pub use crate::reframe_tracks::LOSS_HOLD;
use crate::reframe_tracks::{median, Chosen, SubjectBox, SubjectKind};
use crate::time::{
    one_frame, snap_down_to_frame, snap_to_frame, snap_up_to_frame, Fps, Ticks, TIMESCALE,
};

/// The ease to `where_empty` after a loss: 0.8 s.
pub const EMPTY_EASE: Ticks = TIMESCALE * 4 / 5;
/// How long a subject must be seen at every sample before the framing
/// returns to it from EMPTY: 0.6 s.
pub const RETURN_SEEN: Ticks = TIMESCALE * 3 / 5;
/// A cut places the new shot on its subject's median over this: 1 s.
pub const CUT_MEDIAN: Ticks = TIMESCALE;
/// Each of two people's boxes is widened by this about its centre before
/// their union is tested against the window.
pub const PAIR_WIDEN: f64 = 1.15;

/// The subject point's median reads ±0.5 s.
const MEDIAN_SPAN: Ticks = TIMESCALE / 2;
/// The shortest move: 0.4 s.
pub(crate) const MOVE_MIN: f64 = 0.4;
/// No move within 0.5 s of the last one's end…
pub(crate) const MOVE_SPACING: Ticks = TIMESCALE / 2;

impl FramingPath {
    /// (scale, x, y) at clip tick `t`: the segment ending at key i eases with
    /// key i's curve (`actions::ease`); before the first key its value, after
    /// the last its value.
    pub fn at(&self, t: Ticks) -> (f64, f64, f64) {
        let value = |k: &FramingKey| (k.scale, k.x, k.y);
        let Some(first) = self.keys.first() else {
            return (1.0, 0.0, 0.0);
        };
        let Some(i) = self.keys.iter().position(|k| k.t >= t) else {
            return value(self.keys.last().expect("not empty"));
        };
        if i == 0 {
            return value(first);
        }
        let (a, b) = (&self.keys[i - 1], &self.keys[i]);
        let e = ease(b.curve, (t - a.t) as f64 / (b.t - a.t) as f64);
        (
            a.scale + (b.scale - a.scale) * e,
            a.x + (b.x - a.x) * e,
            a.y + (b.y - a.y) * e,
        )
    }

    /// Keys whose (scale, x, y) differ from the previous key's.
    pub fn moves(&self) -> usize {
        self.keys
            .windows(2)
            .filter(|w| (w[0].scale, w[0].x, w[0].y) != (w[1].scale, w[1].x, w[1].y))
            .count()
    }
}

/// What the framing holds: a window centred on a source-canvas point, or
/// the whole picture fitted.
#[derive(Debug, Clone, Copy, PartialEq)]
enum At {
    Window(Point),
    Fit,
}

/// The keys as they are written, and the state they leave.
struct Writer<'a> {
    frame: &'a Frame,
    keys: Vec<FramingKey>,
    current: At,
    shows_fit: bool,
    last_end: Option<Ticks>,
}

impl Writer<'_> {
    fn key(&self, t: Ticks, at: At, curve: Curve) -> FramingKey {
        match at {
            At::Window(wc) => self.frame.key(t, wc, curve),
            At::Fit => self.frame.fit_key(t, curve),
        }
    }

    /// A hold key at `start` (unless the last key is there already) and the
    /// key `to` at `end` with `curve`.
    fn go(&mut self, start: Ticks, end: Ticks, to: At, curve: Curve) {
        if start > self.keys.last().expect("the first key").t {
            self.keys.push(self.key(start, self.current, Curve::Linear));
        }
        self.keys.push(self.key(end, to, curve));
        self.shows_fit |= to == At::Fit;
        self.current = to;
        self.last_end = Some(end);
    }

    fn running(&self, t: Ticks) -> bool {
        self.last_end.is_some_and(|end| t < end)
    }
}

/// The subject point and offset of a chosen sample (VR-22), its pair's
/// union standing in when both widened boxes fit the window (VR-24 (g)).
fn point_of(frame: &Frame, c: &Chosen, headroom: f64) -> Option<(SubjectKind, Point, Point)> {
    let (kind, b) = (c.kind?, c.subject?);
    let widened = |b: &SubjectBox| {
        let (cx, cy) = (b.x + b.w / 2.0, b.y + b.h / 2.0);
        let (w, h) = (b.w * PAIR_WIDEN, b.h * PAIR_WIDEN);
        (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
    };
    let pair = c.second.and_then(|other| {
        let (a, o) = (widened(&b), widened(&other));
        let (x0, y0) = (a.0.min(o.0), a.1.min(o.1));
        let (x1, y1) = (a.2.max(o.2), a.3.max(o.3));
        let (p0, p1) = (frame.point(c.t, x0, y0), frame.point(c.t, x1, y1));
//! `follow: cursor` — a screen recording framed on its recorded pointer
//! (road map "creator-jobs" VR5, spec §11 VR-50). Pure; `edit_reframe.rs`'s
//! op writes the path as it writes every framing (`reframe_compose.rs`).
//!
//! **The points.** `subjects.cursor` (`reframe_subjects.rs`), in forward-media
//! source ticks, is put into clip time by [`cursor_in_clip_time`]: kept in the
//! played window, mapped through `clip_source_time.rs`'s one mapping, one
//! point per clip tick with `click` and `typing` OR'ed over the points merged.
//!
//! **The window** is `reframe.rs`'s `Frame` at the request's zoom from the
//! current canvas: a point lands on the source canvas through the placement in
//! force (`Frame::point`, VR-27 (a)) and the desired centre is that point
//! clamped (`Frame::clamp`) — no headroom, no offset, since a pointer is a
//! point and not a head.
//!
//! **The moves** ([`CURSOR_TUNING`]): the first key on the first point; a
//! dead zone ±0.20 of the window's width and ±0.12 of its height around the
//! window's target, wider than a face's 0.15 because a pointer wanders where a
//! face holds still; a down click outside it ARRIVES — its move ends on the
//! click's frame, planned back from it at 0.8 window widths a second (at
//! least 0.4 s) and started no earlier than the last move's end; any other
//! point outside it starts VR-23's move unless one runs, it is within 0.5 s of
//! the last move's end with the pointer still in the window, the move would
//! end after a pending arrival's start, or the pointer is typing — a typing
//! stretch holds the window, where a click inside one still arrives. No cut,
//! no `fit`: `where_empty` and `backdrop` never act on it.

use crate::clip_source_time::{clip_time_of_source, in_played_window, Round};
use crate::model::{Clip, Curve, MediaKind, Project, Source};
use crate::reframe::{
    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
};
use crate::reframe_path::{span, MOVE_MIN, MOVE_SPACING};
use crate::reframe_subjects::CursorPoint;
use crate::reframe_tracks::Follow;
use crate::time::{snap_to_frame, Fps, Ticks, TIMESCALE};

/// VR-50 (d): the dead zone ±0.20 of the window's width (a face's is 0.15)
/// and ±0.12 of its height, 0.8 window widths a second, no headroom.
pub const CURSOR_TUNING: FramingTuning = FramingTuning {
    dead_zone_width: 0.20,
    dead_zone_height: 0.12,
    speed: 0.8,
    headroom: 0.0,
};

/// VR-50 (a): the points in clip time — kept in the played window, mapped
/// with `Round::Down`, sorted by (clip tick, media tick), one per clip tick
/// (the earliest media tick's position) with `click` and `typing` OR'ed over
/// the points it stands for. Empty for a clip that is not a media clip.
pub(crate) fn cursor_in_clip_time(
    clip: &Clip,
    project: &Project,
    points: &[CursorPoint],
) -> Vec<CursorPoint> {
    let Source::Media { media, .. } = clip.source else {
        return Vec::new();
    };
    let Some(media) = project.media(media) else {
        return Vec::new();
    };
    let mut mapped: Vec<(Ticks, Ticks, CursorPoint)> = points
        .iter()
        .filter(|p| in_played_window(clip, media, p.t))
        .filter_map(|p| clip_time_of_source(clip, media, p.t, Round::Down).map(|c| (c, p.t, *p)))
        .collect();
    mapped.sort_by_key(|&(c, m, _)| (c, m));
    let mut out: Vec<CursorPoint> = Vec::with_capacity(mapped.len());
    for (c, _, p) in mapped {
        match out.last_mut() {
            Some(last) if last.t == c => {
                last.click |= p.click;
                last.typing |= p.typing;
            }
            _ => out.push(CursorPoint { t: c, ..p }),
        }
    }
    out
}

//! `reframe_clip` — one clip framed on the current canvas (road map
//! "creator-jobs" VR2a2 and VR2b1, spec §11 VR-26, VR-27). The planner is
//! `reframe.rs`'s (VR-20…VR-24), the writing `reframe_compose.rs`'s (the
//! path composed into the base and the actions the clip already carries,
//! VR-27) and `reframe_cover.rs`'s (`keep`, the backdrop, VR-25); this
//! module reads the arguments, refuses in VR-26's order, and finishes.
//! `replace: true` strips `x`, `y` and `scale` from the ends and fits the
//! base before planning, for every follow but `keep`.
//!
//! **What reads what.** The FOLLOWING kinds (`subject`, `face`, `person`,
//! `salient`) plan over `subjects`; `center` and `fit` are `fixed_framing`;
//! `keep` is `set_canvas`'s rescale on the base. `layout` (VR5b, spec §11
//! VR-53) re-lays a camera's switches and its screen's on the current
//! canvas through `reframe_layout.rs`, reading no `zoom`, `where_empty`,
//! `backdrop`, `replace` or `subjects` and skipping refusals (5) and (6) as
//! `keep` does. Only `keep` and `layout` read `from_*`
//! (every other placement is measured from a canvas centre, so the source
//! size cancels), `fit` and `keep` ignore `zoom`, and only the following
//! kinds read `where_empty` and `subjects`; a value that cannot be read is
//! an `Err` whatever the follow. `cursor` (VR5, spec §11 VR-50) plans over
//! `subjects.cursor` with `reframe_cursor.rs`'s planner and reads no
//! `where_empty`; a face follow never reads the cursor, and a clip whose
//! media has a cursor file is never followed by faces (VR-51).
//!
//! `speaker` (VR6a, spec §11 VR-60, VR-61) frames a wide shot on whoever
//! speaks: it reads `subjects` (its faces' `mouth` and its `turns`) and
//! `mics`, `mic_faces`, `zoom`, `where_empty`, `backdrop` and `replace` as
//! `face` does, and plans through `reframe_speaker.rs`; its subject-free
//! refusals (the microphones', `mic_faces`') come here after (5)–(6) and
//! before `subjects`' values, and the rest are the planner's sentences after
//! "no subjects". No other follow reads `mics` or `mic_faces`.
//!
//! **Why "no subjects" is refused LAST.** The tool fills `subjects` from the
//! analysis cache (VR-28) and first tries the op without them: every other
//! refusal must answer that trial, so only a clip that could be framed waits
//! for an analysis. [`no_subjects`] is the sentence both sides know.
//!
//! **`subjects` is read strictly** (`reframe_subjects.rs`, its reader and
//! [`check_subjects`]).

use serde::{Deserialize, Serialize};

use crate::model::{
    Action, Clip, DuringMotion, EdgeMotion, MediaKind, Project, Source, VideoProps,
};
use crate::outcome::Outcome;
use crate::recipe_matte::matte_target;
use crate::reframe::{
    fixed_framing, in_clip_time, plan_framing, FramingRequest, Subjects, WhereEmpty, FRAMING_TUNING,
};
use crate::reframe_cursor::{cursor_in_clip_time, plan_cursor_framing};
use crate::reframe_speaker::{mics_refusal, plan_speaker_framing};
use crate::reframe_subjects::check_subjects;
use crate::reframe_tracks::Follow;

/// What a framing follows (VR-26).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum FramingFollow {
    Subject,
    Face,
    Person,
    Salient,
    Cursor,
    Layout,
    Speaker,
    Center,
    Fit,
    Keep,
}

impl FramingFollow {
    fn following(self) -> Option<Follow> {
        match self {
            Self::Subject => Some(Follow::Subject),
            Self::Face => Some(Follow::Face),
            Self::Person => Some(Follow::Person),
            Self::Salient => Some(Follow::Salient),
            Self::Cursor | Self::Layout | Self::Speaker | Self::Center | Self::Fit | Self::Keep => {
                None
            }
        }
    }

    /// The kinds that read `subjects`: the following kinds, `cursor` and
    /// `speaker`.
    fn reads_subjects(self) -> bool {
        self.following().is_some() || matches!(self, Self::Cursor | Self::Speaker)
    }
}

/// The most samples `subjects` may hold, and boxes of a kind per sample.
pub const MAX_SUBJECT_SAMPLES: usize = 100_000;
pub const MAX_SUBJECT_BOXES: usize = 8;

/// `reframe_clip`'s arguments, in the row's order.
#[derive(Debug, Clone, PartialEq)]
pub struct Reframe {
    pub clip: u32,
    pub follow: FramingFollow,
    pub zoom: Option<f64>,
    pub where_empty: Option<WhereEmpty>,
    pub from_width: Option<u32>,
    pub from_height: Option<u32>,
    pub backdrop: Option<u32>,
    pub replace: Option<bool>,
    pub mics: Option<Vec<u32>>,
    pub mic_faces: Option<Vec<u32>>,
    pub subjects: Option<Subjects>,
}

/// Refusal (10)'s sentence (VR-26), which the tool matches to know a clip
/// waits only for its analysis (VR-28, `AgentServer+Framing.swift`).
pub fn no_subjects(clip: u32) -> String {
    format!("clip {clip} has no subjects to follow; analyze it first")
}

/// VR-50 (h): `cursor` on a media clip whose media has no cursor file.
pub fn no_cursor_file(clip: u32) -> String {
    format!(
        "clip {clip}'s media has no cursor file, so there is no cursor to follow; frame it with \
         subject, center, fit or keep"
    )
}

/// VR-51: a following kind on a media clip whose media has a cursor file.
pub fn cursor_not_faces(clip: u32) -> String {
    format!(
        "clip {clip}'s media has a cursor file, so it follows the cursor, not faces; frame it \
         with cursor, center, fit or keep"
    )
}

impl Project {
    /// The op (spec §11 VR-26; this module's doc, and `edit.rs`'s row).
    pub fn reframe_clip(&self, r: &Reframe) -> Result<Outcome, String> {
        let clip = self.require_clip(r.clip)?.clone();
        if let Some(z) = r
            .zoom
            .filter(|z| !(z.is_finite() && (1.0..=4.0).contains(z)))
        {
            return Err(format!("zoom must be between 1 and 4 times fill, not {z}"));
        }
        for (key, value) in [("from_width", r.from_width), ("from_height", r.from_height)] {
            if value == Some(0) {
                return Err(format!("{key} must be greater than 0, not 0"));
            }
        }
        if let Some(track) = r.backdrop {
            self.require_track(track)?;
        }
        if r.follow == FramingFollow::Speaker {
            for &mic in r.mics.iter().flatten() {
                self.require_clip(mic)?;
            }
        }
        match self.refusal(&clip, r) {
            Some(why) => Ok(Outcome::Refused(why)),
            None => self.reframed(&clip, r),
        }
    }

    /// Refusals (1)–(6) and (8) of VR-26, in order ((7) removed by VR-27),
    /// VR-50's and VR-51's after the nest and still refusals.
    fn refusal(&self, clip: &Clip, r: &Reframe) -> Option<String> {
        let id = clip.id;
        let keep = r.follow == FramingFollow::Keep;
        let following = r.follow.reads_subjects();
        let kind = match clip.source {
            Source::Text => "text",
            Source::Shape => "shape",
            Source::Graphic => "graphic",
            Source::Adjustment => "adjustment",
            _ => "",
        };
        if !kind.is_empty() {
            return (!keep).then(|| {
                format!(
                    "clip {id} is a {kind} clip, with no picture to frame; only keep reframes it"
                )
            });
        }
        let picture = match clip.source {
            Source::Media { media, .. } | Source::Still { media, .. } => self
                .media(media)
                .is_some_and(|m| m.has_video && m.kind == MediaKind::Video),
            _ => true,
        };
        let Some((mw, mh)) = self.source_size(clip).filter(|_| picture) else {
            return Some(format!("clip {id}'s media has no picture to frame"));
        };
        let video = clip.video.clone().unwrap_or_default();
        let crop = video.crop;
        if !(mw - crop.l - crop.r > 0.0
            && mh - crop.t - crop.b > 0.0
            && video.scale.is_finite()
            && video.scale > 0.0)
        {
            return Some(no_picture(id));
        }
        if following {
            match clip.source {
                Source::Nest { .. } => {
                    return Some(format!(
                        "clip {id} shows a nest, which has no subjects to follow; frame it with \
                         center, fit or keep"
                    ))
                }
                Source::Still { .. } | Source::Image { .. } => {
                    return Some(format!(
                        "clip {id} shows a still picture, which has no subjects to follow; frame \
                         it with center, fit or keep"
                    ))
                }
                Source::Media { media, .. } => {
                    let cursor = self.media(media).is_some_and(|m| m.cursor.is_some());
                    if r.follow == FramingFollow::Cursor && !cursor {
                        return Some(no_cursor_file(id));
                    }
                    if r.follow != FramingFollow::Cursor && cursor {
                        return Some(cursor_not_faces(id));
                    }
                }
                _ => {}
            }
        }
        // `layout` re-lays switches that passed CO-62 when made (VR-53 (c)).
        if !keep && r.follow != FramingFollow::Layout {
            if let Some(why) = self.matte_refusal(clip) {
                return Some(why);
            }
            if let Some(why) = turn_refusal(id, clip, &video) {
                return Some(why);
            }
        }
        if r.follow == FramingFollow::Speaker {
            let (mics, faces) = (r.mics.as_deref(), r.mic_faces.as_deref());
            if let Some(why) = mics_refusal(self, id, mics, faces) {
                return Some(why);
            }
        }
        if following {
            if let Some(Err(why)) = r.subjects.as_ref().map(check_subjects) {
                return Some(why);
            }
        }
        None
    }

    /// Refusal (5): a matte track's clip, or one a matte cuts.
    fn matte_refusal(&self, clip: &Clip) -> Option<String> {
        let id = clip.id;
        let index = self.track_index(clip.track)?;
        if self.tracks[index].matte.is_none() {
            let front = self.tracks.get(index + 1)?;
            return (matte_target(&self.tracks, front.id) == Some(clip.track)).then(|| {
                format!(
                    "clip {id} is cut by the matte on track {}, which framing would move it \
                     out of; only keep reframes it",
                    front.id
                )
            });
        }
        Some(format!(
            "clip {id} is on a matte track, which framing would move; only keep reframes it"
        ))
    }

    /// Planned, refused (9) and (10), written and finished.
    fn reframed(&self, clip: &Clip, r: &Reframe) -> Result<Outcome, String> {
        let id = clip.id;
        let zoom = r.zoom.unwrap_or(1.0);
        let canvas = (self.canvas.width, self.canvas.height);
        let from = (r.from_width, r.from_height);
        let from = (from.0.unwrap_or(canvas.0), from.1.unwrap_or(canvas.1));
        match r.follow {
            FramingFollow::Keep => return self.finish(self.kept(id, from)),
            FramingFollow::Layout => return self.relaid(id, from),
            _ => {}
        }
        // VR-27 (g): the strip and the Fit base come before the plan.
        let stripped;
        let source = if r.replace == Some(true) {
            stripped = self.replaced(id);
            &stripped
        } else {
            self
        };
        let path = match (r.follow, r.follow.following()) {
            (FramingFollow::Center, _) => fixed_framing(source, id, WhereEmpty::Center, zoom),
            (FramingFollow::Fit, _) => fixed_framing(source, id, WhereEmpty::Fit, 1.0),
            (FramingFollow::Speaker, _) => {
                let Some(subjects) = &r.subjects else {
                    return Ok(Outcome::Refused(no_subjects(id)));
                };
                let mics = r.mics.as_deref().unwrap_or(&[]);
                let empty = r.where_empty.unwrap_or_default();
                let faces = r.mic_faces.as_deref();
                match plan_speaker_framing(source, id, subjects, mics, faces, zoom, empty) {
                    Ok(path) => Some(path),
                    Err(why) => return Ok(Outcome::Refused(why)),
                }
            }
            (FramingFollow::Cursor, _) => {
                let Some(subjects) = &r.subjects else {
                    return Ok(Outcome::Refused(no_subjects(id)));
                };
                plan_cursor_framing(source, id, &subjects.cursor, zoom)
            }
            (_, Some(follow)) => {
                let Some(subjects) = &r.subjects else {
                    return Ok(Outcome::Refused(no_subjects(id)));
                };
                let request = FramingRequest {
                    follow,
                    zoom,
                    from_width: canvas.0,
                    from_height: canvas.1,
                    where_empty: r.where_empty.unwrap_or_default(),
                };
                plan_framing(source, id, subjects, &request, &FRAMING_TUNING)
            }
            (_, None) => None,
        };
        // No path is unreached: every arm the planner has is refused above.
        let Some(path) = path else {
            return Ok(Outcome::Refused(no_picture(id)));
        };
        let backdrop = r.backdrop.filter(|_| path.shows_fit);
        let original = Clip {
            video: Some(clip.video.clone().unwrap_or_default()),
            ..clip.clone()
        };
        if let Some(track) = backdrop {
            if let Err(why) = self.blurred_copy(&original, 0, 0) {
                return Ok(Outcome::Refused(why));
            }
            if self.track_index(track) >= self.track_index(clip.track) {
                return Ok(Outcome::Refused(format!(
                    "track {track} is not behind clip {id}'s track, so a backdrop there would \
                     cover it"
                )));
            }
        }
        if let (Some(_), Some(subjects)) = (r.follow.following(), &r.subjects) {
            if in_clip_time(clip, self, subjects).0.is_empty() {
                return Ok(Outcome::Refused(no_subjects(id)));
            }
        }
        if let (FramingFollow::Cursor, Some(subjects)) = (r.follow, &r.subjects) {
            if cursor_in_clip_time(clip, self, &subjects.cursor).is_empty() {
                return Ok(Outcome::Refused(no_subjects(id)));
            }
        }
        let (mut next, _) = source.composed(id, &path);
        if let Some(track) = backdrop {
            next = next.with_backdrop(&original, track)?;
        }
        self.finish(next)
    }
}

/// Refusal (2)'s crop sentence.
fn no_picture(id: u32) -> String {
    format!("clip {id}'s crop or scale leaves no picture to frame")
}

/// Refusal (6): a turned base, an action end turning the clip, or a spin.
fn turn_refusal(id: u32, clip: &Clip, video: &VideoProps) -> Option<String> {
    let upright = "framing works on an upright picture; only keep reframes it";
    if video.rotation != 0.0 {
        return Some(format!(
            "clip {id} is turned {}°, and {upright}",
            video.rotation
        ));
    }
    let turning = |a: &&Action| {
        a.end["video"]["rotation"]
            .as_f64()
            .is_some_and(|r| r != 0.0)
    };
    if let Some(action) = clip.actions.iter().find(turning) {
        return Some(format!(
            "clip {id}'s action {} turns it, and {upright}",
            action.id
        ));
    }
    let spins = video.motion.as_ref().is_some_and(|m| {
        [m.r#in, m.out]
            .iter()
            .flatten()
            .any(|e| e.kind == EdgeMotion::Spin)
            || m.during.is_some_and(|d| d.kind == DuringMotion::Spin)
    });
    spins.then(|| format!("clip {id} spins in its motion, and {upright}"))
}
//! The framing path's keys (road map "creator-jobs" VR2a1 and VR2a2, spec
//! §11 VR-23, VR-24): what the chosen subject per sample becomes as keys of
//! F. VR-23's moves — the median-filtered subject point, the dead zone, the
//! speed, the spacing — moved here whole from `reframe.rs`, which keeps the
//! frames, the composition and the mapping into clip time; VR-24 adds what
//! a real recording needs beyond them:
//!
//! - **a hard cut at each shot change** — a one-frame `linear` segment
//!   ending exactly on the first canvas frame that shows the new shot, onto
//!   the new shot's subject's median over its first second;
//! - **loss** — a subject gone is held [`LOSS_HOLD`], then another subject is
//!   followed, or the framing eases over [`EMPTY_EASE`] to the `where_empty`
//!   state and the path goes EMPTY;
//! - **return** — from EMPTY once a subject has been seen for
//!   [`RETURN_SEEN`];
//! - **two people** framed together when both boxes, widened by
//!   [`PAIR_WIDEN`], fit the window.
//!
//! No move or ease ends after the frame before a cut, and a cut counts as a
//! move's end for VR-23's spacing. Every key is on the canvas's grid and the
//! keys are strictly increasing.

use crate::actions::ease;
use crate::model::Curve;
use crate::reframe::{
    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
};
pub use crate::reframe_tracks::LOSS_HOLD;
use crate::reframe_tracks::{median, Chosen, SubjectBox, SubjectKind};
use crate::time::{
    one_frame, snap_down_to_frame, snap_to_frame, snap_up_to_frame, Fps, Ticks, TIMESCALE,
};

/// The ease to `where_empty` after a loss: 0.8 s.
pub const EMPTY_EASE: Ticks = TIMESCALE * 4 / 5;
/// How long a subject must be seen at every sample before the framing
/// returns to it from EMPTY: 0.6 s.
pub const RETURN_SEEN: Ticks = TIMESCALE * 3 / 5;
/// A cut places the new shot on its subject's median over this: 1 s.
pub const CUT_MEDIAN: Ticks = TIMESCALE;
/// Each of two people's boxes is widened by this about its centre before
/// their union is tested against the window.
pub const PAIR_WIDEN: f64 = 1.15;

/// The subject point's median reads ±0.5 s.
const MEDIAN_SPAN: Ticks = TIMESCALE / 2;
/// The shortest move: 0.4 s.
pub(crate) const MOVE_MIN: f64 = 0.4;
/// No move within 0.5 s of the last one's end…
pub(crate) const MOVE_SPACING: Ticks = TIMESCALE / 2;

impl FramingPath {
    /// (scale, x, y) at clip tick `t`: the segment ending at key i eases with
    /// key i's curve (`actions::ease`); before the first key its value, after
    /// the last its value.
    pub fn at(&self, t: Ticks) -> (f64, f64, f64) {
        let value = |k: &FramingKey| (k.scale, k.x, k.y);
        let Some(first) = self.keys.first() else {
            return (1.0, 0.0, 0.0);
        };
        let Some(i) = self.keys.iter().position(|k| k.t >= t) else {
            return value(self.keys.last().expect("not empty"));
        };
        if i == 0 {
            return value(first);
        }
        let (a, b) = (&self.keys[i - 1], &self.keys[i]);
        let e = ease(b.curve, (t - a.t) as f64 / (b.t - a.t) as f64);
        (
            a.scale + (b.scale - a.scale) * e,
            a.x + (b.x - a.x) * e,
            a.y + (b.y - a.y) * e,
        )
    }

    /// Keys whose (scale, x, y) differ from the previous key's.
    pub fn moves(&self) -> usize {
        self.keys
            .windows(2)
            .filter(|w| (w[0].scale, w[0].x, w[0].y) != (w[1].scale, w[1].x, w[1].y))
            .count()
    }
}

/// What the framing holds: a window centred on a source-canvas point, or
/// the whole picture fitted.
#[derive(Debug, Clone, Copy, PartialEq)]
enum At {
    Window(Point),
    Fit,
}

/// The keys as they are written, and the state they leave.
struct Writer<'a> {
    frame: &'a Frame,
    keys: Vec<FramingKey>,
    current: At,
    shows_fit: bool,
    last_end: Option<Ticks>,
}

impl Writer<'_> {
    fn key(&self, t: Ticks, at: At, curve: Curve) -> FramingKey {
        match at {
            At::Window(wc) => self.frame.key(t, wc, curve),
            At::Fit => self.frame.fit_key(t, curve),
        }
    }

    /// A hold key at `start` (unless the last key is there already) and the
    /// key `to` at `end` with `curve`.
    fn go(&mut self, start: Ticks, end: Ticks, to: At, curve: Curve) {
        if start > self.keys.last().expect("the first key").t {
            self.keys.push(self.key(start, self.current, Curve::Linear));
        }
        self.keys.push(self.key(end, to, curve));
        self.shows_fit |= to == At::Fit;
        self.current = to;
        self.last_end = Some(end);
    }

    fn running(&self, t: Ticks) -> bool {
        self.last_end.is_some_and(|end| t < end)
    }
}

/// The subject point and offset of a chosen sample (VR-22), its pair's
/// union standing in when both widened boxes fit the window (VR-24 (g)).
fn point_of(frame: &Frame, c: &Chosen, headroom: f64) -> Option<(SubjectKind, Point, Point)> {
    let (kind, b) = (c.kind?, c.subject?);
    let widened = |b: &SubjectBox| {
        let (cx, cy) = (b.x + b.w / 2.0, b.y + b.h / 2.0);
        let (w, h) = (b.w * PAIR_WIDEN, b.h * PAIR_WIDEN);
        (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
    };
    let pair = c.second.and_then(|other| {
        let (a, o) = (widened(&b), widened(&other));
        let (x0, y0) = (a.0.min(o.0), a.1.min(o.1));
        let (x1, y1) = (a.2.max(o.2), a.3.max(o.3));
        let (p0, p1) = (frame.point(c.t, x0, y0), frame.point(c.t, x1, y1));
//! `follow: cursor` — a screen recording framed on its recorded pointer
//! (road map "creator-jobs" VR5, spec §11 VR-50). Pure; `edit_reframe.rs`'s
//! op writes the path as it writes every framing (`reframe_compose.rs`).
//!
//! **The points.** `subjects.cursor` (`reframe_subjects.rs`), in forward-media
//! source ticks, is put into clip time by [`cursor_in_clip_time`]: kept in the
//! played window, mapped through `clip_source_time.rs`'s one mapping, one
//! point per clip tick with `click` and `typing` OR'ed over the points merged.
//!
//! **The window** is `reframe.rs`'s `Frame` at the request's zoom from the
//! current canvas: a point lands on the source canvas through the placement in
//! force (`Frame::point`, VR-27 (a)) and the desired centre is that point
//! clamped (`Frame::clamp`) — no headroom, no offset, since a pointer is a
//! point and not a head.
//!
//! **The moves** ([`CURSOR_TUNING`]): the first key on the first point; a
//! dead zone ±0.20 of the window's width and ±0.12 of its height around the
//! window's target, wider than a face's 0.15 because a pointer wanders where a
//! face holds still; a down click outside it ARRIVES — its move ends on the
//! click's frame, planned back from it at 0.8 window widths a second (at
//! least 0.4 s) and started no earlier than the last move's end; any other
//! point outside it starts VR-23's move unless one runs, it is within 0.5 s of
//! the last move's end with the pointer still in the window, the move would
//! end after a pending arrival's start, or the pointer is typing — a typing
//! stretch holds the window, where a click inside one still arrives. No cut,
//! no `fit`: `where_empty` and `backdrop` never act on it.

use crate::clip_source_time::{clip_time_of_source, in_played_window, Round};
use crate::model::{Clip, Curve, MediaKind, Project, Source};
use crate::reframe::{
    Frame, FramingKey, FramingPath, FramingRequest, FramingTuning, Point, WhereEmpty,
};
use crate::reframe_path::{span, MOVE_MIN, MOVE_SPACING};
use crate::reframe_subjects::CursorPoint;
use crate::reframe_tracks::Follow;
use crate::time::{snap_to_frame, Fps, Ticks, TIMESCALE};

/// VR-50 (d): the dead zone ±0.20 of the window's width (a face's is 0.15)
/// and ±0.12 of its height, 0.8 window widths a second, no headroom.
pub const CURSOR_TUNING: FramingTuning = FramingTuning {
    dead_zone_width: 0.20,
    dead_zone_height: 0.12,
    speed: 0.8,
    headroom: 0.0,
};

/// VR-50 (a): the points in clip time — kept in the played window, mapped
/// with `Round::Down`, sorted by (clip tick, media tick), one per clip tick
/// (the earliest media tick's position) with `click` and `typing` OR'ed over
/// the points it stands for. Empty for a clip that is not a media clip.
pub(crate) fn cursor_in_clip_time(
    clip: &Clip,
    project: &Project,
    points: &[CursorPoint],
) -> Vec<CursorPoint> {
    let Source::Media { media, .. } = clip.source else {
        return Vec::new();
    };
    let Some(media) = project.media(media) else {
        return Vec::new();
    };
    let mut mapped: Vec<(Ticks, Ticks, CursorPoint)> = points
        .iter()
        .filter(|p| in_played_window(clip, media, p.t))
        .filter_map(|p| clip_time_of_source(clip, media, p.t, Round::Down).map(|c| (c, p.t, *p)))
        .collect();
    mapped.sort_by_key(|&(c, m, _)| (c, m));
    let mut out: Vec<CursorPoint> = Vec::with_capacity(mapped.len());
    for (c, _, p) in mapped {
        match out.last_mut() {
            Some(last) if last.t == c => {
                last.click |= p.click;
                last.typing |= p.typing;
            }
            _ => out.push(CursorPoint { t: c, ..p }),
        }
    }
    out
}

//! `reframe_clip {follow: speaker}` (road map "creator-jobs" VR6a, spec §11
//! VR-60, VR-61), pure: a wide two-person clip framed on the face whose
//! microphone is speaking. The app hands the op who speaks when
//! (`subjects.turns`, Switch by Speaker's reading of the microphones) and
//! each face's mouth opening (`mouth`); `reframe_speaker_match.rs` matches
//! faces to microphones (its items re-exported here), and this module turns
//! the turns into held segments and writes them as cuts through
//! `reframe_path.rs`'s `write_keys`.
//!
//! - **Segments** (VR-61 (e)). Cut at the turns' bounds: one speaker frames
//!   their face, nobody holds the last (the first labelled one's at the
//!   start), two or more frame the pair (the face already framed first) when
//!   both widened median boxes fit the window, else the face already
//!   framed; equal neighbours coalesce, and the earliest segment shorter
//!   than [`SPEAKER_HOLD`] joins the one before it (the first, the one
//!   after) until none is short.
//! - **The path** (VR-61 (f)). Each segment start after 0 is a hard cut (a
//!   shot to `write_keys`), every sample choosing its segment's face, the
//!   pair's other face as `second`.
//!
//! VR-60 (d)'s sentences are all here: [`mics_refusal`] (the subject-free
//! ones, which `edit_reframe.rs` asks after (5)–(6)) and
//! [`plan_speaker_framing`]'s `Err`s (those that need `subjects`), each in
//! its order.

use crate::model::{Clip, MediaKind, Project, Source};
use crate::reframe::{
    in_clip_time, Frame, FramingPath, FramingRequest, WhereEmpty, FRAMING_TUNING,
};
use crate::reframe_path::{write_keys, PAIR_WIDEN};
pub use crate::reframe_speaker_match::{
    clip_speaker_match, pearson, speaker_match, sure, SpeakerFace, SpeakerMatch, ACTIVITY_SPAN,
    FACE_SHARE, MAX_SPEAKERS, SPEAKER_AGREEMENT,
};
use crate::reframe_speaker_match::{clip_turns, covered, faces_of, matched, median_box};
use crate::reframe_subjects::{Subjects, Turn};
use crate::reframe_tracks::{centre, Chosen, Follow, SubjectKind};
use crate::time::{Ticks, TIMESCALE};

/// The shortest segment that stands: 2 s (VR-61 (e)).
pub const SPEAKER_HOLD: Ticks = 2 * TIMESCALE;

/// VR-60 (d)'s subject-free refusals, in order: the count, a repeat, a
/// microphone with no sound of a media file or the framed clip, one with
/// its sound off, two on a track, then `mic_faces`.
pub(crate) fn mics_refusal(
    project: &Project,
    id: u32,
    mics: Option<&[u32]>,
    mic_faces: Option<&[u32]>,
) -> Option<String> {
    let mics = mics.unwrap_or(&[]);
    if !(2..=4).contains(&mics.len()) {
        return Some(format!(
            "follow speaker needs two to four microphone clips in mics, not {}",
            mics.len()
        ));
    }
    if let Some(&m) = mics
        .iter()
        .iter()
        .enumerate()
        .find(|(i, m)| mics[..*i].contains(m))
        .map(|(_, m)| m)
    {
        return Some(format!("clip {m} is named twice in mics"));
    }
    let clips: Vec<&Clip> = mics.iter().filter_map(|&m| project.clip(m)).collect();
    for c in &clips {
        if c.id == id {
            return Some(format!(
                "clip {id} is the clip being framed, so it cannot be one of its microphones"
            ));
        }
        let sounds = match c.source {
            Source::Media { media, .. } => project.media(media).is_some_and(|m| m.has_audio),
            _ => false,
        };
        if !sounds {
            return Some(format!(
                "clip {} has no sound from a media file, so it cannot be a microphone",
                c.id
            ));
        }
    }
    if let Some(c) = clips.iter().find(|c| !c.enabled.audio) {
        return Some(format!(
            "clip {}'s sound is off, so it never says who is talking; turn its sound on or \
             leave it out of mics",
            c.id
        ));
    }
    for (n, a) in clips.iter().enumerate() {
        if let Some(b) = clips[..n].iter().find(|b| b.track == a.track) {
            return Some(format!(
                "clips {} and {} are both on track {}; each microphone needs its own track",
                b.id, a.id, a.track
            ));
        }
    }
    let faces = mic_faces?;
    if faces.len() != mics.len() {
        return Some(format!(
            "mic_faces needs one face number for each of the {} microphones in mics, not {}",
            mics.len(),
            faces.len()
        ));
    }
    if faces.contains(&0) {
        return Some("mic_faces names face 0; faces are numbered from 1".to_string());
    }
    if let Some(&f) = faces
        .iter()
        .enumerate()
        .find(|(i, f)| faces[..*i].contains(f))
        .map(|(_, f)| f)
    {
        return Some(format!(
            "mic_faces names face {f} twice; each microphone needs its own face"
        ));
    }
    None
}

/// What a segment frames: a face (its index), or a pair (current, other).
#[derive(Debug, Clone, Copy, PartialEq)]
enum Label {
    Face(usize),
    Both(usize, usize),
}

#[derive(Debug, Clone, Copy, PartialEq)]
struct Segment {
    from: Ticks,
    to: Ticks,
    label: Label,
}

fn coalesced(segments: Vec<Segment>) -> Vec<Segment> {
    let mut out: Vec<Segment> = Vec::new();
    for s in segments {
        match out.last_mut() {
            Some(last) if last.label == s.label => last.to = s.to,
            _ => out.push(s),
        }
    }
    out
}

/// VR-61 (e): the segments over `[0, duration)`; `faces[m]` is mic m's face
/// index, `fits` whether a pair fits the window over a span. `None` with no
/// turn inside the clip.
fn segments(
    duration: Ticks,
    turns: &[Turn],
    mics: &[u32],
    faces: &[usize],
    fits: impl Fn(usize, usize, Ticks, Ticks) -> bool,
) -> Option<Vec<Segment>> {
    let mut bounds: Vec<Ticks> = vec![0, duration];
    bounds.extend(
        turns
            .iter()
            .flat_map(|u| [u.from, u.to])
            .map(|t| t.clamp(0, duration)),
    );
    bounds.sort_unstable();
    bounds.dedup();
    let mut raw: Vec<(Ticks, Ticks, Option<Label>)> = Vec::new();
    let mut previous: Option<Label> = None;
    for w in bounds.windows(2) {
        let (a, b) = (w[0], w[1]);
        let active: Vec<usize> = (0..mics.len())
            .filter(|&m| covered(turns, mics[m], a))
            .map(|m| faces[m])
            .collect();
        let label = match active.as_slice() {
            [] => None,
            [f] => Some(Label::Face(*f)),
            _ => {
                let held = previous.map(|l| match l {
                    Label::Face(f) | Label::Both(f, _) => f,
                });
                let current = held.filter(|f| active.contains(f)).unwrap_or(active[0]);
                let other = *active.iter().find(|&&f| f != current).expect("two faces");
                Some(if fits(current, other, a, b) {
                    Label::Both(current, other)
                } else {
                    Label::Face(current)
                })
            }
        };
        if label.is_some() {
            previous = label;
        }
        raw.push((a, b, label.or(previous)));
    }
    let first = raw.iter().find_map(|r| r.2)?;
    let mut out = coalesced(
        raw.into_iter()
            .map(|(from, to, l)| Segment {
                from,
                to,
                label: l.unwrap_or(first),
            })
            .collect(),
    );
    // SW-22 (h)'s merge: the earliest short segment joins the one before
    // it, the first the one after, until none is short.
    while out.len() > 1 {
        let Some(i) = out.iter().position(|s| s.to - s.from < SPEAKER_HOLD) else {
            break;
        };
        if i > 0 {
            out[i - 1].to = out[i].to;
        } else {
            out[1].from = out[0].from;
        }
        out.remove(i);
        out = coalesced(out);
    }
    Some(out)
}

/// The framing (spec §11 VR-60, VR-61): `mics` checked by the op before;
/// `Err` is the refusal's sentence, in VR-60 (d)'s order.
pub fn plan_speaker_framing(
    project: &Project,
    clip: u32,
    subjects: &Subjects,
    mics: &[u32],
    mic_faces: Option<&[u32]>,
    zoom: f64,
    where_empty: WhereEmpty,
) -> Result<FramingPath, String> {
    let picture = || format!("clip {clip}'s crop or scale leaves no picture to frame");
    let c = project.clip(clip).ok_or_else(picture)?;
    let Source::Media { media, .. } = c.source else {
        return Err(picture());
    };
    if !project
        .media(media)
        .is_some_and(|m| m.kind == MediaKind::Video && m.has_video)
    {
        return Err(picture());
    }
    if let Some((i, turn)) = subjects
        .turns
        .iter()
        .enumerate()
        .find(|(_, u)| !mics.contains(&u.mic))
    {
        return Err(format!(
            "subjects turns[{i}] names clip {}, which is not one of mics",
            turn.mic
        ));
    }
    let request = FramingRequest {
        follow: Follow::Face,
        zoom,
        from_width: project.canvas.width,
        from_height: project.canvas.height,
        where_empty,
    };
    let mut frame = Frame::of(project, c, &request).ok_or_else(picture)?;
    let (samples, shots) = in_clip_time(c, project, subjects);
    if let Some(&shot) = shots.first() {
        return Err(format!(
            "clip {clip} changes shot at {}; follow speaker frames one wide shot — split the \
             clip at its shot changes first",
            project.layout_timecode(c.start + shot)
        ));
    }
    if !c.actions.is_empty() {
        frame.placed = samples
            .iter()
            .map(|s| {
                let p = project.evaluate_clip(c, s.t).video;
                (s.t, p.scale, p.x, p.y)
            })
            .collect();
    }
    let turns = clip_turns(c, &subjects.turns);
    let faces = faces_of(&samples);
    let plural = |n: usize| if n == 1 { "face" } else { "faces" };
    let Some(found) = matched(&samples, &faces, &turns, mics) else {
        return Err(format!(
            "clip {clip} shows {} {} for {} microphones; follow speaker needs a face for each \
             microphone",
            faces.len(),
            plural(faces.len()),
            mics.len()
        ));
    };
    if let Some(&f) = mic_faces
        .into_iter()
        .flatten()
        .find(|&&f| f as usize > faces.len())
    {
        return Err(format!(
            "mic_faces names face {f}, but clip {clip} shows only {} {}",
            faces.len(),
            plural(faces.len())
        ));
    }
    let no_turn = || {
        format!(
            "clip {clip} has no turn of its microphones inside it, so there is no speaker to \
             follow"
        )
    };
    if turns.is_empty() {
        return Err(no_turn());
    }
    let assignment: Vec<u32> = match mic_faces {
        Some(given) => given.to_vec(),
        None if found.sure => found.assignment.clone(),
        None => {
            let least = (0..mics.len())
                .map(|m| found.agreement[m][found.assignment[m] as usize - 1])
                .fold(f64::INFINITY, f64::min);
            let places: Vec<String> = found
                .faces
                .iter()
                .enumerate()
                .map(|(n, f)| {
                    let at = format!("face {} at {} %", f.face, (f.x * 100.0).round());
                    if n == 0 {
                        format!("{at} across the picture")
                    } else {
                        at
                    }
                })
                .collect();
            return Err(format!(
                "clip {clip}'s faces do not show which microphone is whose: the best match \
                 agrees only {least:.2} (under {SPEAKER_AGREEMENT}); name each microphone's face \
                 with mic_faces, in mics' order — {}",
                places.join(", ")
            ));
        }
    };
    let index: Vec<usize> = assignment.iter().map(|&f| f as usize - 1).collect();
    let fits = |a: usize, b: usize, from: Ticks, to: Ticks| {
        let widened = |f: usize| {
            let m = median_box(&faces[f], &samples, from, to);
            let (cx, cy) = centre(&m);
            let (w, h) = (m.w * PAIR_WIDEN, m.h * PAIR_WIDEN);
            (cx - w / 2.0, cy - h / 2.0, cx + w / 2.0, cy + h / 2.0)
        };
        let (p, q) = (widened(a), widened(b));
        let p0 = frame.point(from, p.0.min(q.0), p.1.min(q.1));
        let p1 = frame.point(from, p.2.max(q.2), p.3.max(q.3));
        p1.0 - p0.0 <= frame.window.0 && p1.1 - p0.1 <= frame.window.1
    };
    let segments = segments(c.duration, &turns, mics, &index, fits).ok_or_else(no_turn)?;
    let cuts: Vec<Ticks> = segments.iter().map(|s| s.from).filter(|&t| t > 0).collect();
    let chosen: Vec<Chosen> = samples
        .iter()
        .enumerate()
        .map(|(i, s)| {
            let n = segments
                .partition_point(|g| g.to <= s.t)
                .min(segments.len() - 1);
            let (face, other) = match segments[n].label {
                Label::Face(f) => (f, None),
                Label::Both(f, o) => (f, Some(o)),
            };
            Chosen {
                t: s.t,
                kind: Some(SubjectKind::Face),
                track: Some(face as u32 + 1),
                subject: faces[face].at(i),
                identity: Some(face as u32 + 1),
                lost: false,
                second: other.and_then(|o| faces[o].at(i)),
            }
        })
        .collect();
    Ok(write_keys(
        &frame,
        &chosen,
        &cuts,
        c.duration,
        project.canvas.fps,
        &request,
        &FRAMING_TUNING,
    ))
}

import Foundation

/// Make Vertical's `follow: speaker` (road map "creator-jobs" VR6b, spec §11 VR-64, VR-66): which
/// tracks are microphones, which pictures are framed by who is talking and with which of them,
/// the turns filled on main, and what the sheet reads to confirm the match. The step itself is
/// `VerticalVersion+Plan.swift`'s; the match is the core's (`ReelProject.speakerMatch`, VR-65).
/// Swift restates none of VR-60's refusals: a microphone the core will not take reaches the
/// clip's entry in its own sentence. Names no `rc_*`.
extension VerticalVersion {
    /// A track the sheet offers as a microphone (VR-66 (b)): its name, and the clip that stands
    /// for it in `mics`, the earliest that plays a sound file.
    struct Microphone: Equatable {
        let track: UInt32
        let name: String
        let clip: UInt32
    }

    /// A picture framed by who is talking (VR-64 (b)), with its own microphones — one clip per
    /// microphone track that sounds under it, in `mics`' order — and their faces when given.
    struct SpeakerClip: Equatable {
        let clip: UInt32
        let mics: [UInt32]
        let micFaces: [UInt32]?
    }

    /// A clip the step framed with `speaker` (VR-64 (f)): its microphones and the face of each,
    /// given or the core's own match.
    struct SpeakerFraming: Equatable {
        let clip: UInt32
        let mics: [UInt32]
        let faces: [UInt32]
    }

    /// What the sheet reads for Speaker (VR-66 (c)): a refusal's sentence, or the subjects with
    /// their turns, the reference clip and the core's match on it.
    enum SpeakerReading {
        case refused(String)
        case ready(subjects: [UInt32: [String: Any]], reference: UInt32, match: SpeakerMatch?)
    }

    /// The tool's refusal with no speaker clip (VR-64 (e)).
    static let noSpeakerClip =
        "make_vertical_version found no full-frame movie clip playing beside two of the "
        + "microphones in mics, so nobody is framed by who is talking."

    /// The sheet's sentence with no speaker clip (VR-66 (c)).
    static let noSpeakerClipSheet =
        "No full-frame movie clip plays beside two of the ticked microphones, so nobody can be "
        + "framed by who is talking."

    /// VR-66 (b): each track, front to back, holding a clip `SpeakerSwitch.playsSound` takes
    /// whose media has no picture; its `clip` the earliest such clip (ties: the lower id).
    static func microphones(_ project: ReelProject) -> [Microphone] {
        let snapshot = project.snapshot
        return snapshot.tracks.reversed().compactMap { track in
            let sounding = snapshot.clips(onTrack: track.id).filter {
                SpeakerSwitch.playsSound($0, in: snapshot)
                    && snapshot.media(for: $0)?.hasVideo == false
            }
            guard let first = sounding.min(by: { ($0.start, $0.id) < ($1.start, $1.id) })
            else { return nil }
            return Microphone(track: track.id, name: track.name, clip: first.id)
        }
    }

    /// VR-64 (b): the present, cursor-free class-3 media pictures off the microphone tracks whose
    /// span overlaps a clip with audio on at least two of them, in id order; [] unless `follow`
    /// is `speaker`. Each one's `mics` are, per microphone in order, the media clip with audio on
    /// that microphone's track with the greatest overlap (ties: the earlier start, then the lower
    /// id); a track with none is left out with its `micFaces` entry. A `micFaces` that is not
    /// one per microphone is passed as given, for the core to refuse in its own sentence.
    static func speakerClips(
        _ project: ReelProject, settings: VerticalSettings, missing: Set<UInt32>
    ) -> [SpeakerClip] {
        guard settings.follow == .speaker else { return [] }
        let snapshot = project.snapshot
        let micTracks = settings.mics.map { snapshot.clip($0)?.track }
        let onMics = Set(micTracks.compactMap { $0 })
        let given = settings.micFaces
        let filters = given.map { $0.count == settings.mics.count } ?? false
        var out: [SpeakerClip] = []
        for id in mediaPictures(classify(project), in: snapshot) where !missing.contains(id) {
            guard let clip = snapshot.clip(id), snapshot.media(for: clip)?.cursor == nil,
                !onMics.contains(clip.track)
            else { continue }
            var mics: [UInt32] = []
            var faces: [UInt32] = []
            for (n, track) in micTracks.enumerated() {
                guard let track, let best = loudest(on: track, under: clip, in: snapshot)
                else { continue }
                mics.append(best)
                if filters, let given { faces.append(given[n]) }
            }
            guard mics.count >= 2 else { continue }
            out.append(SpeakerClip(clip: id, mics: mics, micFaces: filters ? faces : given))
        }
        return out
    }

    /// The media clip with audio on `track` that overlaps `clip` most (ties: the earlier start,
    /// then the lower id); nil when none overlaps it.
    private static func loudest(
        on track: UInt32, under clip: ClipSnapshot, in snapshot: ProjectSnapshot
    ) -> UInt32? {
        func overlap(_ other: ClipSnapshot) -> Ticks {
            max(0, min(other.end, clip.end) - max(other.start, clip.start))
        }
        let sounding = snapshot.clips(onTrack: track).filter { other in
            guard case .media = other.source, snapshot.media(for: other)?.hasAudio == true
            else { return false }
            return overlap(other) > 0
        }
        return sounding.min { a, b in
            (-overlap(a), a.start, a.id) < (-overlap(b), b.start, b.id)
        }?.id
    }

    /// VR-64 (d): each speaker clip's subjects with `turns`, read through `FramingSpeaker.turns`
    /// over its own microphones; a clip with no subjects is left as it is. Main thread (it reads
    /// the document); throws `FramingSpeaker.Refusal`.
    static func withTurns(
        _ subjects: [UInt32: [String: Any]], speaker: [SpeakerClip], document: ProjectDocument
    ) throws -> [UInt32: [String: Any]] {
        var out = subjects
        let snapshot = document.editedProject.snapshot
        for entry in speaker {
            guard var own = out[entry.clip], let clip = snapshot.clip(entry.clip) else { continue }
            own["turns"] = try FramingSpeaker.turns(
                document: document, clip: clip, mics: entry.mics)
            out[entry.clip] = own
        }
        return out
    }

    /// VR-66 (c): the sheet's reading for Speaker on `project` with the ticked microphones in
    /// `settings.mics` — the turns filled, then the core's match on the reference clip (the
    /// longest speaker clip, ties to the lower id) with its own microphones. Main thread.
    static func speakerReading(
        document: ProjectDocument, project: ReelProject, settings: VerticalSettings,
        subjects: [UInt32: [String: Any]], missing: Set<UInt32>
    ) -> SpeakerReading {
        let clips = speakerClips(project, settings: settings, missing: missing)
        let snapshot = project.snapshot
        let reference = clips.min { a, b in
            let (da, db) = (snapshot.clip(a.clip)?.duration ?? 0, snapshot.clip(b.clip)?.duration ?? 0)
            return (-da, a.clip) < (-db, b.clip)
        }
        guard let reference else { return .refused(noSpeakerClipSheet) }
        let filled: [UInt32: [String: Any]]
        do {
            filled = try withTurns(subjects, speaker: clips, document: document)
        } catch let refusal as FramingSpeaker.Refusal {
            return .refused(refusal.sentence)
        } catch {
            return .refused(error.localizedDescription)
        }
        let match = filled[reference.clip].flatMap {
            project.speakerMatch(clip: reference.clip, mics: reference.mics, subjects: $0)
        }
        return .ready(subjects: filled, reference: reference.clip, match: match)
    }
}
