/// `make_vertical_version` (spec §11 VR-36, VR-37; road map "creator-jobs" VR3a): the project's
/// 9:16, 4:5 or 1:1 version made by `VerticalVersion.plan`, opened as a copy through
/// `ProjectDocument.verticalCopy` (the default; saved at `path` when given) or, with
/// `copy: false`, applied to the addressed project in place as one undo step "Make Vertical".
/// Its UI path is File ▸ Make Vertical Version… (road map creator-jobs VR3b, spec §11 VR-39:
/// `EditorViewController+VerticalVersion.swift` and `VerticalVersionSheetController.swift`). It
/// never asks the person and reads no `UserDefaults`.
///
/// **Runs on the SERVER thread** (`creatorOffMainTools`), in hops:
/// - the first main hop resolves and refuses in VR-36's order, runs a DRY plan with no
///   subjects (so the core's own error for a bad argument is answered before any analysis is
///   asked for) and, for a following kind, asks `FramingAnalysis.requests` on the SOURCE over
///   the media pictures whose file is present (VR-37);
/// - the wait is `reframe_clip`'s (`waitForAnalysis`); past CJ-25's bound the answer is
///   `analyzing` and nothing is made; the subjects are read off main from the source's cache;
/// - the last main hop refuses a changed project or scope, plans on the current handle and
///   applies in place or opens the copy; with `path` the copy is saved on the server thread.
///
/// A media picture whose media has a cursor file (`analysisTargets`' `cursor`, spec §11 VR-51)
/// is never analysed: its cursor is read off main beside the analysis's subjects
/// (`FramingCursor.subjects`), and the plan follows it with `replace: true` (VR-52).
///
/// `follow: speaker` (road map creator-jobs VR6b, spec §11 VR-64) takes `mics` and `mic_faces`,
/// analyses as a following kind does, and frames each speaker clip (`VerticalVersion.speakerClips`)
/// on whoever is talking: the last main hop fills their turns (`VerticalVersion.withTurns`,
/// Switch by Speaker's reading), a `FramingSpeaker.Refusal` refusing the call, and the answer
/// carries `speaker`. Its UI path is the sheet's Follow Speaker.
extension AgentServer {

    /// What the first main hop resolves.
    private struct VerticalCall {
        let document: ProjectDocument
        let settings: VerticalSettings
        let copy: Bool
        let url: URL?
        /// Media pictures whose media file is missing (kept, not followed).
        let missing: Set<UInt32>
        /// The media pictures whose subjects are read: the following kinds' only.
        let targets: [UInt32]
        /// The media pictures whose cursor is read (VR-51): the following kinds' only.
        let cursor: [UInt32]
        let requests: [AnalysisRequest]
        let cacheDir: URL?
        let asked: ReelProject
        let scope: UInt32?
    }

    /// The last main hop's answer: in place, the finished answer; a copy, the document.
    private enum VerticalOutcome {
        case applied(String)
        case copied(
            (
                document: ProjectDocument, carried: DerivedCarry.Report,
                templates: VerticalVersion.TemplateReport
            ))
    }

    func makeVerticalVersion(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "make_vertical_version must run on the server thread — its name is "
                    + "missing from AgentServer.creatorOffMainTools.")
        }
        let call = try onMain { try self.resolveVertical(a) }
        var subjects: [UInt32: [String: Any]] = [:]
        if !call.requests.isEmpty {
            let clips = call.targets.count
            if let analyzing = try waitForAnalysis(
                call.requests, document: call.document, stop: stop, unmade: "nothing was made",
                note: { percent in
                    "Still analyzing the media of \(clips) \(clips == 1 ? "clip" : "clips") "
                        + "(\(percent) %); call make_vertical_version again to make the version."
                })
            {
                return analyzing
            }
        }
        if let cacheDir = call.cacheDir, !call.targets.isEmpty {
            subjects = FollowSubject.subjects(call.targets, in: call.asked, cacheDir: cacheDir)
        }
        subjects.merge(FramingCursor.subjects(call.cursor, in: call.asked)) { _, new in new }
        var fields: [String: Any] = ["cached": call.requests.isEmpty]
        let outcome: VerticalOutcome = try onMain {
            let document = call.document
            guard document.project === call.asked, document.scope == call.scope else {
                throw ToolError(
                    message: "the project changed while make_vertical_version read the "
                        + "analysis, so nothing was made. Call make_vertical_version again.")
            }
            // VR-64 (d): who talks when, read on this hop from the microphones' caches.
            var filled = subjects
            do {
                filled = try VerticalVersion.withTurns(
                    subjects,
                    speaker: VerticalVersion.speakerClips(
                        document.project, settings: call.settings, missing: call.missing),
                    document: document)
            } catch let refusal as FramingSpeaker.Refusal {
                throw ToolError(message: "make_vertical_version was refused: " + refusal.sentence)
            }
            let plan = try self.verticalPlan(
                document.project, call.settings, subjects: filled, missing: call.missing)
            guard call.copy else {
                // In place nothing is written: the old template copies are listed (VR-44 (c)).
                let survey = VerticalVersion.templateSurvey(
                    document.project, store: document.graphicStore)
                fields.merge(
                    VerticalVersion.answerFields(
                        plan, templates: VerticalVersion.templateReport(survey, copy: false))
                ) { _, new in new }
                return .applied(
                    try self.editResult(document, VerticalVersion.actionName, plan.ops, fields))
            }
            do {
                let made = try ProjectDocument.verticalCopy(
                    from: document, plan: plan, shape: call.settings.shape, path: call.url,
                    display: Self.derivedDisplay)
                // The copy's own report: what it updated and what it listed.
                fields.merge(VerticalVersion.answerFields(plan, templates: made.templates)) {
                    _, new in new
                }
                return .copied(made)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
        }
        let made: (
            document: ProjectDocument, carried: DerivedCarry.Report,
            templates: VerticalVersion.TemplateReport
        )
        switch outcome {
        case .applied(let answer): return answer
        case .copied(let copy): made = copy
        }
        if let url = call.url {
            try save(made.document, to: url, operation: .saveOperation)
            fields["saved"] = url.path
        }
        return try onMain {
            var result: [String: Any] = ["ok": true]
            result.merge(fields) { _, new in new }
            result["carried"] = [
                "files": made.carried.files, "bytes": made.carried.bytes,
                "seconds": made.carried.seconds,
            ]
            result["project"] = self.summary(made.document)
            return try self.jsonResult(result)
        }
    }

    /// The plan on `project`, its refusal thrown in the step's own sentence and the core's
    /// invalid input as its message. Main thread.
    private func verticalPlan(
        _ project: ReelProject, _ settings: VerticalSettings, subjects: [UInt32: [String: Any]],
        missing: Set<UInt32>
    ) throws -> VerticalVersion.Plan {
        let answer: VerticalVersion.Answer
        do {
            answer = try VerticalVersion.plan(
                project, settings: settings, subjects: subjects, missing: missing)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        switch answer {
        case .plan(let plan): return plan
        case .refused(let why): throw ToolError(message: why)
        }
    }

    /// VR-36's first hop, its refusals in order.
    private func resolveVertical(_ a: [String: Any]) throws -> VerticalCall {
        let document = try target(a)
        let shape = try requiredEnumArg(a, "shape", VerticalShape.self)
        var follow = FramingFollow.subject
        if let raw = try stringArg(a, "follow") {
            guard let kind = FramingFollow(rawValue: raw), VerticalVersion.follows.contains(kind)
            else {
                throw ToolError(
                    message: "follow must be subject, face, person, salient, speaker or center, "
                        + "not \(raw).")
            }
            follow = kind
        }
        let zoom = try doubleArg(a, "zoom") ?? 1
        let whereEmpty = try enumArg(a, "where_empty", FramingWhereEmpty.self) ?? .fit
        let copy = try boolArg(a, "copy") ?? true
        let captions = try boolArg(a, "captions") ?? true
        let path = try stringArg(a, "path")
        guard document.scope == nil else {
            throw ToolError(
                message: "make_vertical_version works on the top-level timeline: set_scope with "
                    + "no nest first.")
        }
        if path != nil, !copy {
            throw ToolError(
                message: "make_vertical_version writes path only for a copy: drop path, or copy.")
        }

        }
        let url = path.map {
            Self.destinationURL($0, extension: ProjectDocument.projectFileExtension)
        }
        if let url {
            try refuseHeldPath(url, except: nil, tool: "make_vertical_version")
            guard !FileManager.default.fileExists(atPath: url.path) else {
                throw ToolError(
                    message: "\(url.path) already exists, so make_vertical_version did not "
                        + "write there: pass a new path.")
            }
        }
        let project = document.project
        let canvas = project.snapshot.canvas
        let size = shape.size(from: canvas)
        guard size.width != canvas.width || size.height != canvas.height else {
            throw ToolError(
                message: "the canvas is already \(canvas.width) × \(canvas.height), so there is "
                    + "no \(shape.rawValue) version to make.")
        }
        do {
            if case .refused(let why) = try VerticalVersion.opening(
                project, width: size.width, height: size.height)
            {
                throw ToolError(message: why)
            }
        } catch let error as ToolError {
            throw error
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        // VR-64 (a), (e): the microphones, read only with speaker.
        var mics: [UInt32] = []
        var micFaces: [UInt32]?
        if follow == .speaker {
            guard let given = try numbersArg(a, "mics"), !given.isEmpty else {
                throw ToolError(
                    message: "make_vertical_version's follow speaker needs mics: two to four "
                        + "clips, one on each microphone's track.")
            }
            for id in given { _ = try clipArg(["clip": Int(id)], "clip", document) }
            mics = given
            micFaces = try numbersArg(a, "mic_faces")
        }
        let settings = VerticalSettings(
            shape: shape, follow: follow, zoom: zoom, whereEmpty: whereEmpty, captions: captions,
            mics: mics, micFaces: micFaces)
        let (present, missing, cursor) = VerticalVersion.analysisTargets(
            project, urls: document.mediaURLs())
        if follow == .speaker,
            VerticalVersion.speakerClips(project, settings: settings, missing: missing).isEmpty
        {
            throw ToolError(message: VerticalVersion.noSpeakerClip)
        }
        // The dry plan: the core's error for a bad argument, before any analysis. Its
        // refusal and its plan are discarded.
        do {
            _ = try VerticalVersion.plan(
                project, settings: settings, subjects: [:], missing: missing)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        let analysed = VerticalVersion.analyses(follow)
        let targets = analysed ? present : []
        var requests: [AnalysisRequest] = []
        var cacheDir: URL?
        if !targets.isEmpty {
            guard let folder = document.cacheDirectory else {
                throw ToolError(
                    message: ProjectDocument.AnalysisRequestError.noCache.localizedDescription)
            }
            cacheDir = folder
            do {
                requests = try FramingAnalysis.requests(
                    clips: targets, in: document, project: project)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
        }
        return VerticalCall(
            document: document, settings: settings, copy: copy, url: url, missing: missing,
            targets: targets, cursor: analysed ? cursor : [],
            requests: requests, cacheDir: cacheDir, asked: project, scope: document.scope)
    }

    /// `relay_captions` (road map "creator-jobs" VR4a, spec §11 VR-45): the word caption
    /// tracks of the container `set_scope` has open re-paged on its canvas as one undo step
    /// "Re-lay Captions" — what File ▸ Re-lay Captions for This Canvas does
    /// (`EditorViewController+RelayCaptions.swift`). Main thread; no `scope` argument, since
    /// dispatch reads `scope` only for op names; it plans on `editedProject` and
    /// `performGroupedEdit` addresses the ops.
    func relayCaptions(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let planned: (ops: [ReelOp], outcome: CaptionRelayout.Outcome)
        do {
            planned = try CaptionRelayout.plan(document.editedProject)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        guard !planned.ops.isEmpty else {
            let kept = planned.outcome.kept.map { "\"\($0.name)\": \($0.reason)" }
            throw ToolError(
                message: "relay_captions found no caption track it can re-lay: "
                    + (kept.isEmpty
                        ? "there is no track named Captions holding only text clips"
                        : kept.joined(separator: "; ")))
        }
        return try editResult(
            document, CaptionRelayout.actionName, planned.ops,
            CaptionRelayout.answerFields(planned.outcome))
    }
}
import Foundation

/// Make Vertical's step (spec §11 VR-34): `opening` is the canvas and the "Backgrounds" track,
/// `plan` the whole step on one `SwitchAngle.Trial`, each op TRIED on the trial's handle and
/// only its answer deciding the clip's entry. The classes are `VerticalVersion.swift`'s; step
/// 3b, the camera layouts re-laid, is `VerticalVersion+Layouts.swift`'s (VR-53 (d)); step (6),
/// the word caption tracks re-paged on the new canvas, is `CaptionRelayout`'s (VR-40 (f)); the
/// summary is `VerticalVersion+Summary.swift`'s; `follow: speaker`'s clips and turns are
/// `VerticalVersion+Speaker.swift`'s (VR-64). Throws only the core's invalid input. Names no
/// `rc_*`.
extension VerticalVersion {

    /// What the step did to one clip, and why when it did less than asked.
    struct Entry: Equatable {
        let clip: UInt32
        let treatment: Treatment
        let reason: String?
    }

    /// The step: its ops and the handle they make, the new size, one entry per classed clip
    /// in id order, whether Backgrounds is kept, the further tracks the core made behind it,
    /// and VR-27 (f)'s counts over the framed clips.
    struct Plan {
        let ops: [ReelOp]
        let project: ReelProject
        let width: Int
        let height: Int
        let entries: [Entry]
        let backgrounds: Bool
        let moreTracks: Int
        let reEased: Int
        let carried: Int
        /// Step (6)'s caption tracks, re-laid and kept; nil with `captions` false.
        let captions: CaptionRelayout.Outcome?
        /// The clips followed by their cursor, in id order (spec §11 VR-52).
        let cursor: [UInt32]
        /// Step 3b's re-laid switches, in time order, then camera id (spec §11 VR-54).
        let relaid: [Relaid]
        /// The clips framed by who is talking, in id order (spec §11 VR-64 (f)).
        let speaker: [SpeakerFraming]
    }

    enum Answer {
        case plan(Plan)
        case refused(String)
    }

    enum Opening {
        case opened(SwitchAngle.Trial, backgrounds: UInt32)
        case refused(String)
    }

    /// VR-34 (1)–(2): `set_canvas` with no rescale, then `add_track` "Backgrounds" at the back,
    /// both required. The core's own error for either (the track cap is one: "too many
    /// tracks") stops the step as its refusal does, in its own words.
    static func opening(_ project: ReelProject, width: Int, height: Int) throws -> Opening {
        var trial = SwitchAngle.Trial(project: project)
        func required(_ op: ReelOp) -> String? {
            do { return try trial.require(op) } catch { return error.localizedDescription }
        }
        if let why = required(.setCanvas(width: width, height: height, rescaleClips: false)) {
            return .refused("Make Vertical was refused at set_canvas: \(why)")
        }
        let known = Set(trial.project.snapshot.tracks.map(\.id))
        if let why = required(.addTrack(index: 0, name: backgroundsName)) {
            return .refused("Make Vertical was refused at add_track: \(why)")
        }
        guard let track = trial.project.snapshot.tracks.first(where: { !known.contains($0.id) })
        else { return .refused("Make Vertical was refused at add_track: no track was added.") }
        return .opened(trial, backgrounds: track.id)
    }

    /// VR-34 on `project`, the top-level timeline. `missing`: media pictures whose media has
    /// no URL in `document.mediaURLs()` (kept, not followed). `subjects` per clip, read by the
    /// following kinds and `speaker` only: the analysis's, or for a picture whose media has a
    /// cursor file its cursor's (`FramingCursor`, VR-51), followed by `cursor` with `replace:
    /// true`, or shown whole (`fit`) when it is absent. With `speaker` a speaker clip's subjects
    /// carry their `turns` (`withTurns`, VR-64 (d)); it is framed `speaker` with its own
    /// microphones, every other analysed picture `face`, a refused `speaker` retried as `face`.
    static func plan(
        _ project: ReelProject, settings: VerticalSettings, subjects: [UInt32: [String: Any]],
        missing: Set<UInt32>
    ) throws -> Answer {
        let old = project.snapshot
        let size = settings.shape.size(from: old.canvas)
        var trial: SwitchAngle.Trial
        let backgrounds: UInt32
        switch try opening(project, width: size.width, height: size.height) {
        case .refused(let why): return .refused(why)
        case .opened(let opened, let track):
            trial = opened
            backgrounds = track
        }
        let roles = classify(project)
        // Step (6)'s survey is of the OLD snapshot, so step (3) leaves its tracks alone.
        let survey = settings.captions ? CaptionRelayout.survey(old) : nil
        let relaid = Set(survey?.recognised.map(\.track) ?? [])
        var entries: [UInt32: Entry] = [:]
        var framed: Set<UInt32> = []
        var cursor: [UInt32] = []
        let speakers = speakerClips(project, settings: settings, missing: missing)
        let speakerOf = Dictionary(uniqueKeysWithValues: speakers.map { ($0.clip, $0) })
        var speaker: [SpeakerFraming] = []
        var moreTracks = 0
        var reEased = 0
        var carried = 0

        // (3b) The camera layouts re-laid first; what they changed is done (VR-53 (d)).
        let done: Set<UInt32>
        let layouts: [Relaid]
        switch try relay(roles, old: old, width: size.width, height: size.height, trial: &trial) {
        case .refused(let why): return .refused(why)
        case .done(let changed, let made, let switches):
            done = changed
            layouts = switches
            entries.merge(made) { _, new in new }
        }

        // (3) Each picture, nest and other clip, from the old canvas.
        for (id, role) in roles where !done.contains(id) {
            guard let clip = old.clip(id), !relaid.contains(clip.track) else { continue }
            var follow = FramingFollow.keep
            var note: String?
            switch role {
            case .picture:
                if case .media = clip.source {
                    if analyses(settings.follow), missing.contains(id) {
                        note = "its media file is missing, so it is kept as placed"
                    } else if analyses(settings.follow), old.media(for: clip)?.cursor != nil {
                        follow = subjects[id] == nil ? .fit : .cursor
                        if follow == .fit {
                            note = "its cursor file could not be read, so it is shown whole"
                        }
                    } else if settings.follow == .speaker {
                        follow = speakerOf[id] == nil ? .face : .speaker
                    } else {
                        follow = settings.follow
                    }
                } else {
                    follow = .center
                    note = "it is a still picture, so it is centred"
                }
            case .nest:
                follow = .center
                note = "it is a nest, so it is centred"
            case .other:
                break
            case .backdrop, .shapePlate, .imagePlate, .graphic, .layoutCamera, .layoutScreen,
                .layoutPiece:
                continue
            }
            func op(_ follow: FramingFollow) -> ReelOp {
                let own = follow == .speaker ? speakerOf[id] : nil
                var read = follow.readsSubjects ? subjects[id] : nil
                if follow != .speaker { read?["turns"] = nil }
                return .reframeClip(
                    clip: id, follow: follow, zoom: settings.zoom,
                    whereEmpty: analyses(follow) ? settings.whereEmpty : nil,
                    fromWidth: UInt32(old.canvas.width), fromHeight: UInt32(old.canvas.height),
                    backdrop: backgrounds, replace: follow == .cursor ? true : nil,
                    mics: own?.mics, micFaces: own?.micFaces, subjects: read)
            }
            let prior = trial.project
            var next = prior
            var used = follow
            var refusedWhy: String?
            var speakerWhy: String?
            // VR-34's retry, VR-64 (c)'s first: speaker → face → keep, a refused keep stopping.
            tried: while true {
                switch try prior.applying(op(used)) {
                case .applied(let made):
                    next = made
                    trial.ops.append(op(used))
                    break tried
                case .identity:
                    break tried
                case .refused(let refusal):
                    guard used != .keep else {
                        return .refused(
                            "Make Vertical was refused at reframe_clip for clip \(id): "
                                + refusal.reason)
                    }
                    if used == .speaker {
                        speakerWhy = refusal.reason
                        used = .face
                    } else {
                        refusedWhy = refusal.reason
                        used = .keep
                    }
                }
            }
            trial.project = next
            moreTracks += next.snapshot.tracks.count - prior.snapshot.tracks.count
            if let refusedWhy {
                entries[id] = Entry(clip: id, treatment: .notFollowed, reason: refusedWhy)
                continue
            }
            if used == .cursor { cursor.append(id) }
            if used == .speaker, let own = speakerOf[id] {
                let matched = own.micFaces ?? subjects[id].flatMap {
                    project.speakerMatch(clip: id, mics: own.mics, subjects: $0)?.assignment
                }
                speaker.append(SpeakerFraming(clip: id, mics: own.mics, faces: matched ?? []))
            }
            if used != .keep {
                framed.insert(id)
                let counted = FollowSubject.counts(
                    before: prior, after: next, clip: id, replace: used == .cursor)
                reEased += counted.reEased
                carried += counted.carried
            }
            if let note {
                entries[id] = Entry(clip: id, treatment: .notFollowed, reason: note)
            } else if role == .other {
                entries[id] = Entry(clip: id, treatment: .kept, reason: nil)
            } else if let speakerWhy {
                // VR-64 (c): followed on its faces, saying why not by who is talking.
                let base = followedEntry(clip, prior: prior, next: next)
                let reasons = [
                    "it follows its faces, not who is talking, because " + speakerWhy, base.reason,
                ].compactMap { $0 }
                entries[id] = Entry(
                    clip: id, treatment: .followed, reason: reasons.joined(separator: " and "))
            } else {
                entries[id] = followedEntry(clip, prior: prior, next: next)
            }
        }

        // (4) The backdrops and the plates, at the new canvas; a canvas-size graphic re-sized
        // to it (VR-42).
        let newFill = { (clip: ClipSnapshot) -> Double in
            fill(old.sourceSize(of: clip) ?? .zero, width: size.width, height: size.height)
        }
        for (id, role) in roles where !done.contains(id) {
            guard let clip = old.clip(id) else { continue }
            let ops: [ReelOp]
            let treatment: Treatment
            switch role {
            case .backdrop(let partner) where framed.contains(partner):
                ops = [.delete(clips: [id])]
                treatment = .removed
            case .backdrop, .imagePlate:
                ops = [.setVideo(clips: [id], patch: VideoPatch(x: 0, y: 0, scale: newFill(clip)))]
                treatment = .refilled
            case .shapePlate:
                ops = [
                    .setShape(
                        clips: [id],
                        patch: ShapePatch(width: Double(size.width), height: Double(size.height))),
                ]
                treatment = .refilled
            case .graphic:
                ops = graphicOps(clip, from: old.canvas, width: size.width, height: size.height)
                treatment = .resized
            case .picture, .nest, .other, .layoutCamera, .layoutScreen, .layoutPiece:
                continue
            }
            for op in ops {
                if let why = try trial.require(op) {
                    return .refused(
                        "Make Vertical was refused at \(op.name) for clip \(id): \(why)")
                }
            }
            entries[id] = Entry(clip: id, treatment: treatment, reason: nil)
        }

        // (5) Backgrounds goes when nothing landed on it.
        let kept = !trial.project.snapshot.clips(onTrack: backgrounds).isEmpty
        if !kept, let why = try trial.require(.removeTrack(track: backgrounds)) {
            return .refused("Make Vertical was refused at remove_track: \(why)")
        }

        // (6) The word caption tracks re-paged on the new canvas; a track the re-lay keeps
        // takes step (3)'s `keep`, so no clip is left without a reframe or an entry.
        var captions: CaptionRelayout.Outcome?
        if let survey {
            var outcome = try CaptionRelayout.relay(survey.recognised, on: &trial)
            let unlaid = Set(outcome.kept.map(\.track))
            for (id, _) in roles {
                guard let clip = old.clip(id), unlaid.contains(clip.track) else { continue }
                let op = ReelOp.reframeClip(
                    clip: id, follow: .keep, zoom: settings.zoom,
                    fromWidth: UInt32(old.canvas.width), fromHeight: UInt32(old.canvas.height),
                    backdrop: kept ? backgrounds : nil)
                if let why = try trial.require(op) {
                    return .refused(
                        "Make Vertical was refused at reframe_clip for clip \(id): \(why)")
                }
                entries[id] = Entry(clip: id, treatment: .kept, reason: nil)
            }
            outcome.kept = survey.kept + outcome.kept
            captions = outcome
        }
        return .plan(
            Plan(
                ops: trial.ops, project: trial.project, width: size.width, height: size.height,
                entries: entries.keys.sorted().compactMap { entries[$0] }, backgrounds: kept,
                moreTracks: moreTracks, reEased: reEased, carried: carried,
                captions: captions, cursor: cursor.sorted(), relaid: layouts,
                speaker: speaker.sorted { $0.clip < $1.clip }))
    }

    /// A media picture framed with a following kind or `center`: whole only when the op added
    /// a blurred copy AND the framing F is the same at the clip's start, its last tick and
    /// every action's two ends; otherwise followed, with why it is not wholly followed.
    private static func followedEntry(
        _ clip: ClipSnapshot, prior: ReelProject, next: ReelProject
    ) -> Entry {
        let known = Set(prior.snapshot.clips.map(\.id))
        let blurred = next.snapshot.clips.contains {
            !known.contains($0.id) && $0.name == blurredName
        }
        var constant = false
        if blurred, let now = next.snapshot.clip(clip.id) {
            var times = [now.start, now.start + max(0, now.duration - 1)]
            for action in now.actions {
                times += [now.start + action.start, now.start + action.endTime]
            }
            let frames = times.map {
                FollowSubject.framing(before: prior, after: next, clip: clip.id, at: $0)
            }
            if let first = frames.first ?? nil {
                constant = frames.allSatisfy { frame in
                    guard let frame else { return false }
                    return abs(frame.k - first.k) <= 1e-6 && abs(frame.dx - first.dx) <= 1e-6
                        && abs(frame.dy - first.dy) <= 1e-6
                }
            }
        }
        if constant { return Entry(clip: clip.id, treatment: .whole, reason: nil) }
        let reasons = [
            blurred ? "it is shown whole on a blurred copy where no subject is found" : nil,
            motionNote(clip),
        ].compactMap { $0 }
        return Entry(
            clip: clip.id, treatment: .followed,
            reason: reasons.isEmpty ? nil : reasons.joined(separator: " and "))
    }
}

import Foundation

/// Make Vertical's step (spec §11 VR-30…VR-35; road map "creator-jobs" VR3a): a project's
/// tall or square version as one grouped edit — `set_canvas`, a "Backgrounds" track, one
/// `reframe_clip` per picture from the old canvas, its backdrops and plates re-filled — tried
/// on one `SwitchAngle.Trial`. The copy is `ProjectDocument+VerticalCopy.swift`'s, the tool
/// `AgentServer+VerticalVersion.swift`'s; File ▸ Make Vertical Version… is
/// `VerticalVersionSheetController.swift` and `EditorViewController+VerticalVersion.swift` (VR3b,
/// VR-39).
///
/// This file holds the shapes (VR-32), the settings and the classes (VR-33);
/// `VerticalVersion+Plan.swift` the step (VR-34); `VerticalVersion+Summary.swift` the summary
/// and the answer (VR-35, VR-36); `VerticalVersion+Layers.swift` the graphics (VR-42, VR-44,
/// VR4b); `VerticalVersion+Layouts.swift` class 2b and step 3b (VR-53, VR-54, VR5b). Swift restates none
/// of VR-26's refusals: a clip the core will not frame reaches `keep` through the core's own
/// sentence. Names no `rc_*`.
enum VerticalShape: String, CaseIterable {
    case tall = "9:16"
    case portrait = "4:5"
    case square = "1:1"

    /// Height over width.
    private var ratio: Double {
        switch self {
        case .tall: return 16.0 / 9.0
        case .portrait: return 5.0 / 4.0
        case .square: return 1
        }
    }

    /// VR-32: w = min(W, H) rounded down to even; h = 2 × round(w × ratio / 2).
    func size(from canvas: CanvasSnapshot) -> (width: Int, height: Int) {
        let short = min(canvas.width, canvas.height)
        let width = short - short % 2
        let height = 2 * Int((Double(width) * ratio / 2).rounded())
        return (width, height)
    }
}

/// What the step is asked for (VR-36's arguments, VR3b's sheet).
struct VerticalSettings: Equatable {
    var shape: VerticalShape
    /// One of `VerticalVersion.follows`.
    var follow: FramingFollow
    /// Times the scale that fills the canvas, 1–4 (the core refuses outside).
    var zoom: Double
    var whereEmpty: FramingWhereEmpty
    /// Whether step (6) re-pages the word caption tracks (spec §11 VR-40 (f)); the sheet
    /// passes the default, `make_vertical_version` its `captions`.
    var captions = true
    /// `follow: speaker`'s microphones (spec §11 VR-64 (a)): 2–4 clip ids, each standing for
    /// its track; read only with `speaker`.
    var mics: [UInt32] = []
    /// One face number per microphone in `mics`' order, or nil for the core's own match; read
    /// only with `speaker`.
    var micFaces: [UInt32]? = nil
}

enum VerticalVersion {
    /// The undo step's name (VR-31, FC-90).
    static let actionName = "Make Vertical"
    static let backgroundsName = FollowSubject.backgroundsName
    /// The name `add_blurred_background` and `reframe_clip`'s backdrop give a copy.
    static let blurredName = "Blurred Background"
    /// The sheet's Follow pop-up and the tool's `follow`, in order (spec §11 VR-66 (a)): Follow
    /// Subject's list with Speaker before Center.
    static let follows: [FramingFollow] = [.subject, .face, .person, .salient, .speaker, .center]

    /// Whether `follow` analyses the media pictures (VR-64 (c)): the following kinds and
    /// `speaker`, which frames its other pictures on their faces.
    static func analyses(_ follow: FramingFollow) -> Bool {
        follow.follows || follow == .speaker
    }

    /// The Make Vertical sheet's opening Follow and Where Empty (VR-66 (a)): VR-29 (c)'s key
    /// read against `follows`, so a stored `speaker` opens Speaker here while Follow Subject's
    /// sheet reads it as Subject; any other value is Subject. Where Empty as
    /// `FollowSubjectSettings.remembered`; Zoom is never remembered, so 1.
    static func remembered(_ defaults: UserDefaults) -> FollowSubjectSettings {
        var settings = FollowSubjectSettings.remembered(defaults, zoom: 1)
        let kind = defaults.string(forKey: FollowSubjectSettings.followKey)
            .flatMap(FramingFollow.init(rawValue:))
        settings.follow = kind.flatMap { follows.contains($0) ? $0 : nil } ?? .subject
        return settings
    }

    /// What the step did to one clip, as the answer spells it.
    enum Treatment: String {
        case followed, whole, kept, refilled, removed, resized, relaid
        case notFollowed = "not_followed"
    }

    /// VR-33's classes.
    enum Role: Equatable {
        /// (1) A blurred copy of the clip `partner`, in front of it.
        case backdrop(partner: UInt32)
        /// (2) A shape rectangle the canvas's size at the centre, scale 1.
        case shapePlate
        /// (2) An image or still named "Background" at the canvas's fill.
        case imagePlate
        /// (2b) A clip laid out by Clip ▸ Camera Layout ▸ as the camera, as the screen behind
        /// it, or a cut piece of one (VR-53 (a), `VerticalVersion+Layouts.swift`).
        case layoutCamera, layoutScreen, layoutPiece
        /// (3) A media, still or image clip covering one axis of the canvas.
        case picture
        /// (4) A nest clip covering one axis.
        case nest
        /// (5) A graphic exactly the canvas's size, each side (VR-42 (a)).
        case graphic
        /// (6) Everything else.
        case other
    }

    /// VR-33's first match per top-level clip with a picture (not audio-only, not an
    /// adjustment clip, video enabled), in id order, on the OLD canvas.
    static func classify(_ project: ReelProject) -> [(clip: UInt32, role: Role)] {
        let snapshot = project.snapshot
        let order = Dictionary(
            uniqueKeysWithValues: snapshot.tracks.enumerated().map { ($0.element.id, $0.offset) })
        return snapshot.clips.sorted { $0.id < $1.id }.compactMap { clip in
            guard hasPicture(clip, in: snapshot) else { return nil }
            return (clip.id, role(of: clip, in: project, order: order))
        }
    }

    /// The `.picture` clips whose source is `.media` (the analysis targets).
    static func mediaPictures(
        _ roles: [(clip: UInt32, role: Role)], in snapshot: ProjectSnapshot
    ) -> [UInt32] {
        roles.compactMap { entry in
            guard entry.role == .picture, let clip = snapshot.clip(entry.clip),
                case .media = clip.source
            else { return nil }
            return entry.clip
        }
    }

    /// VR-37's analysis targets: the media pictures (`mediaPictures(classify(project), …)`),
    /// split by whether their media has a URL in `urls` (`document.mediaURLs()`); `missing` are
    /// kept, not followed. A present one whose media has a cursor file is in `cursor`, never
    /// analysed: it follows its cursor (spec §11 VR-51). The tool's first hop and the sheet
    /// both read it (VR-39 (d)).
    static func analysisTargets(_ project: ReelProject, urls: [UInt32: URL])
        -> (present: [UInt32], missing: Set<UInt32>, cursor: [UInt32])
    {
        let snapshot = project.snapshot
        let pictures = mediaPictures(classify(project), in: snapshot)
        let missing = Set(pictures.filter { id in
            snapshot.clip(id)?.source.mediaID.map { urls[$0] == nil } ?? false
        })
        let found = pictures.filter { !missing.contains($0) }
        let cursor = found.filter { id in
            snapshot.clip(id).flatMap { snapshot.media(for: $0) }?.cursor != nil
        }
        return (found.filter { !cursor.contains($0) }, missing, cursor)
    }

    /// VR-32's "not offered": `VerticalShape.allCases` whose size differs from `canvas`, in case
    /// order (the sheet's Shape pop-up, VR-39 (b)).
    static func offered(_ canvas: CanvasSnapshot) -> [VerticalShape] {
        VerticalShape.allCases.filter { shape in
            let size = shape.size(from: canvas)
            return size.width != canvas.width || size.height != canvas.height
        }
    }

    /// "moves by its own motion: <name>" for the first active slot that is neither a fade nor
    /// a spin, in the order during, in, out; nil when there is none.
    static func motionNote(_ clip: ClipSnapshot) -> String? {
        guard let motion = clip.videoProps.motion else { return nil }
        if let during = motion.during, during.amount > 0, during.kind != .spin {
            return "moves by its own motion: \(during.kind.displayName)"
        }
        for edge in [motion.inEdge, motion.out].compactMap({ $0 })
        where edge.isActive && edge.kind != .fade && edge.kind != .spin {
            return "moves by its own motion: \(edge.kind.displayName)"
        }
        return nil
    }

    /// The scale that fills `canvas` with a source of `size` (`edit_fit.rs`'s `fill_scale`),
    /// clamped to the canvas sessions' range.
    static func fill(_ size: CGSize, width: Int, height: Int) -> Double {
        guard size.width > 0, size.height > 0 else { return 1 }
        let scale = max(Double(width) / size.width, Double(height) / size.height)
        return min(CanvasScaleSession.maxScale, max(CanvasScaleSession.minScale, scale))
    }

    // MARK: - The classes

    /// A clip that draws pixels: `ProjectSnapshot.layers(at:)`'s test without the time.
    private static func hasPicture(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard clip.enabled.video else { return false }
        if case .adjustment = clip.source { return false }
        if let media = snapshot.media(for: clip) { return media.hasVideo || media.kind == .image }
        return true
    }

    private static func role(
        of clip: ClipSnapshot, in project: ReelProject, order: [UInt32: Int]
    ) -> Role {
        let snapshot = project.snapshot
        let canvas = snapshot.canvas
        if clip.name == blurredName, let partner = partner(of: clip, in: snapshot, order: order) {
            return .backdrop(partner: partner)
        }
        let video = clip.videoProps
        let centred = abs(video.x) <= 1e-6 && abs(video.y) <= 1e-6
        switch clip.source {
        case .shape:
            if let shape = clip.shape, shape.kind == .rectangle, centred,
                abs(video.scale - 1) <= 1e-6,
                abs(shape.width - Double(canvas.width)) <= 0.5,
                abs(shape.height - Double(canvas.height)) <= 0.5
            {
                return .shapePlate
            }
        case .image, .still:
            if clip.name == "Background", centred, let size = snapshot.sourceSize(of: clip) {
                let fill = fill(size, width: canvas.width, height: canvas.height)
                if abs(video.scale - fill) <= 1e-6 * fill { return .imagePlate }
            }
        case .graphic:
            if let graphic = clip.graphic, graphic.width == canvas.width,
                graphic.height == canvas.height
            {
                return .graphic
            }
        default:
            break
        }
        if let laid = layoutRole(of: clip, in: snapshot, order: order) { return laid }
        switch clip.source {
        case .media, .still, .image:
            if covers(clip, in: project) { return .picture }
        case .nest:
            if covers(clip, in: project) { return .nest }
        default:
            break
        }
        return .other
    }

    /// (1)'s partner: a clip on a track in front of `clip`'s with an equal source, start and
    /// duration; the nearest track first.
    private static func partner(
        of clip: ClipSnapshot, in snapshot: ProjectSnapshot, order: [UInt32: Int]
    ) -> UInt32? {
        guard let own = order[clip.track] else { return nil }
        return snapshot.clips
            .filter {
                $0.id != clip.id && (order[$0.track] ?? -1) > own && $0.source == clip.source
                    && $0.start == clip.start && $0.duration == clip.duration
            }
            .min { (order[$0.track] ?? 0, $0.id) < (order[$1.track] ?? 0, $1.id) }?.id
    }

    /// (3)'s test: the clip's rectangle at its first frame — base props with scale, x and y
    /// from `clip_state` at its start — covers one axis of the canvas (both edges at or beyond
    /// it, at most 1 px inside) and is centred within 2 % on the other, or covers it too.
import Foundation

/// Make Vertical's summary (spec §11 VR-35) and its answer (VR-36): what `plan` did, said as
/// the sheet's and the tool's text and as `make_vertical_version`'s keys. A pure move out of
/// `VerticalVersion+Plan.swift` (road map "creator-jobs" VR5b's toll). Names no `rc_*`.
extension VerticalVersion {
    /// VR-35: the counts, then one line per re-laid switch (VR-54), then one line per entry
    /// with a reason; the graphic counts and lines VR4b's (`templates`, VR-44 (d)).
    static func summary(_ plan: Plan, templates: TemplateReport = TemplateReport()) -> String {
        func count(_ treatment: Treatment) -> Int {
            plan.entries.filter { $0.treatment == treatment }.count
        }
        var text = "Makes a \(plan.width) × \(plan.height) version."
        let followed = count(.followed)
        if followed > 0 { text += " Follows \(counted(followed, "clip"))." }
        if !plan.cursor.isEmpty {
            text += " Follows the cursor in \(counted(plan.cursor.count, "clip")), their own "
                + "zooms and pans replaced."
        }
        if !plan.speaker.isEmpty {
            text += " Follows whoever is talking in \(counted(plan.speaker.count, "clip"))."
        }
        if !plan.relaid.isEmpty {
            text += " Re-lays \(counted(plan.relaid.count, "camera layout")) for the new canvas."
        }
        let whole = count(.whole)
        if whole > 0 { text += " Shows \(counted(whole, "clip")) whole on a blurred copy." }
        let kept = count(.kept)
        if kept > 0 { text += " Keeps \(counted(kept, "clip")) as placed." }
        let refilled = count(.refilled)
        if refilled > 0 { text += " Re-fills \(counted(refilled, "background"))." }
        let removed = count(.removed)
        if removed > 0 {
            text += " Removes \(removed) blurred \(removed == 1 ? "copy" : "copies") the "
                + "framing replaces."
        }
        text += graphicsCounts(plan, templates)
        if plan.backgrounds { text += " Adds a Backgrounds track for the blurred copy." }
        if plan.moreTracks > 0 {
            text += " Adds \(plan.moreTracks) more \(plan.moreTracks == 1 ? "track" : "tracks")"
                + " behind it where clips overlap."
        }
        if plan.reEased > 0 { text += " \(counted(plan.reEased, "action")) re-eased at a cut." }
        if plan.carried > 0 {
            text += " \(counted(plan.carried, "action")) "
                + (plan.carried == 1 ? "carries" : "carry") + " a framing move."
        }
        if let relaid = plan.captions?.relaid.count, relaid > 0 {
            text += " Re-lays \(counted(relaid, "caption track")) for the new canvas."
        }
        let canvas = plan.project.snapshot.canvas
        var lines = [text] + plan.relaid.map { relaidLine($0, canvas: canvas) }
        for entry in plan.entries {
            guard let reason = entry.reason else { continue }
            let why = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
            switch entry.treatment {
            case .notFollowed: lines.append("Clip \(entry.clip) is not followed: \(why).")
            default: lines.append("Clip \(entry.clip) is followed, but \(why).")
            }
        }
        lines += (plan.captions?.kept ?? []).map(CaptionRelayout.keptLine)
        lines += graphicsLines(templates)
        return lines.joined(separator: "\n")
    }

    /// VR-39 (d)'s pending summary, while the analysis is still to be made; with `speaker` it
    /// says the sheet comes back to confirm the microphones' faces (VR-66 (e)).
    static func pendingSummary(files: Int, width: Int, height: Int, speaker: Bool = false)
        -> String
    {
        "Finds the faces, people and shot changes in \(counted(files, "file")) on this Mac "
            + "first, " + (speaker ? "then asks you to confirm who is on each microphone, " : "")
            + "then makes a \(width) × \(height) version."
    }

    /// The answer's keys every door shares (VR-36): `canvas`, `clips` in id order,
    /// `backgrounds`, `more_tracks`, `re_eased`, `moves_carried`, `summary`, `graphics`,
    /// `cursor` (VR-52), `relaid` (VR-54) and `speaker` (VR-64 (f)).
    static func answerFields(_ plan: Plan, templates: TemplateReport = TemplateReport())
        -> [String: Any]
    {
        let clips: [[String: Any]] = plan.entries.map { entry in
            var row: [String: Any] = [
                "clip": Int(entry.clip), "treatment": entry.treatment.rawValue,
            ]
            if let reason = entry.reason { row["reason"] = reason }
            return row
        }
        var fields: [String: Any] = [
            "canvas": ["width": plan.width, "height": plan.height],
            "clips": clips,
            "backgrounds": plan.backgrounds,
            "more_tracks": plan.moreTracks,
            "re_eased": plan.reEased,
            "moves_carried": plan.carried,
            "summary": summary(plan, templates: templates),
            "cursor": plan.cursor.map { Int($0) },
            "relaid": relaidFields(plan.relaid),
            "speaker": plan.speaker.map { framed -> [String: Any] in
                [
                    "clip": Int(framed.clip), "mics": framed.mics.map { Int($0) },
                    "mic_faces": framed.faces.map { Int($0) },
                ]
            },
            "graphics": graphicsFields(plan, templates),
        ]
        if let captions = plan.captions {
            fields["captions"] = CaptionRelayout.answerFields(captions)
        }
        return fields
    }

    static func counted(_ n: Int, _ noun: String) -> String {
        "\(n) \(noun)\(n == 1 ? "" : "s")"
    }
}

import Foundation

/// What Clip ▸ Follow Subject… frames (spec §11 VR-29; road map "creator-jobs" VR2b2): each
/// selected clip with a moving picture `reframe_clip`'d with `replace: true` and a "Backgrounds"
/// track as its `backdrop`, as one undo step "Follow Subject". The sheet is
/// `FollowSubjectSheetController`, the door `EditorViewController+FollowSubject.swift`.
///
/// Swift copies none of VR-26's or VR-27's rules: the plan TRIES each op on the container's
/// handle through `SwitchAngle.Trial` and lists the core's own sentence for a refusal; the
/// subjects are `FramingSubjects.read`'s, over `FramingAnalysis.windows`. Names no `rc_*`.
struct FollowSubjectSettings: Equatable {
    /// One of `FollowSubject.follows`.
    var follow: FramingFollow
    /// Times the scale that fills the canvas, inside `zoomRange` (the sheet shows 100–400 %).
    var zoom: Double
    var whereEmpty: FramingWhereEmpty

    static let followKey = "FrameJobFollowKind"
    static let whereEmptyKey = "FrameJobFollowWhereEmpty"
    static let zoomRange: ClosedRange<Double> = 1...4

    /// VR-29 (c): Follow and Where Empty as remembered, an absent or unknown value read as
    /// `subject` / `fit`; Zoom is never remembered, so it is the caller's.
    static func remembered(_ defaults: UserDefaults, zoom: Double) -> FollowSubjectSettings {
        let kind = defaults.string(forKey: followKey).flatMap(FramingFollow.init(rawValue:))
        let empty = defaults.string(forKey: whereEmptyKey).flatMap(FramingWhereEmpty.init(rawValue:))
        return FollowSubjectSettings(
            follow: kind.flatMap { FollowSubject.follows.contains($0) ? $0 : nil } ?? .subject,
            zoom: zoom, whereEmpty: empty ?? .fit)
    }

    /// Writes each remembered key whose value changed from `opened`, and no other.
    func remember(changedFrom opened: FollowSubjectSettings, in defaults: UserDefaults) {
        if follow != opened.follow {
            defaults.set(follow.rawValue, forKey: Self.followKey)
        }
        if whereEmpty != opened.whereEmpty {
            defaults.set(whereEmpty.rawValue, forKey: Self.whereEmptyKey)
        }
    }

    /// The clip's `reframe_clip` (VR-29 (e)): `zoom` for every follow, `where_empty` and
    /// `subjects` for the following kinds only, always `replace: true`.
    func op(clip: UInt32, backdrop: UInt32, subjects: [String: Any]?) -> ReelOp {
        let following = follow.follows
        return .reframeClip(
            clip: clip, follow: follow, zoom: zoom, whereEmpty: following ? whereEmpty : nil,
            backdrop: backdrop, replace: true, subjects: following ? subjects : nil)
    }
}

enum FollowSubject {
    static let actionName = "Follow Subject"
    static let backgroundsName = "Backgrounds"
    /// The sheet's Follow pop-up, in order: Subject, Faces, People, Salient Region, Center.
    static let follows: [FramingFollow] = [.subject, .face, .person, .salient, .center]

    /// What Follow would write: the ops, the clips framed, the ones already framed this way, the
    /// refused with the core's sentence, whether Backgrounds is kept, how many more tracks the
    /// core made behind it, and VR-27 (f)'s counts summed over the framed clips.
    struct Plan {
        let ops: [ReelOp]
        let framed: [UInt32]
        let unchanged: [UInt32]
        let refused: [(clip: UInt32, reason: String)]
        let backgrounds: Bool
        let moreTracks: Int
        let reEased: Int
        let carried: Int
    }

    enum Answer {
        case plan(Plan)
        case refused(String)
    }

    /// VR-29 (a): the selected clips `FramingAnalysis.qualifies` takes, in id order.
    static func targets(_ selection: Set<UInt32>, in project: ReelProject) -> [UInt32] {
        let snapshot = project.snapshot
        return selection.sorted().filter { id in
            snapshot.clip(id).map { FramingAnalysis.qualifies($0, in: snapshot) } ?? false
        }
    }

    /// VR-29 (b): 1 (fill, the owner's answer), or 1.25 when the first clip's media is within
    /// 1 % of the canvas's aspect.
    static func defaultZoom(_ clips: [UInt32], in snapshot: ProjectSnapshot) -> Double {
        guard let first = clips.first, let clip = snapshot.clip(first),
            let media = snapshot.media(for: clip), media.width > 0, media.height > 0,
            snapshot.canvas.width > 0, snapshot.canvas.height > 0
        else { return 1 }
        let picture = Double(media.width) / Double(media.height)
        let canvas = Double(snapshot.canvas.width) / Double(snapshot.canvas.height)
        return abs(picture / canvas - 1) <= 0.01 ? 1.25 : 1
    }

    /// The targets whose media has no cursor file — the ones Follow Subject analyses (spec §11
    /// VR-51). A clip whose media has one stays a target, so the core's VR-51 sentence is
    /// listed as its refusal, but it is never requested or read.
    static func analysed(_ clips: [UInt32], in project: ReelProject) -> [UInt32] {
        let snapshot = project.snapshot
        return clips.filter { id in
            snapshot.clip(id).flatMap { snapshot.media(for: $0) }?.cursor == nil
        }
    }

    /// Each clip's `subjects`, read from the store over that clip's own windows, as
    /// `reframe_clip`'s tool reads them; a clip whose media has a cursor file is skipped
    /// (`analysed`, VR-51). Reads files only: any thread.
    static func subjects(_ clips: [UInt32], in project: ReelProject, cacheDir: URL)
        -> [UInt32: [String: Any]]
    {
        var out: [UInt32: [String: Any]] = [:]
        for clip in analysed(clips, in: project) {
            guard let entry = FramingAnalysis.windows(clips: [clip], in: project).first,
                let media = project.snapshot.media(entry.media)
            else { continue }
            out[clip] = FramingSubjects.read(
                media: media, windows: entry.windows, cacheDir: cacheDir)
        }
        return out
    }

    /// VR-29 (e) on `project`, the handle of the container being edited. Throws only the core's
    /// invalid input.
    static func plan(
        _ clips: [UInt32], subjects: [UInt32: [String: Any]], settings: FollowSubjectSettings,
        project: ReelProject
    ) throws -> Answer {
        var trial = SwitchAngle.Trial(project: project)
        let known = Set(project.snapshot.tracks.map(\.id))
        if let why = try trial.require(.addTrack(index: 0, name: backgroundsName)) {
            return .refused("Follow Subject was refused at add_track: \(why)")
        }
        guard let track = trial.project.snapshot.tracks.first(where: { !known.contains($0.id) })
        else { return .refused("Follow Subject was refused at add_track: no track was added.") }

        var framed: [UInt32] = []
        var unchanged: [UInt32] = []
        var refused: [(clip: UInt32, reason: String)] = []
import AppKit

/// Clip ▸ Follow Subject… (road map "creator-jobs" VR2b2, spec §11 VR-29 (b)–(d), (g), (h)): each
/// selected clip with a moving picture framed on its subject by `reframe_clip` with `replace:
/// true` and a "Backgrounds" track behind it, as one undo step "Follow Subject". The plan is
/// `FollowSubject.plan`; `reframe_clip`'s tool is the mirror (`AgentServer+Framing.swift`).
///
/// Follow (Subject, Faces, People, Salient Region, Center), Zoom (100–400 %, never remembered)
/// and Where Empty (Show Whole, Center; off while Follow is Center), then the summary. The sheet
/// opens at once and asks `FramingAnalysis.requests` what is missing. With nothing missing it
/// reads the subjects off main ("Reading the analysis…", Follow disabled) and plans on main at
/// every change. With something missing a following kind shows the pending summary, and Follow
/// remembers, dismisses and hands the requests to the editor (`analyze`) on the main queue's next
/// turn after `viewDidDisappear` — the Analyzing sheet and the commit are
/// `EditorViewController+FollowSubject.swift`'s. Center reads no subjects, so it plans at once and
/// never analyzes. Follow plans again on the document's current handle before it applies.
///
/// **The dev accept** (`-RCDevFollowAccept YES`, dev tools only): the sheet presses Follow once,
/// the first time Follow is enabled after the first summary (AU-128's precedent).
final class FollowSubjectSheetController: NSViewController, NSTextFieldDelegate {
    /// The dev-only launch default that presses Follow.
    static let devAcceptKey = "RCDevFollowAccept"
    static let reading = "Reading the analysis…"
    private static let followTitles = ["Subject", "Faces", "People", "Salient Region", "Center"]
    private static let whereEmpties: [(String, FramingWhereEmpty)] = [
        ("Show Whole", .fit), ("Center", .center),
    ]

    private weak var document: ProjectDocument?
    private let clipIDs: [UInt32]
    private let opened: FollowSubjectSettings
    private let analyze: (FollowSubjectSettings, [AnalysisRequest]) -> Void
    private var requests: [AnalysisRequest] = []
    private var requestError: String?
    private var subjects: [UInt32: [String: Any]]?
    private var asked = false
    private var plan: FollowSubject.Plan?
    private var accepted = false
    /// Set by Follow when the analysis is to be made: handed to `analyze` after disappearing.
    private var handOff: (FollowSubjectSettings, [AnalysisRequest])?

    private let followPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let whereEmptyPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let zoomField = NSTextField(string: "")
    private let summaryLabel = NSTextField(wrappingLabelWithString: "")
    private var followButton: NSButton?

    init(
        document: ProjectDocument, clips: [UInt32],
        analyze: @escaping (FollowSubjectSettings, [AnalysisRequest]) -> Void
    ) {
        self.document = document
        self.clipIDs = clips
        self.analyze = analyze
        self.opened = FollowSubjectSettings.remembered(
            .standard, zoom: FollowSubject.defaultZoom(clips, in: document.editedProject.snapshot))
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("FollowSubjectSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        for title in Self.followTitles { followPopup.addItem(withTitle: title) }
        followPopup.selectItem(at: FollowSubject.follows.firstIndex(of: opened.follow) ?? 0)
        for (title, _) in Self.whereEmpties { whereEmptyPopup.addItem(withTitle: title) }
        whereEmptyPopup.selectItem(
            at: Self.whereEmpties.firstIndex { $0.1 == opened.whereEmpty } ?? 0)
        for (popup, id) in [(followPopup, "follow.kind"), (whereEmptyPopup, "follow.whereEmpty")] {
            popup.font = DS.sans(13)
            popup.target = self
            popup.action = #selector(controlChanged(_:))
            popup.setAccessibilityIdentifier(id)
        }

        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.allowsFloats = false
        formatter.minimum = NSNumber(value: FollowSubjectSettings.zoomRange.lowerBound * 100)
        formatter.maximum = NSNumber(value: FollowSubjectSettings.zoomRange.upperBound * 100)
        zoomField.formatter = formatter
        zoomField.delegate = self
        zoomField.alignment = .right
        zoomField.integerValue = Int((opened.zoom * 100).rounded())
        zoomField.widthAnchor.constraint(equalToConstant: 64).isActive = true
        zoomField.setAccessibilityIdentifier("follow.zoom")
        DSField.style(zoomField)

        summaryLabel.font = DS.sans(12)
        summaryLabel.textColor = DS.textMuted
        summaryLabel.preferredMaxLayoutWidth = sheetWidth - sheetInset * 2
        summaryLabel.stringValue = Self.reading
        summaryLabel.setAccessibilityIdentifier("follow.summary")

        let grid = makeSheetGrid([
            [fieldLabel("Follow:"), followPopup],
            [fieldLabel("Zoom:"), sheetRow([zoomField, sheetUnitLabel("%")])],
            [fieldLabel("Where Empty:"), whereEmptyPopup],
        ])
        let cancel = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let follow = StickerButton(
            title: "Follow", style: .primary, target: self, action: #selector(followClicked(_:)))
        follow.isEnabled = false
        followButton = follow
        view = makeSheetView(
            title: "Follow Subject",
            hint: "Frames each selected clip on its subject with eased moves on its action lane, "
                + "and a blurred copy behind it where it shows the whole picture. Replaces the "
                + "clips' own position and scale. One undo step.",
            content: sheetColumn([grid, summaryLabel]),
            buttonRow: makeButtonRow(cancel: cancel, apply: follow))
        whereEmptyPopup.isEnabled = opened.follow != .center
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        guard !asked, let document else { return }
        asked = true
        do {
            requests = try FramingAnalysis.requests(
                clips: FollowSubject.analysed(clipIDs, in: document.editedProject), in: document)
        } catch {
            requestError = error.localizedDescription
        }
        if requestError == nil, requests.isEmpty, let cacheDir = document.cacheDirectory {
            let project = document.editedProject
            let clips = clipIDs
            DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                let read = FollowSubject.subjects(clips, in: project, cacheDir: cacheDir)
                DispatchQueue.main.async { self?.didRead(read) }
            }
        }
        refresh()
    }

    private func didRead(_ read: [UInt32: [String: Any]]) {
        subjects = read
        refresh()
    }

    /// The one hand-back: once, after the sheet is gone, never after Cancel.
    override func viewDidDisappear() {
        super.viewDidDisappear()
        guard let handOff else { return }
        self.handOff = nil
        let analyze = self.analyze
        DispatchQueue.main.async { analyze(handOff.0, handOff.1) }
    }

    // MARK: - Values

    /// What the controls say, Zoom inside its range.
    private var settings: FollowSubjectSettings {
        let range = FollowSubjectSettings.zoomRange
        let percent = Double(zoomField.integerValue)
        let follow = FollowSubject.follows[max(0, followPopup.indexOfSelectedItem)]
        let empty = Self.whereEmpties[max(0, whereEmptyPopup.indexOfSelectedItem)].1
        return FollowSubjectSettings(
            follow: follow, zoom: min(max(percent / 100, range.lowerBound), range.upperBound),
            whereEmpty: empty)
    }

    /// Whether Follow must make the analysis first: a following kind with requests missing.
    private func pending(_ settings: FollowSubjectSettings) -> Bool {
        settings.follow.follows && requestError == nil && !requests.isEmpty
    }

    /// Says what Follow would do and enables it: the request error, the pending summary,
    /// "Reading the analysis…", or the plan made on main over the document's current handle.
    private func refresh() {
        let settings = self.settings
        whereEmptyPopup.isEnabled = settings.follow != .center
        plan = nil
        var enabled = false
        if settings.follow.follows, let requestError {
            summaryLabel.stringValue = requestError
        } else if pending(settings) {
            summaryLabel.stringValue = FollowSubject.pendingSummary(
                files: Set(requests.map(\.media.id)).count, clips: clipIDs.count)
            enabled = true
        } else if settings.follow.follows, subjects == nil {
            summaryLabel.stringValue = Self.reading
        } else {
            let (made, text) = planned(settings)
            plan = made
            summaryLabel.stringValue = text
            enabled = !(made?.ops.isEmpty ?? true)
        }
        followButton?.isEnabled = enabled
        acceptIfAsked()
    }

    /// `FollowSubject.plan` on the document's current handle: the plan and its summary, or the
    /// refusal.
    private func planned(_ settings: FollowSubjectSettings) -> (FollowSubject.Plan?, String) {
