/// and Where Empty (Show Whole, Center; off while Follow is Center), then the summary. The sheet
/// opens at once and asks `FramingAnalysis.requests` what is missing. With nothing missing it
/// reads the subjects off main ("Reading the analysis…", Follow disabled) and plans on main at
/// every change. With something missing a following kind shows the pending summary, and Follow
/// remembers, dismisses and hands the requests to the editor (`analyze`) on the main queue's next
/// turn after `viewDidDisappear` — the Analyzing sheet and the commit are
/// `EditorViewController+FollowSubject.swift`'s. Center reads no subjects, so it plans at once and
/// never analyzes. Follow plans again on the document's current handle before it applies.
///
/// **The dev accept** (`-RCDevFollowAccept YES`, dev tools only): the sheet presses Follow once,
/// the first time Follow is enabled after the first summary (AU-128's precedent).
final class FollowSubjectSheetController: NSViewController, NSTextFieldDelegate {
    /// The dev-only launch default that presses Follow.
    static let devAcceptKey = "RCDevFollowAccept"
    static let reading = "Reading the analysis…"
    private static let followTitles = ["Subject", "Faces", "People", "Salient Region", "Center"]
    private static let whereEmpties: [(String, FramingWhereEmpty)] = [
        ("Show Whole", .fit), ("Center", .center),
    ]

    private weak var document: ProjectDocument?
    private let clipIDs: [UInt32]
    private let opened: FollowSubjectSettings
    private let analyze: (FollowSubjectSettings, [AnalysisRequest]) -> Void
    private var requests: [AnalysisRequest] = []
    private var requestError: String?
    private var subjects: [UInt32: [String: Any]]?
    private var asked = false
    private var plan: FollowSubject.Plan?
    private var accepted = false
    /// Set by Follow when the analysis is to be made: handed to `analyze` after disappearing.
    private var handOff: (FollowSubjectSettings, [AnalysisRequest])?

    private let followPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let whereEmptyPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let zoomField = NSTextField(string: "")
    private let summaryLabel = NSTextField(wrappingLabelWithString: "")
    private var followButton: NSButton?

    init(
        document: ProjectDocument, clips: [UInt32],
        analyze: @escaping (FollowSubjectSettings, [AnalysisRequest]) -> Void
    ) {
        self.document = document
        self.clipIDs = clips
        self.analyze = analyze
        self.opened = FollowSubjectSettings.remembered(
            .standard, zoom: FollowSubject.defaultZoom(clips, in: document.editedProject.snapshot))
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("FollowSubjectSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        for title in Self.followTitles { followPopup.addItem(withTitle: title) }
        followPopup.selectItem(at: FollowSubject.follows.firstIndex(of: opened.follow) ?? 0)
        for (title, _) in Self.whereEmpties { whereEmptyPopup.addItem(withTitle: title) }
        whereEmptyPopup.selectItem(
            at: Self.whereEmpties.firstIndex { $0.1 == opened.whereEmpty } ?? 0)
        for (popup, id) in [(followPopup, "follow.kind"), (whereEmptyPopup, "follow.whereEmpty")] {
            popup.font = DS.sans(13)
            popup.target = self
            popup.action = #selector(controlChanged(_:))
            popup.setAccessibilityIdentifier(id)
        }

        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.allowsFloats = false
        formatter.minimum = NSNumber(value: FollowSubjectSettings.zoomRange.lowerBound * 100)
        formatter.maximum = NSNumber(value: FollowSubjectSettings.zoomRange.upperBound * 100)
        zoomField.formatter = formatter
        zoomField.delegate = self
        zoomField.alignment = .right
        zoomField.integerValue = Int((opened.zoom * 100).rounded())
        zoomField.widthAnchor.constraint(equalToConstant: 64).isActive = true
        zoomField.setAccessibilityIdentifier("follow.zoom")
        DSField.style(zoomField)

        summaryLabel.font = DS.sans(12)
        summaryLabel.textColor = DS.textMuted
        summaryLabel.preferredMaxLayoutWidth = sheetWidth - sheetInset * 2
        summaryLabel.stringValue = Self.reading
        summaryLabel.setAccessibilityIdentifier("follow.summary")

        let grid = makeSheetGrid([
            [fieldLabel("Follow:"), followPopup],
            [fieldLabel("Zoom:"), sheetRow([zoomField, sheetUnitLabel("%")])],
            [fieldLabel("Where Empty:"), whereEmptyPopup],
        ])
        let cancel = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let follow = StickerButton(
            title: "Follow", style: .primary, target: self, action: #selector(followClicked(_:)))
        follow.isEnabled = false
        followButton = follow
        view = makeSheetView(
            title: "Follow Subject",
            hint: "Frames each selected clip on its subject with eased moves on its action lane, "
                + "and a blurred copy behind it where it shows the whole picture. Replaces the "
                + "clips' own position and scale. One undo step.",
            content: sheetColumn([grid, summaryLabel]),
            buttonRow: makeButtonRow(cancel: cancel, apply: follow))
        whereEmptyPopup.isEnabled = opened.follow != .center
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        guard !asked, let document else { return }
        asked = true
        do {
            requests = try FramingAnalysis.requests(
                clips: FollowSubject.analysed(clipIDs, in: document.editedProject), in: document)
        } catch {
            requestError = error.localizedDescription
        }
        if requestError == nil, requests.isEmpty, let cacheDir = document.cacheDirectory {
            let project = document.editedProject
            let clips = clipIDs
            DispatchQueue.global(qos: .userInitiated).async { [weak self] in
                let read = FollowSubject.subjects(clips, in: project, cacheDir: cacheDir)
                DispatchQueue.main.async { self?.didRead(read) }
            }
        }
        refresh()
    }

    private func didRead(_ read: [UInt32: [String: Any]]) {
        subjects = read
        refresh()
    }

    /// The one hand-back: once, after the sheet is gone, never after Cancel.
    override func viewDidDisappear() {
        super.viewDidDisappear()
        guard let handOff else { return }
        self.handOff = nil
        let analyze = self.analyze
        DispatchQueue.main.async { analyze(handOff.0, handOff.1) }
    }

    // MARK: - Values

    /// What the controls say, Zoom inside its range.
    private var settings: FollowSubjectSettings {
        let range = FollowSubjectSettings.zoomRange
        let percent = Double(zoomField.integerValue)
        let follow = FollowSubject.follows[max(0, followPopup.indexOfSelectedItem)]
        let empty = Self.whereEmpties[max(0, whereEmptyPopup.indexOfSelectedItem)].1
        return FollowSubjectSettings(
            follow: follow, zoom: min(max(percent / 100, range.lowerBound), range.upperBound),
            whereEmpty: empty)
    }

    /// Whether Follow must make the analysis first: a following kind with requests missing.
    private func pending(_ settings: FollowSubjectSettings) -> Bool {
        settings.follow.follows && requestError == nil && !requests.isEmpty
    }

    /// Says what Follow would do and enables it: the request error, the pending summary,
    /// "Reading the analysis…", or the plan made on main over the document's current handle.
    private func refresh() {
        let settings = self.settings
        whereEmptyPopup.isEnabled = settings.follow != .center
        plan = nil
        var enabled = false
        if settings.follow.follows, let requestError {
            summaryLabel.stringValue = requestError
        } else if pending(settings) {
            summaryLabel.stringValue = FollowSubject.pendingSummary(
                files: Set(requests.map(\.media.id)).count, clips: clipIDs.count)
            enabled = true
        } else if settings.follow.follows, subjects == nil {
            summaryLabel.stringValue = Self.reading
        } else {
            let (made, text) = planned(settings)
            plan = made
            summaryLabel.stringValue = text
            enabled = !(made?.ops.isEmpty ?? true)
        }
        followButton?.isEnabled = enabled
        acceptIfAsked()
    }

    /// `FollowSubject.plan` on the document's current handle: the plan and its summary, or the
    /// refusal.
    private func planned(_ settings: FollowSubjectSettings) -> (FollowSubject.Plan?, String) {
        guard let document else { return (nil, "") }
import AppKit

/// Clip ▸ Follow Subject… (road map "creator-jobs" VR2b2, spec §11 VR-29) — the menu door over
/// `reframe_clip`: the selection's targets (`FollowSubject.targets`), the sheet
/// (`FollowSubjectSheetController`), and, when the sheet's Follow needs an analysis made, the
/// Analyzing sheet and the commit. The sheet commits itself when nothing is missing, or for
/// Center, which never analyzes.
///
/// The Analyzing sheet's hand-back is not an AppKit event, so the plan goes through
/// `performGroupedEdit` (Split at Shot Changes' shape), and only onto the project handle and
/// scope the hand-off read: a changed project is refused in VR-29 (d)'s sentence. The subjects
/// are read off main, then the project is checked again. Every refusal beeps and puts its
/// sentence at the inspector's foot (spec §11 CI-10).
extension EditorViewController {

    @objc func showFollowSubjectSheet(_ sender: Any?) {
        guard let document, view.window?.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let targets = FollowSubject.targets(document.selection, in: document.editedProject)
        guard !targets.isEmpty else {
            NSSound.beep()
            return
        }
        presentAsSheet(
            FollowSubjectSheetController(document: document, clips: targets) {
                [weak self, weak document] settings, requests in
                guard let self, let document else { return }
                self.analyzeForFollow(
                    settings, requests: requests, targets: targets, document: document)
            })
    }

    /// The sheet's hand-off: the Analyzing sheet over every missing request, one row each.
    private func analyzeForFollow(
        _ settings: FollowSubjectSettings, requests: [AnalysisRequest], targets: [UInt32],
        document: ProjectDocument
    ) {
        guard view.window?.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let asked = document.project
        let scope = document.scope
        let rows = requests.map {
            AnalyzingSheetController.Row(name: FollowSubject.rowName($0), request: $0)
        }
        presentAsSheet(
            AnalyzingSheetController(
                document: document, command: FollowSubject.actionName, rows: rows
            ) { [weak self, weak document] outcome in
                guard let self, let document else { return }
                self.finishFollow(
                    outcome, rows: rows, settings: settings, targets: targets, asked: asked,
                    scope: scope, document: document)
            })
    }

    /// The Analyzing sheet's answer: refused when the project or scope changed, a failed
    /// analysis named; else the subjects read off main and the plan committed.
    private func finishFollow(
        _ outcome: AnalyzingSheetController.Outcome, rows: [AnalyzingSheetController.Row],
        settings: FollowSubjectSettings, targets: [UInt32], asked: ReelProject, scope: UInt32?,
        document: ProjectDocument
    ) {
        guard document.project === asked, document.scope == scope else {
            refuseFollow(Self.followChanged, document: document)
            return
        }
        switch outcome {
        case .failed(let name, let why):
            let request = rows.first { $0.name == name }?.request
            let kind = request?.kind.rawValue ?? "framing"
            let file = request?.media.name ?? name
            refuseFollow("The \(kind) analysis of “\(file)” failed: \(why).", document: document)
        case .landed:
            guard let cacheDir = document.cacheDirectory else {
                refuseFollow(
                    ProjectDocument.AnalysisRequestError.noCache.localizedDescription,
                    document: document)
                return
            }
            let project = document.editedProject
            DispatchQueue.global(qos: .userInitiated).async { [weak self, weak document] in
                let subjects = FollowSubject.subjects(targets, in: project, cacheDir: cacheDir)
                DispatchQueue.main.async {
                    guard let self, let document else { return }
                    guard document.project === asked, document.scope == scope else {
                        self.refuseFollow(Self.followChanged, document: document)
                        return
                    }
                    self.commitFollow(
                        targets, subjects: subjects, settings: settings, document: document)
                }
            }
        }
    }

    /// The plan on the current handle, as one explicit undo group; nothing framed is refused
    /// with the summary's lines.
    private func commitFollow(
        _ targets: [UInt32], subjects: [UInt32: [String: Any]], settings: FollowSubjectSettings,
        document: ProjectDocument
    ) {
        let answer: FollowSubject.Answer
        do {
            answer = try FollowSubject.plan(
                targets, subjects: subjects, settings: settings, project: document.editedProject)
        } catch {
            refuseFollow(error.localizedDescription, document: document)
            return
        }
        switch answer {
        case .refused(let why):
            refuseFollow(why, document: document)
        case .plan(let plan) where plan.ops.isEmpty:
            refuseFollow(FollowSubject.summary(plan), document: document)
        case .plan(let plan):
            document.performGroupedEdit(FollowSubject.actionName, plan.ops)
        }
    }

    private static let followChanged =
        "the project changed while \(FollowSubject.actionName) was analyzing, so nothing was "
        + "framed. Choose \(FollowSubject.actionName) again."

    /// A beep and the sentence at the inspector's foot.
    private func refuseFollow(_ reason: String, document: ProjectDocument) {
        NSSound.beep()
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: ["refusal": ReelRefusal(op: "reframe_clip", reason: reason)])
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any other
    /// action. On when a selected clip of the edited container has a moving picture and no
    /// sheet is on the window; allowed inside a nest.
    func validateFollowSubjectAction(_ action: Selector) -> Bool? {
        guard action == #selector(showFollowSubjectSheet(_:)) else { return nil }
        guard let document, view.window?.attachedSheet == nil else { return false }
        return !FollowSubject.targets(document.selection, in: document.editedProject).isEmpty
    }
}

import Foundation

/// Switch by Speaker's planner (road map "creator-jobs" SW2a, spec §11
/// SW-20…SW-25): which microphone is active on a 10 ms grid, the shots those
/// turns make on the angle tracks, and every refusal named at once. Nothing
/// here is visible yet; SW2b's sheet and tool write the shots onto a Program
/// track.
///
/// Pure (SW-25): `defaults`, `plan`, `labels` and `shots` read no document,
/// file or clock. `read` (`SpeakerSwitch+Read.swift`) is the one reader, and
/// the series it builds are `ClipLevelSeries`'. Names no `rc_*` but
/// `ReelTime.snapToFrame` and `ReelTime.format`.
enum SpeakerSwitch {
    static let actionName = "Switch by Speaker"
    static let maxAngles = 9

    /// What a qualifying crosstalk turn does: show the wide, or hold.
    enum Crosstalk: String { case wide, hold }

    /// Seconds and dB; the defaults are SW-S4's (SW-21) and SW-22's drafts.
    struct Settings: Equatable {
        var minShot = 2.0, minTurn = 1.0, lead = 0.2, crosstalkMin = 1.0, bridge = 0.5
        var crosstalk: Crosstalk = .wide
        var bleedDB = 15.0, dominanceDB = 8.0, floorMarginDB = 6.0, voiceThreshold: Float = 0.5
        /// nil = off.
        var wideAfter: Double? = nil
        /// The faces mode's label (SW-81): the top angle's activity over the next's, and the
        /// floor it must exceed.
        var faceRatio = FaceActivity.ratio, faceFloor = FaceActivity.floor
    }

    /// Who says who is talking (SW-83): each microphone its own person, or one microphone shared
    /// by two or more angles and their faces (`SpeakerSwitch+Faces.swift`).
    enum Mode: String { case microphones, faces }

    /// One face-speaker angle's mouth activity on the range's grid (SW-81): step k's activity,
    /// nil where none can be read. Empty: not read.
    struct FaceAngle: Equatable {
        let track: UInt32
        let activity: [Double?]
    }

    /// A person: their microphone track and the angle track that shows them.
    struct Speaker: Equatable { let mic: UInt32?; let angle: UInt32? }
    struct Pairing: Equatable { let speakers: [Speaker]; let wide: UInt32? }
    struct Span: Equatable { let clip: UInt32; let start: Ticks; let end: Ticks }
    /// An angle track and its picture clips (`SwitchAngle.pictureClips`), by start.
    struct AngleTrack: Equatable { let track: UInt32; let clips: [Span] }

    /// One microphone track on the range's grid: step k is
    /// `[from + k·step, from + (k+1)·step)`. Empty arrays: not read.
    struct Microphone: Equatable {
        let track: UInt32
        /// ℓ(k) in dB over the centred window; −∞ when silent.
        let level: [Double]
        /// v(k).
        let voice: [Float]
        /// A selected clip of this track plays at the step's midpoint.
        let covered: [Bool]
    }

    struct Input {
        let from: Ticks, to: Ticks, fps: Fps
        /// Front first.
        let angles: [AngleTrack]
        /// Front first.
        let microphones: [Microphone]
        let pairing: Pairing
        /// `read`'s: still analysed, no speech detection.
        let problems: [String]
        /// `ShotSplit.clipCount` of the document's project.
        let clipCount: Int
        let settings: Settings
        /// The faces mode's angles, front first (`readFaces`); empty in the microphones mode.
        var faces: [FaceAngle] = []
    }

    /// A step's label; `person` names the microphone track (in the faces mode, the angle's).
    enum Label: Equatable { case person(UInt32), crosstalk, nobody }
    struct Shot: Equatable { let angle: UInt32; let start: Ticks; let end: Ticks }
    enum Plan: Equatable { case refused([String]); case planned(shots: [Shot], added: Int) }

    // MARK: - SW-20's defaults

    /// The angles, microphones and pairing a selection implies, front first.
    static func defaults(selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
        -> (angles: [UInt32], microphones: [UInt32], pairing: Pairing)
    {
        let front = snapshot.tracks.reversed().map(\.id)
        func holds(_ track: UInt32, _ test: (ClipSnapshot) -> Bool) -> Bool {
            selection.contains { $0.track == track && test($0) }
        }
        let angles = front.filter { holds($0) { isPicture($0, in: snapshot) } }
        let files = front.filter {
            holds($0) { playsSound($0, in: snapshot) && snapshot.media(for: $0)?.hasVideo == false }
        }
        let microphones = files.isEmpty
            ? angles.filter { holds($0) { playsSound($0, in: snapshot) } } : files

        var speakers: [Speaker] = []
        var used: Set<UInt32> = []
        for mic in microphones where angles.contains(mic) {
            used.insert(mic)
        }
        var free = angles.filter { !used.contains($0) }.makeIterator()
        for mic in microphones {
            if angles.contains(mic) {
                speakers.append(Speaker(mic: mic, angle: mic))
            } else if let angle = free.next() {
                used.insert(angle)
                speakers.append(Speaker(mic: mic, angle: angle))
            } else {
                speakers.append(Speaker(mic: mic, angle: nil))
            }
        }
        let left = angles.filter { !used.contains($0) }
        // SW-83: one microphone shared by every angle, and no wide (the faces mode).
        if microphones.count == 1, angles.count >= 2, let mic = microphones.first {
            return (angles, microphones,
                    Pairing(speakers: angles.map { Speaker(mic: mic, angle: $0) }, wide: nil))
        }
        return (angles, microphones,
                Pairing(speakers: speakers, wide: left.count == 1 ? left.first : nil))
    }

    /// A `detach_audio` half: the sound of a file with pictures.
    static func isDetachedSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        !clip.enabled.video && clip.linked != nil && snapshot.media(for: clip)?.hasVideo == true
    }

    /// A media clip with a picture that may make its track an angle.
    static func isPicture(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard case .media = clip.source, snapshot.sourceSize(of: clip) != nil else { return false }
        return !(clip.enabled.video == false && clip.linked != nil)
    }

    /// A media clip that sounds, by the snapshot alone (no plan here): its
    /// media has audio, its sound is on, and it is no detached camera sound.
    static func playsSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard case .media = clip.source, clip.enabled.audio,
            snapshot.media(for: clip)?.hasAudio == true
        else { return false }
        return !isDetachedSound(clip, in: snapshot)
    }

    // MARK: - The plan

    static func plan(_ input: Input) -> Plan {
        let refusals = refusals(input)
        if !refusals.isEmpty { return .refused(refusals) }
        let step = stepTicks
        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
        let faces = mode(input.pairing) == .faces
        let all = faces
            ? faceLabels(input)
            : labels(input.microphones.filter { $0.level.count == count }, settings: input.settings)
        let planned = shots(
            labels: all, from: input.from, to: input.to, fps: input.fps,
            pairing: faces ? facePairing(input.pairing) : input.pairing,
            angles: input.angles, settings: input.settings)
        let added = clipsAdded(planned, angles: input.angles, from: input.from, to: input.to)
        let most = Int(RC_MAX_CLIPS)
        if input.clipCount + added > most {
            return .refused([
                "Switch by Speaker would add \(added) clips to \(input.clipCount); the most is "
                    + "\(most) — raise the minimum shot."
            ])
        }
        return .planned(shots: planned, added: added)
    }

    /// SW-24's list, in its order; empty when nothing is refused.
    static func refusals(_ input: Input) -> [String] {
        var out: [String] = []
        let angles = input.angles.map(\.track)
        if angles.count < 2 {
            out.append(
                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
                    + "with a picture.")
        }
        if angles.count > maxAngles {
            out.append(
                "Switch by Speaker takes at most nine angles; \(angles.count) tracks hold a "
                    + "selected clip with a picture.")
        }
        let microphones = input.microphones.map(\.track)
        let faces = mode(input.pairing) == .faces
        // SW-83: in the faces mode a speaker on the wide takes no part.
        for speaker in input.pairing.speakers
        where !(faces && speaker.angle != nil && speaker.angle == input.pairing.wide) {
            guard let mic = speaker.mic, microphones.contains(mic) else {
                let track = speaker.angle ?? speaker.mic ?? 0
                out.append("The speaker on track \(track) has no microphone.")
                continue
            }
            if speaker.angle.map({ !angles.contains($0) }) ?? true {
                out.append("The microphone on track \(mic) has no angle to show its speaker.")
            }
        }
        var counted: [UInt32] = []
        for mic in input.pairing.speakers.compactMap(\.mic) where !faces && !counted.contains(mic) {
            counted.append(mic)
            let n = input.pairing.speakers.filter { $0.mic == mic }.count
            if n > 1 {
                out.append(
                    "Track \(mic) is the microphone for \(n) speakers; each person needs their "
                        + "own microphone.")
            }
        }
        out += input.problems
        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
        out += silentMicrophones(input)
        // SW-84: a read angle with no step whose mouth can be read.
        for angle in input.faces where angle.activity.count == count
            && !angle.activity.contains(where: { $0 != nil })
        {
            out.append(
                "The camera on track \(angle.track) shows no face whose mouth can be read between "
                    + "\(a) and \(b), so it never says who is talking.")
        }
        if let gap = firstGap(input.angles, from: input.from, to: input.to) {
            out.append(
                "No angle has a picture between "
                    + "\(ReelTime.format(gap.from, fps: input.fps, frames: true)) and "
                    + "\(ReelTime.format(gap.to, fps: input.fps, frames: true)).")
        }
        return out
    }

    /// SW-24's no-speech sentences: each read microphone with no speech step inside the range.
    static func silentMicrophones(_ input: Input) -> [String] {
        var out: [String] = []
        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
        for mic in input.microphones where mic.voice.count == count {
            let speaks = mic.voice.indices.contains {
                mic.covered[$0] && mic.voice[$0] >= input.settings.voiceThreshold
            }
            if !speaks {
                out.append(
                    "The microphone on track \(mic.track) has no speech between \(a) and \(b), "
                        + "so it never says who is talking.")
            }
        }
        return out
    }

    /// The first stretch of `[from, to)` no angle covers.
    static func firstGap(_ angles: [AngleTrack], from: Ticks, to: Ticks)
        -> (from: Ticks, to: Ticks)?
    {
        var t = from
        while t < to {
            if let end = angles.compactMap({ reach($0, from: t) }).max() {
                t = end
                continue
            }
            let next = angles.flatMap(\.clips).map(\.start).filter { $0 > t }.min() ?? to
            return (t, min(next, to))
        }
        return nil
    }

    /// How far `angle`'s clips cover contiguously from `t`; nil when they
    /// do not cover `t` (SW-13's rule).
    static func reach(_ angle: AngleTrack, from t: Ticks) -> Ticks? {
        var reached = angle.clips.filter { $0.start <= t && $0.end > t }.map(\.end).max()
        // A clip starting at or before the edge extends it (abutting files
        // cover their join): loop until the edge no longer moves.
        while let end = reached {
            let further = angle.clips.filter { $0.start <= end && $0.end > end }.map(\.end).max()
            guard let further else { break }
            reached = further
        }
        return reached
    }

    /// SW-24's N: per shot, the angle clips it overlaps (the later one
    /// taking over where two overlap, SW-15 (d)), plus a split for each
    /// angle clip straddling `from` and each straddling `to`.
    static func clipsAdded(_ shots: [Shot], angles: [AngleTrack], from: Ticks, to: Ticks) -> Int {
        var n = 0
        for shot in shots {
            guard let angle = angles.first(where: { $0.track == shot.angle }) else { continue }
            let crossing = angle.clips.filter { $0.end > shot.start && $0.start < shot.end }
            for (index, clip) in crossing.enumerated() {
                let next = index + 1 < crossing.count ? crossing[index + 1].start : shot.end
                if min(clip.end, next, shot.end) > max(clip.start, shot.start) { n += 1 }
            }
        }
        for clip in angles.flatMap(\.clips) {
            if clip.start < from && from < clip.end { n += 1 }
            if clip.start < to && to < clip.end { n += 1 }
        }
        return n
    }
}
