/// Switch by Speaker's values, as both doors take them (spec §11 SW-26 (d)): the ranges the sheet
/// clamps to and `switch_by_speaker` refuses outside of, the four values the sheet remembers, and
/// the summary the sheet shows. Pure but for the `UserDefaults` it is handed; names no `rc_*`.
extension SpeakerSwitch.Settings {
    /// Seconds.
    static let minShotRange: ClosedRange<Double> = 0.5...30
    /// Seconds; the tool's alone (SW-26 (d)).
    static let minTurnRange: ClosedRange<Double> = 0.2...10
    /// Seconds.
    static let leadRange: ClosedRange<Double> = 0...1
    /// dB below a speaker's own level.
    static let bleedRange: ClosedRange<Double> = 3...40
    /// dB; the tool's alone (SW-26 (d)).
    static let dominanceRange: ClosedRange<Double> = 0...30
    /// Seconds.
    static let wideAfterRange: ClosedRange<Double> = 2...600
    /// The sheet's field when "Cut to the wide after" is first ticked (the owner: offered, off).
    static let wideAfterOffered = 20.0

    static let minShotKey = "FrameJobSwitchSpeakerMinShot"
    static let leadKey = "FrameJobSwitchSpeakerLead"
    /// "wide" or "hold".
    static let crosstalkKey = "FrameJobSwitchSpeakerCrosstalk"
    static let bleedKey = "FrameJobSwitchSpeakerBleed"

    /// The sheet's opening values: each remembered key clamped into its range, an absent or
    /// unreadable key the default. Read through `double(forKey:)`, so a launch argument counts.
    static func remembered(_ d: UserDefaults) -> SpeakerSwitch.Settings {
        var s = SpeakerSwitch.Settings()
        func number(_ key: String, _ range: ClosedRange<Double>, _ fallback: Double) -> Double {
            guard d.object(forKey: key) != nil else { return fallback }
            let v = d.double(forKey: key)
            guard v.isFinite else { return fallback }
            return min(max(v, range.lowerBound), range.upperBound)
        }
        s.minShot = number(minShotKey, minShotRange, s.minShot)
        s.lead = number(leadKey, leadRange, s.lead)
        s.bleedDB = number(bleedKey, bleedRange, s.bleedDB)
        if let raw = d.string(forKey: crosstalkKey), let crosstalk = SpeakerSwitch.Crosstalk(rawValue: raw) {
            s.crosstalk = crosstalk
        }
        return s
    }

    /// Writes only the remembered keys whose value differs from the sheet's opening values, so a
    /// sheet pressed as it opened moves no default (mcp.py's DEFAULTS MOVED guard).
    func remember(changedFrom opened: SpeakerSwitch.Settings, in d: UserDefaults) {
        if minShot != opened.minShot { d.set(minShot, forKey: Self.minShotKey) }
        if lead != opened.lead { d.set(lead, forKey: Self.leadKey) }
        if crosstalk != opened.crosstalk { d.set(crosstalk.rawValue, forKey: Self.crosstalkKey) }
        if bleedDB != opened.bleedDB { d.set(bleedDB, forKey: Self.bleedKey) }
    }
}

extension SpeakerSwitch {
    /// "N shots: k on <name>, …. Adds M clips." — the angles in the order they first show,
    /// each named by `names` (a track id when it has none).
    static func summary(_ shots: [Shot], added: Int, names: [UInt32: String]) -> String {
        var order: [UInt32] = []
        var counts: [UInt32: Int] = [:]
        for shot in shots {
            if counts[shot.angle] == nil { order.append(shot.angle) }
            counts[shot.angle, default: 0] += 1
        }
        let each = order.map { "\(counts[$0] ?? 0) on \(names[$0] ?? "track \($0)")" }
        let count = shots.count == 1 ? "1 shot" : "\(shots.count) shots"
        let adds = added == 1 ? "1 clip" : "\(added) clips"
        return "\(count): \(each.joined(separator: ", ")). Adds \(adds)."
    }

    /// The name each of `tracks` is listed by: its own, with " (n)" — n its 1-based position
    /// from the back — when two of them share it (SW-13's rule, `SwitchAngle.angles`).
    static func titles(_ tracks: [UInt32], in snapshot: ProjectSnapshot) -> [UInt32: String] {
        let names = tracks.map { snapshot.track($0)?.name ?? "Track" }
        var out: [UInt32: String] = [:]
        for (track, name) in zip(tracks, names) {
            if names.filter({ $0 == name }).count > 1 {
                out[track] = "\(name) (\((snapshot.trackIndex(of: track) ?? 0) + 1))"
            } else {
                out[track] = name
            }
        }
        return out
    }

    /// The sheet's Microphone choices, front first: every track holding a selected `.media`
    /// clip with its sound on and a media with audio, a detached camera sound included (SW-20).
    static func microphoneChoices(_ selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
        -> [UInt32]
    {
        snapshot.tracks.reversed().map(\.id).filter { track in
            selection.contains { clip in
                guard clip.track == track, case .media = clip.source, clip.enabled.audio else {
                    return false
                }
                return snapshot.media(for: clip)?.hasAudio == true
            }
        }
    }
}

import Foundation

/// Who is active on each step (SW-21) and the shots those turns make (SW-22).
/// Pure; `SpeakerSwitch.swift` says what the switch is.
extension SpeakerSwitch {
    static var stepTicks: Ticks { MediaPeaks.bucketTicks }

    /// The nearest-rank percentile `sorted[⌈p·n⌉ − 1]`; nil for no values.
    static func percentile(_ values: [Double], _ p: Double) -> Double? {
        guard !values.isEmpty else { return nil }
        let sorted = values.sorted()
        let rank = Int((p * Double(sorted.count) - 1e-9).rounded(.up))
        return sorted[min(sorted.count - 1, max(0, rank - 1))]
    }

    // MARK: - SW-21

    /// One label per step. Every microphone's series must be the same length.
    static func labels(_ microphones: [Microphone], settings: Settings) -> [Label] {
        activeSets(microphones, settings: settings).map { active in
            switch active.count {
            case 0: return .nobody
            case 1: return .person(active[0])
            default: return .crosstalk
            }
        }
    }

    /// The microphone tracks active on each step (SW-21), a dominant one alone.
    static func activeSets(_ microphones: [Microphone], settings: Settings) -> [[UInt32]] {
        let count = microphones.map(\.level.count).min() ?? 0
        let threshold = settings.voiceThreshold
        // P and F per microphone; a microphone with no speech is never active.
        let gauges: [(p: Double, f: Double)?] = microphones.map { mic in
            var speech: [Double] = []
            var quiet: [Double] = []
            for k in 0..<count where mic.covered[k] {
                if mic.voice[k] >= threshold { speech.append(mic.level[k]) } else {
                    quiet.append(mic.level[k])
                }
            }
            guard let p = percentile(speech, 0.9) else { return nil }
            return (p, percentile(quiet, 0.1) ?? -.infinity)
        }
        var out: [[UInt32]] = []
        out.reserveCapacity(count)
        for k in 0..<count {
            var active: [(track: UInt32, over: Double)] = []
            for (index, mic) in microphones.enumerated() {
                guard let gauge = gauges[index], mic.covered[k], mic.voice[k] >= threshold
                else { continue }
                let level = mic.level[k]
                guard level >= gauge.p - settings.bleedDB,
                    level >= gauge.f + settings.floorMarginDB
                else { continue }
                active.append((mic.track, level - gauge.p))
            }
            if active.count >= 2, let top = active.max(by: { $0.over < $1.over }),
                active.allSatisfy({ $0.track == top.track
                    || top.over - $0.over >= settings.dominanceDB })
            {
                active = [top]
            }
            out.append(active.map(\.track))
        }
        return out
    }

    // MARK: - SW-22

    struct Run: Equatable { var label: Label; var start: Int; var end: Int }

    /// Maximal runs of equal labels, in step indices.
    static func runs(_ labels: [Label]) -> [Run] {
        var out: [Run] = []
        for (k, label) in labels.enumerated() {
            if var last = out.last, last.label == label {
                last.end = k + 1
                out[out.count - 1] = last
            } else {
                out.append(Run(label: label, start: k, end: k + 1))
            }
        }
        return out
    }

    /// SW-22 (a), the crosstalk half: each maximal stretch of non-crosstalk runs lying between two
    /// crosstalk runs, shorter than `bridge` in total, becomes crosstalk; the runs it joins merge.
    static func bridgingCrosstalk(_ runs: [Run], under bridge: Ticks) -> [Run] {
        var out: [Run] = []
        var index = 0
        while index < runs.count {
            let run = runs[index]
            if run.label != .crosstalk, var last = out.last, last.label == .crosstalk,
                let next = runs[index...].firstIndex(where: { $0.label == .crosstalk }),
                Ticks(runs[next].start - run.start) * stepTicks < bridge
            {
                last.end = runs[next].end
                out[out.count - 1] = last
                index = next + 1
                continue
            }
            out.append(run)
            index += 1
        }
        return out
    }

    static func shots(
        labels: [Label], from: Ticks, to: Ticks, fps: Fps, pairing: Pairing,
        angles: [AngleTrack], settings: Settings
    ) -> [Shot] {
        let step = stepTicks
        func ticks(_ seconds: Double) -> Ticks { Ticks((seconds * Double(ReelTime.perSecond)).rounded()) }
        func snap(_ t: Ticks) -> Ticks { ReelTime.snapToFrame(t, fps: fps) }
        guard to > from, let front = angles.first?.track else { return [] }
        let wide = pairing.wide.flatMap { w in angles.contains { $0.track == w } ? w : nil }

        // (a), (b): the turns.
        let turns = bridgedRuns(labels, settings: settings)

        // (c), (d), (e): the starts.
        var starts: [(angle: UInt32, start: Ticks)] = []
        if let wide { starts.append((wide, from)) }
        for turn in turns {
            let length = Ticks(turn.end - turn.start) * step
            let angle: UInt32?
            switch turn.label {
            case .nobody: angle = nil
            case .person(let mic):
                angle = length >= ticks(settings.minTurn)
                    ? pairing.speakers.first(where: { $0.mic == mic })?.angle : nil
            case .crosstalk:
                angle = length >= ticks(settings.crosstalkMin) && settings.crosstalk == .wide
                    ? wide : nil
            }
            guard let angle, angle != starts.last?.angle else { continue }
            let at = max(
                starts.last?.start ?? from, from,
                snap(from + Ticks(turn.start) * step - ticks(settings.lead)))
            if starts.last?.start == at {
                starts.removeLast()
                if starts.last?.angle == angle { continue }
            }
            starts.append((angle, at))
        }
        if starts.isEmpty { starts.append((front, from)) }
        starts[0].start = from
        var tiled = tile(starts, to: to)

        // (f) the wide after a person has held the screen `wide_after`.
        if let wide, let after = settings.wideAfter, after > 0 {
            var out: [Shot] = []
            for shot in tiled {
                guard shot.angle != wide else {
                    out.append(shot)
                    continue
                }
                var held = shot.start
                while true {
                    let cut = snap(held + ticks(after))
                    guard cut > held, cut < shot.end else { break }
                    let back = min(shot.end, snap(cut + ticks(settings.minShot)))
                    out.append(Shot(angle: shot.angle, start: held, end: cut))
                    out.append(Shot(angle: wide, start: cut, end: back))
                    held = back
                    if back >= shot.end { break }
                }
                if held < shot.end { out.append(Shot(angle: shot.angle, start: held, end: shot.end)) }
            }
            tiled = out
        }

        // (g) every uncovered piece handed on; (h) the merges.
        let covered = handOff(tiled, angles: angles, wide: wide)
        return merged(covered, angles: angles, minShot: ticks(settings.minShot))
    }

    /// SW-22 (a): a short stretch between two crosstalk runs is crosstalk, then a short nobody
    /// between two equal labels takes the label; (b) the runs left are the turns.
    static func bridgedRuns(_ labels: [Label], settings: Settings) -> [Run] {
        let step = stepTicks
        let bridge = Ticks((settings.bridge * Double(ReelTime.perSecond)).rounded())
        var turns = bridgingCrosstalk(runs(labels), under: bridge)
        var index = 1
        while index + 1 < turns.count {
            let gap = turns[index]
            if gap.label == .nobody, turns[index - 1].label == turns[index + 1].label,
                Ticks(gap.end - gap.start) * step < bridge
            {
                turns[index - 1].end = turns[index + 1].end
                turns.removeSubrange(index...(index + 1))
            } else {
                index += 1
            }
        }
        return turns
    }

    /// Starts to shots tiling `[starts[0].start, to)`, empty ones dropped.
    static func tile(_ starts: [(angle: UInt32, start: Ticks)], to: Ticks) -> [Shot] {
        var out: [Shot] = []
        for (index, start) in starts.enumerated() {
            let end = index + 1 < starts.count ? min(starts[index + 1].start, to) : to
            if end > start.start { out.append(Shot(angle: start.angle, start: start.start, end: end)) }
        }
        return coalesced(out)
    }

    static func coalesced(_ shots: [Shot]) -> [Shot] {
        var out: [Shot] = []
        for shot in shots where shot.end > shot.start {
            if let last = out.last, last.angle == shot.angle, last.end == shot.start {
                out[out.count - 1] = Shot(angle: last.angle, start: last.start, end: shot.end)
            } else {
                out.append(shot)
            }
        }
        return out
    }

    /// (g): each shot's uncovered pieces go to the wide, else the shot
    /// before's angle, else the front-most angle covering there.
    static func handOff(_ shots: [Shot], angles: [AngleTrack], wide: UInt32?) -> [Shot] {
        func track(_ id: UInt32) -> AngleTrack? { angles.first { $0.track == id } }
        func reachOf(_ id: UInt32?, _ t: Ticks) -> Ticks? {
            id.flatMap(track).flatMap { reach($0, from: t) }
        }
        var out: [Shot] = []
        for (index, shot) in shots.enumerated() {
            let before = index > 0 ? shots[index - 1].angle : nil
            var t = shot.start
            while t < shot.end {
                if let end = reachOf(shot.angle, t) {
                    let stop = min(end, shot.end)
                    out.append(Shot(angle: shot.angle, start: t, end: stop))
                    t = stop
                    continue
                }
                let back = track(shot.angle)?.clips.map(\.start).filter { $0 > t }.min() ?? shot.end
                let uncovered = min(back, shot.end)
                while t < uncovered {
                    let choice: (UInt32, Ticks)?
                    if let w = wide, let end = reachOf(w, t) {
                        choice = (w, end)
                    } else if let b = before, let end = reachOf(b, t) {
                        choice = (b, end)
                    } else {
                        choice = angles.lazy.compactMap { a in reach(a, from: t).map { (a.track, $0) } }
                            .first
                    }
                    guard let (angle, end) = choice else {
                        // No angle covers: SW-24 refuses this; keep the shot's own.
                        let next = angles.flatMap(\.clips).map(\.start).filter { $0 > t }.min()
                        let stop = min(next ?? uncovered, uncovered)
                        out.append(Shot(angle: shot.angle, start: t, end: stop))
                        t = stop
                        continue
                    }
                    let stop = min(end, uncovered)
                    out.append(Shot(angle: angle, start: t, end: stop))
                    t = stop
                }
            }
        }
        return coalesced(out)
    }

    /// Whether `angle` covers `[start, end)` whole.
    static func covers(_ angle: UInt32, _ start: Ticks, _ end: Ticks, in angles: [AngleTrack]) -> Bool {
        guard let track = angles.first(where: { $0.track == angle }) else { return false }
        guard let reached = reach(track, from: start) else { return false }
        return reached >= end
    }

    /// (h): the earliest short shot that can merge does, until none can.
    static func merged(_ shots: [Shot], angles: [AngleTrack], minShot: Ticks) -> [Shot] {
        var out = coalesced(shots)
        while true {
            var done = true
            for (i, shot) in out.enumerated() where shot.end - shot.start < minShot {
                let intoBefore = i > 0 && covers(out[i - 1].angle, shot.start, shot.end, in: angles)
                let intoAfter = i + 1 < out.count
                    && covers(out[i + 1].angle, shot.start, shot.end, in: angles)
                if intoBefore {
                    let b = out[i - 1]
                    out[i - 1] = Shot(angle: b.angle, start: b.start, end: shot.end)
                } else if intoAfter {
                    let a = out[i + 1]
                    out[i + 1] = Shot(angle: a.angle, start: shot.start, end: a.end)
                } else {
                    continue
                }
                out.remove(at: i)
                out = coalesced(out)
                done = false
                break
            }
            if done { return out }
        }
    }
}
import Foundation

/// Switch by Speaker's faces mode (road map "creator-jobs" SW8, spec §11 SW-80…SW-86): one
/// microphone shared by two or more angles, who talks decided by each angle's mouth activity
/// (`FaceActivity`) while the microphone hears speech, and SW-22's `shots` run unchanged over
/// those labels with the face pairing.
///
/// `withoutWide`, `faceSpeakers`, `mode`, `facePairing`, `faceLabels` and `faceSeries` are pure
/// (SW-25). `readFaces` (from `read`) and `facesWanted` (the menu's Analyzing sheet, the tool's
/// wait) are the switch's second and third readers: the `faces` kind through the analysis store
/// in forward-media source ticks (SW-84). Names no `rc_*`.
extension SpeakerSwitch {

    // MARK: - The mode (SW-83)

    /// Each speaker whose angle is the wide AND whose microphone another speaker shares is
    /// dropped; every other pairing comes back identical.
    static func withoutWide(_ pairing: Pairing) -> Pairing {
        guard let wide = pairing.wide else { return pairing }
        let speakers = pairing.speakers
        let kept = speakers.indices.filter { i in
            guard speakers[i].angle == wide, let mic = speakers[i].mic else { return true }
            return !speakers.indices.contains { $0 != i && speakers[$0].mic == mic }
        }
        return Pairing(speakers: kept.map { speakers[$0] }, wide: wide)
    }

    /// The speakers with an angle that is not the wide, the first per angle.
    static func faceSpeakers(_ pairing: Pairing) -> [Speaker] {
        var seen: Set<UInt32> = []
        return pairing.speakers.filter { speaker in
            guard let angle = speaker.angle, angle != pairing.wide else { return false }
            return seen.insert(angle).inserted
        }
    }

    /// Faces when two or more face speakers all name one microphone; else microphones.
    static func mode(_ pairing: Pairing) -> Mode {
        let speakers = faceSpeakers(pairing)
        guard speakers.count >= 2, let mic = speakers[0].mic,
            speakers.allSatisfy({ $0.mic == mic })
        else { return .microphones }
        return .faces
    }

    /// The face speakers as their own labels — `(mic: angle, angle: angle)` — and the same wide,
    /// so `shots` maps `faceLabels`' `.person(angle)` to that angle.
    static func facePairing(_ pairing: Pairing) -> Pairing {
        Pairing(
            speakers: faceSpeakers(pairing).map { Speaker(mic: $0.angle, angle: $0.angle) },
            wide: pairing.wide)
    }

    // MARK: - The labels (SW-81)

    /// One label per step: `.person(angle track)`, `.crosstalk` or `.nobody`. A step is speech
    /// when the shared microphone covers it at v ≥ `voice_threshold`; the face speakers' angles
    /// contest it front first.
    static func faceLabels(_ input: Input) -> [Label] {
        let step = stepTicks
        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
        let nobody = [Label](repeating: .nobody, count: count)
        let speakers = faceSpeakers(input.pairing)
        guard let micTrack = speakers.first?.mic,
            let mic = input.microphones.first(where: { $0.track == micTrack }),
            mic.voice.count == count, mic.covered.count == count
        else { return nobody }
        let order = input.angles.map(\.track)
        let contest = speakers.compactMap(\.angle)
            .sorted { (order.firstIndex(of: $0) ?? .max) < (order.firstIndex(of: $1) ?? .max) }
        let series: [(UInt32, [Double?])] = contest.map { angle in
            let read = input.faces.first { $0.track == angle }?.activity ?? []
            return (angle, read.count == count ? read : [Double?](repeating: nil, count: count))
        }
        let threshold = input.settings.voiceThreshold
        return (0..<count).map { k in
            FaceActivity.label(
                speech: mic.covered[k] && mic.voice[k] >= threshold,
                activities: series.map { (angle: $0.0, activity: $0.1[k]) },
                ratio: input.settings.faceRatio, floor: input.settings.faceFloor)
        }
    }

    /// An angle clip as the faces series reads it: its span, its times, its media's sample grid
    /// and duration, and the media's activity per grid index.
    struct FaceClip {
        let span: Span
        let times: AnalysisClipTimes
        let grid: AnalysisGrid
        let duration: Ticks
        let activity: [Double?]
    }

    /// Step k's activity: the sample nearest the forward source tick of the step's midpoint,
    /// through the covering clip (the later-starting where two cover); nil off every clip or
    /// outside the media's 0…duration.
    static func faceSeries(_ clips: [FaceClip], from: Ticks, count: Int) -> [Double?] {
        let step = stepTicks
        return (0..<max(0, count)).map { k -> Double? in
            let mid = from + Ticks(k) * step + step / 2
            var covering: FaceClip?
            for clip in clips where clip.span.start <= mid && mid < clip.span.end {
                if covering.map({ clip.span.start >= $0.span.start }) ?? true { covering = clip }
            }
            guard let clip = covering else { return nil }
            let source = clip.times.source(atClip: mid - clip.span.start)
            guard source >= 0, source <= clip.duration else { return nil }
            let index = clip.grid.index(of: source)
            return index < clip.activity.count ? clip.activity[index] : nil
        }
    }

    // MARK: - The store (SW-84)

    /// A face speaker's angle clip of moving-video media crossing the range, and the window of
    /// its media the faces series needs: the part inside the range in source ticks, widened by
    /// half the activity window and clamped to 0…duration.
    struct FaceWindow {
        let track: UInt32
        let span: Span
        let media: MediaSnapshot
        let times: AnalysisClipTimes
        let window: ClosedRange<Ticks>
    }

    static func faceWindows(
        in project: ReelProject, angles: [AngleTrack], pairing: Pairing, from: Ticks, to: Ticks
    ) -> [FaceWindow] {
        let snapshot = project.snapshot
        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
        let half = Ticks((FaceActivity.window / 2 * Double(ReelTime.perSecond)).rounded())
        var out: [FaceWindow] = []
        for angle in angles where wanted.contains(angle.track) {
            for span in angle.clips where span.end > from && span.start < to {
                guard let clip = snapshot.clip(span.clip), let media = snapshot.media(for: clip),
                    media.kind == .video, media.hasVideo
                else { continue }
                let times = AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(clip.id))
                let a = times.source(atClip: max(span.start, from) - span.start)
                let b = times.source(atClip: min(span.end, to) - span.start)
                let low = max(0, min(a, b) - half)
                let high = min(media.duration, max(a, b) + half)
                guard high > low else { continue }
                out.append(FaceWindow(
                    track: angle.track, span: span, media: media, times: times, window: low...high))
            }
        }
        return out
    }

    /// The media's activity per grid index from the cached samples: each index the marker covers
    /// has the opening of its sample, the rest none.
    static func storedActivity(_ media: MediaSnapshot, grid: AnalysisGrid, cacheDir: URL)
        -> [Double?]
    {
        var openings = [Double?](repeating: nil, count: grid.count)
        if let marker = AnalysisStore.readMarker(.faces, media: media.id, in: cacheDir),
            let file = marker.files.first,
            let data = AnalysisStore.readPayload(.faces, media: media.id, file: file, in: cacheDir),
            let decoded = AnalysisFaces.decode(data), decoded.count == grid.count
        {
            for range in marker.ranges {
                for k in max(0, range.lowerBound)...min(grid.lastIndex, range.upperBound) {
                    openings[k] = FaceActivity.opening(decoded.samples[k])
                }
            }
        }
        let rate = grid.rate * Double(ReelTime.perSecond)
        return FaceActivity.activities(openings, half: FaceActivity.halfWidth(rate: rate))
    }

    /// Each face speaker's angle, front first, on the range's grid, and the "still being
    /// analysed" problem for an angle any of whose windows the store does not answer (read as
    /// `[]`). Main thread.
    static func readFaces(
        from document: ProjectDocument, angles: [AngleTrack], pairing: Pairing, from: Ticks,
        count: Int
    ) -> (faces: [FaceAngle], problems: [String]) {
        let to = from + Ticks(max(0, count)) * stepTicks
        let windows = faceWindows(
            in: document.editedProject, angles: angles, pairing: pairing, from: from, to: to)
        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
        var activity: [UInt32: [Double?]] = [:]
        var faces: [FaceAngle] = []
        var problems: [String] = []
        for angle in angles where wanted.contains(angle.track) {
            var clips: [FaceClip] = []
            var pending = false
            for window in windows where window.track == angle.track {
                let missed: Bool
                do {
                    missed = try document.analysisRequest(
                        kind: .faces, media: window.media, window: window.window) != nil
                } catch {
                    missed = true
                }
                guard !missed, let cacheDir = document.cacheDirectory else {
                    pending = true
                    continue
                }
                let grid = AnalysisKind.faces.grid(of: window.media)
                let stored = activity[window.media.id]
                    ?? storedActivity(window.media, grid: grid, cacheDir: cacheDir)
                activity[window.media.id] = stored
                clips.append(FaceClip(
                    span: window.span, times: window.times, grid: grid,
                    duration: window.media.duration, activity: stored))
            }
            if pending {
                problems.append(
                    "The camera on track \(angle.track) is still being analysed — its faces have "
                        + "not been found yet. Try again in a moment.")
                faces.append(FaceAngle(track: angle.track, activity: []))
            } else {
                faces.append(FaceAngle(
                    track: angle.track, activity: faceSeries(clips, from: from, count: count)))
            }
        }
        return (faces, problems)
    }

    /// One `faces` request a media still needs, and the first face-speaker angle clip needing it.
    struct FacesWant {
        let track: UInt32
        let clip: UInt32
        let media: MediaSnapshot
        let request: AnalysisRequest
    }

    /// The requests the faces mode still needs, one per media in first-window order, each
    /// media's misses merged (`ShotSplit.wants`' shape); empty in the microphones mode or when
    /// every window is a hit. Main thread; throws `analysisRequest`'s errors.
    static func facesWanted(_ input: Input, in document: ProjectDocument) throws -> [FacesWant] {
        guard mode(input.pairing) == .faces else { return [] }
        let windows = faceWindows(
            in: document.editedProject, angles: input.angles, pairing: input.pairing,
            from: input.from, to: input.to)
        var order: [UInt32] = []
        var misses: [UInt32: [AnalysisRequest]] = [:]
        var first: [UInt32: FaceWindow] = [:]
        for window in windows {
            guard let request = try document.analysisRequest(
                kind: .faces, media: window.media, window: window.window)
            else { continue }
            let id = window.media.id
            if misses[id] == nil {
                order.append(id)
                first[id] = window
            }
            misses[id, default: []].append(request)
        }
        return order.compactMap { id in
            guard let requests = misses[id], let head = requests.first, let window = first[id]
            else { return nil }
            let request = AnalysisRequest(
                kind: head.kind, cacheDir: head.cacheDir, media: head.media, url: head.url,
                stamp: head.stamp, input: head.input,
                ranges: AnalysisStore.merged(requests.flatMap(\.ranges)))
            return FacesWant(
                track: window.track, clip: window.span.clip, media: window.media, request: request)
        }
    }
}

extension AnalysisClipTimes {
    /// The forward source tick at `t` ticks from the clip's start: the inverse of
    /// `clipTime(ofSource:)` (its source map when it ramps, its speed when not, the reversed
    /// mirror last).
    func source(atClip t: Ticks) -> Int64 {
        let played: Int64
        if let map {
            played = Int64(map.source(atClip: Double(t)).rounded())
        } else {
            played = sourceIn + Int64((Double(t) * speed).rounded())
        }
        return pivot.map { ReverseMirror.mirrored(played, about: $0) } ?? played
    }
