    /// The container `set_scope` has open, as `text_behind_subject` reads it:
    /// no `scope` key, on the main thread, committed through
    /// `performGroupedEdit` (which stamps that scope on the ops).
    func switchAngle(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try idArg(a, "clip")
        let angle = try idArg(a, "angle")
        let container =
            effectiveScope(document).flatMap { document.project.scoped($0) } ?? document.project
        let answer: SwitchAngle.Answer
        do {
            answer = try SwitchAngle.plan(clip: clip, angle: angle, in: container)
        } catch let error as ToolError {
            throw error
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        switch answer {
        case .refused(let reason):
            throw ToolError(message: reason)
        case .plan(let plan):
            _ = try performGroupedEdit(document, plan.actionName, plan.ops)
            // Written by hand so the keys keep SW-15's order.
            let step = try JSONSerialization.data(
                withJSONObject: plan.actionName, options: .fragmentsAllowed)
            let project = try JSONSerialization.data(withJSONObject: summary(document))
            let pieces = plan.pieces.map(String.init).joined(separator: ",")
            let text = "{\"ok\":true,\"step\":\(String(decoding: step, as: UTF8.self)),"
                + "\"pieces\":[\(pieces)],\"transitions_removed\":\(plan.transitionsRemoved),"
                + "\"project\":\(String(decoding: project, as: UTF8.self))}"
            return try callResult(content: [["type": "text", "text": text]], isError: false)
        }
    }

    // MARK: - switch_by_speaker (SW2b, SW8)

    /// What the first hop resolved: the document, the values, and the project and scope the
    /// call read, which the last hop requires unchanged (SW-86).
    private struct SpeakerCall {
        let document: ProjectDocument
        let settings: SpeakerSwitch.Settings
        let pairing: SpeakerSwitch.Pairing?
        let range: (from: Ticks, to: Ticks)?
        let track: UInt32?
        let asked: ReelProject
        let scope: UInt32?
    }

    /// SW-26 (c) as SW-86 amends it: on the server thread (`creatorOffMainTools`), the container
    /// `set_scope` has open, no `scope` key. One main hop reads the arguments, `read` and the faces
    /// the store still misses; with none it plans and edits in that hop. Otherwise the call wants
    /// them under an owner of its own and waits at most `AnalysisLane.callWaitLimit`, then a last
    /// hop refuses a changed project or scope, reads again and runs SW2b's sequence: Replace's
    /// track, `plan` and `edit`, `apply: false` answering without editing, one
    /// `performGroupedEdit`.
    func switchBySpeaker(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "switch_by_speaker must run on the server thread — its name is missing "
                    + "from AgentServer.creatorOffMainTools.")
        }
        let (call, wants, answer): (SpeakerCall, [SpeakerSwitch.FacesWant], String?) = try onMain {
            let call = try speakerCall(a)
            let input = try speakerInput(call)
            let wants: [SpeakerSwitch.FacesWant]
            do {
                wants = try SpeakerSwitch.facesWanted(input, in: call.document)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            guard wants.isEmpty else { return (call, wants, nil) }
            return (call, wants, try finishSpeakerSwitch(a, call, input))
        }
        if let answer { return answer }
        try waitForFaces(wants, document: call.document, stop: stop)
        return try onMain {
            guard call.document.project === call.asked, call.document.scope == call.scope else {
                throw ToolError(
                    message: "the project changed while \(SpeakerSwitch.actionName) was "
                        + "analyzing, so nothing was switched. Call switch_by_speaker again.")
            }
            return try finishSpeakerSwitch(a, call, try speakerInput(call))
        }
    }

    /// SW-26 (c)'s arguments and errors, and the pairing: a named `wide` without `speakers` drops
    /// a shared-microphone speaker on it (SW-83); `min_shot` absent is 3 s in the faces mode.
    private func speakerCall(_ a: [String: Any]) throws -> SpeakerCall {
        let document = try target(a)
        var settings = try speakerSettings(a)
        let fps = document.editedProject.snapshot.canvas.fps
        let from = try intArg(a, "from").map { ReelTime.snapToFrame(Ticks($0), fps: fps) }
        let to = try intArg(a, "to").map { ReelTime.snapToFrame(Ticks($0), fps: fps) }
        if (from == nil) != (to == nil) {
            throw ToolError(message: "Name both from and to, or neither.")
        }
        if let from, let to, to <= from {
            throw ToolError(message: "to (\(to)) must be after from (\(from)) on the frame grid.")
        }
        let scope = try idScope(document)
        func trackID(_ raw: Any?, _ key: String) throws -> UInt32 {
            guard let number = raw as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID(),
                let value = Self.whole(number), value >= 0, value <= Int(UInt32.max)
            else { throw ToolError(message: "\(key) must be a track id (an integer).") }
            guard scope.track(UInt32(value)) != nil else {
                throw ToolError(message: "no track with id \(value)")
            }
            return UInt32(value)
        }
        var speakers: [SpeakerSwitch.Speaker]?
        if let raw = a["speakers"], !(raw is NSNull) {
            guard let rows = raw as? [Any], !rows.isEmpty else {
                throw ToolError(
                    message: "speakers must be an array of {mic, angle} objects, at least one.")
            }
            speakers = try rows.map { row in
                guard let item = row as? [String: Any] else {
                    throw ToolError(message: "each of speakers must be an object {mic, angle}.")
                }
                if let stranger = item.keys.sorted().first(where: { $0 != "mic" && $0 != "angle" })
                {
                    throw ToolError(
                        message: "speakers: unknown key \(stranger); each speaker is {mic, angle}.")
                }
                return SpeakerSwitch.Speaker(
                    mic: try trackID(item["mic"], "a speaker's mic"),
                    angle: try trackID(item["angle"], "a speaker's angle"))
            }
        }
        let snapshot = document.editedProject.snapshot
        let selected = document.selection.sorted().compactMap { snapshot.clip($0) }
        let implied = SpeakerSwitch.defaults(selection: selected, in: snapshot)
        var wide: UInt32?
        let wideNamed = a.keys.contains("wide")
        if let raw = a["wide"], !(raw is NSNull) {
            let id = try trackID(raw, "wide")
            guard implied.angles.contains(id) else {
                throw ToolError(message: "wide: track \(id) is not an angle")
            }
            wide = id
        }
        let track = try a["track"].flatMap { $0 is NSNull ? nil : $0 }.map {
            try trackID($0, "track")
        }

        // `wide` absent: SW-20's leftover rule over the speakers used.
        let pairing: SpeakerSwitch.Pairing?
        if let speakers {
            if !wideNamed {
                let used = Set(speakers.compactMap(\.angle))
                let left = implied.angles.filter { !used.contains($0) }
                wide = left.count == 1 ? left.first : nil
            }
            pairing = SpeakerSwitch.Pairing(speakers: speakers, wide: wide)
        } else {
            pairing = wideNamed
                ? SpeakerSwitch.withoutWide(
                    SpeakerSwitch.Pairing(speakers: implied.pairing.speakers, wide: wide)) : nil
        }
        if a["min_shot"] == nil || a["min_shot"] is NSNull,
            SpeakerSwitch.mode(pairing ?? implied.pairing) == .faces
        {
            settings.minShot = FaceActivity.minShot  // SW-82
        }
        let range = from.flatMap { f in to.map { (from: f, to: $0) } }
        return SpeakerCall(
            document: document, settings: settings, pairing: pairing, range: range, track: track,
            asked: document.project, scope: document.scope)
    }

    private func speakerInput(_ call: SpeakerCall) throws -> SpeakerSwitch.Input {
        guard
            let input = SpeakerSwitch.read(
                from: call.document, clips: nil, pairing: call.pairing, range: call.range,
                settings: call.settings)
        else {
            throw ToolError(
                message: "The project's audio plan could not be read, so Switch by Speaker "
                    + "cannot run. Try again in a moment.")
        }
        return input
    }

    /// SW2b's sequence over `input`, main thread: Replace's track, `plan`, `edit`, then the edit
    /// unless `apply` is false, and the answer with SW-86's `mode` and, in the faces mode, `note`.
    private func finishSpeakerSwitch(
        _ a: [String: Any], _ call: SpeakerCall, _ input: SpeakerSwitch.Input
    ) throws -> String {
        let document = call.document
        let track = call.track
        let snapshot = document.editedProject.snapshot
        let refused = "Switch by Speaker was refused: "
        if let track,
            let why = SpeakerSwitch.replaceRefusal(
                track, input: input, selection: document.selection, in: snapshot)
        {
            throw ToolError(message: refused + why)
        }
        guard case .planned(let shots, let added) = SpeakerSwitch.plan(input) else {
            if case .refused(let reasons) = SpeakerSwitch.plan(input) {
                throw ToolError(message: refused + reasons.joined(separator: " "))
            }
            throw ToolError(message: refused + "nothing was planned.")
        }
        let mute = try boolArg(a, "mute_cameras") ?? SpeakerSwitch.muteDefault(input)
        let answer: SpeakerSwitch.EditAnswer
        do {
            answer = try SpeakerSwitch.edit(
                shots, input: input, muteCameras: mute, replacing: track,
                selection: document.selection, in: document.editedProject)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        let edit: SpeakerSwitch.Edit
        switch answer {
        case .refused(let why):
            // (a)'s refusal already says where; (h)'s is the bare sentence.
            throw ToolError(
                message: why.hasPrefix("Switch by Speaker was refused") ? why : refused + why)
        case .edit(let made):
            edit = made
        }

        let apply = try boolArg(a, "apply") ?? true
        if apply {
            try performGroupedEdit(document, SpeakerSwitch.actionName, edit.ops)
            document.selection = edit.selection
        }
        func id(_ value: UInt32?) -> Any { value.map { NSNumber(value: $0) } ?? NSNull() }
        var fields: [String: Any] = [
            "ok": true,
            "applied": apply,
            "track": apply || track != nil ? id(edit.track) : NSNull(),
            "shots": shots.map { ["angle": $0.angle, "start": $0.start, "end": $0.end] },
            "ops": edit.ops.count,
            "added": added,
            "speakers": input.pairing.speakers.map { ["mic": id($0.mic), "angle": id($0.angle)] },
            "wide": id(input.pairing.wide),
            "mute_cameras": mute,
            "project": summary(document),
        ]
        if apply { fields["step"] = SpeakerSwitch.actionName }
        let mode = SpeakerSwitch.mode(input.pairing)
        fields["mode"] = mode.rawValue
        if mode == .faces { fields["note"] = FaceActivity.hedge }
        return try jsonResult(fields)
    }

    /// Wants every request under an owner of the call's own and waits (`waitForShots`' shape);
    /// throws naming the first media not landed when one failed, the call was stopped, or the
    /// bound passed (SW-86).
    private func waitForFaces(
        _ wants: [SpeakerSwitch.FacesWant], document: ProjectDocument, stop: AgentCallCancel?
    ) throws {
        let lane = AnalysisLane.shared
        let requests = wants.map(\.request)
        let owner = lane.newOwner()
        defer { lane.release(owner: owner) }
        lane.want(
            requests, owner: owner,
            alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
            settled: { document.packageContentsDidChangeOnDisk() })
        let outcome = lane.wait(
            for: requests, owner: owner,
            deadline: Date().addingTimeInterval(AnalysisLane.callWaitLimit),
            cancelled: { stop?.isCancelled ?? false })
        let open = wants.first { lane.run(of: $0.request)?.outcome != .landed } ?? wants[0]
        let media = open.media.id
        switch outcome {
        case .landed: return
        case .failed(let why):
            throw ToolError(message: "The faces analysis of media \(media) failed: \(why).")
        case .cancelled:
            throw ToolError(
                message: "The faces analysis of media \(media) was stopped before it finished, "
                    + "so nothing was switched.")
        case .timedOut:
            throw ToolError(
                message: "The faces analysis of media \(media) did not finish in the "
                    + "\(Int(AnalysisLane.callWaitLimit)) s a call waits; what it covered is "
                    + "kept — call switch_by_speaker again to continue.")
        }
    }

    /// SW-26's numbers and `crosstalk`, each refused outside its range in auto_zoom's form.
    private func speakerSettings(_ a: [String: Any]) throws -> SpeakerSwitch.Settings {
        typealias S = SpeakerSwitch.Settings
        func plain(_ v: Double) -> String {
            v.rounded() == v && abs(v) < 1e15 ? String(Int64(v)) : String(v)
        }
        func number(_ key: String, _ unit: String, _ range: ClosedRange<Double>) throws
            -> Double?
        {
            guard let v = try doubleArg(a, key) else { return nil }
            guard v.isFinite, range.contains(v) else {
                throw ToolError(
                    message: "\(key) is \(plain(v))\(unit); it runs "
                        + "\(plain(range.lowerBound))–\(plain(range.upperBound))\(unit).")
            }
            return v
        }
        var s = S()
        s.minShot = try number("min_shot", " s", S.minShotRange) ?? s.minShot
        s.minTurn = try number("min_turn", " s", S.minTurnRange) ?? s.minTurn
        s.lead = try number("lead", " s", S.leadRange) ?? s.lead
        s.bleedDB = try number("bleed_db", " dB", S.bleedRange) ?? s.bleedDB
        s.dominanceDB = try number("dominance_db", " dB", S.dominanceRange) ?? s.dominanceDB
        s.wideAfter = try number("wide_after", " s", S.wideAfterRange)
        if let crosstalk = try stringArg(a, "crosstalk") {
            guard let value = SpeakerSwitch.Crosstalk(rawValue: crosstalk) else {
                throw ToolError(
                    message: "crosstalk is \"\(crosstalk)\"; it is \"wide\" or \"hold\".")
            }
            s.crosstalk = value
        }
        return s
    }
}
import Foundation

/// Switch Angle (road map "creator-jobs" SW1, spec §11 SW-13…SW-15): which
/// tracks are angles for a shot, and the sequence that re-picks the shot from
/// one. Clip ▸ Switch Angle ▸ (`EditorViewController+SwitchAngle.swift`) and
/// `switch_angle` (`AgentServer+Switch.swift`) both run it. It names no
/// `rc_*`: every op is tried through `ReelProject.applying(_:)`.
///
/// **Covering (SW-13, SW-15 (d)).** A track covers a span when its media
/// clips with a picture (`sourceSize(of:) != nil`) leave no tick of it
/// uncovered; a clip with its picture switched off, or on a hidden track,
/// still counts.
///
/// **The re-pick (SW-14, SW-15 (e)).** With B the shot between A and C on its
/// track: `delete` B, trim A's end to B's start and C's start to B's end
/// (each `alone`), one `copy_pieces` per angle clip the span crosses (B's
/// switches), then A and C trimmed back to their old edges and the two
/// transitions put back. The ops are tried one at a time on the container's
/// handle, because `applying([ReelOp])` does not stop at a refusal: a refusal
/// before the trim-backs, or a trim away held short of its target, refuses
/// the whole plan and nothing is committed; a trim-back that is refused or
/// held short is left out with its edge's transition, and the step is named
/// "Switch Angle (transition removed)".
enum SwitchAngle {
    /// One row of Clip ▸ Switch Angle ▸.
    struct Angle: Equatable {
        let track: UInt32
        let title: String
    }

    /// The most rows the submenu lists.
    static let menuLimit = 9
    static let actionName = "Switch Angle"
    static let removedName = "Switch Angle (transition removed)"

    /// The ops of a re-pick, its step's name, the new pieces' ids in time
    /// order, and how many of the shot's two transitions were dropped.
    struct Plan {
        let ops: [ReelOp]
        let actionName: String
        let pieces: [UInt32]
        let transitionsRemoved: Int
    }

    enum Answer {
        case plan(Plan)
        case refused(String)
    }

    /// The media clips with a picture on `track`, by start.
    static func pictureClips(on track: UInt32, in snapshot: ProjectSnapshot) -> [ClipSnapshot] {
        snapshot.clips(onTrack: track).filter { clip in
            guard case .media = clip.source else { return false }
            return snapshot.sourceSize(of: clip) != nil
        }
    }

    /// The first tick of `[from, to)` no picture clip on `track` covers, or
    /// nil when the track covers the whole span.
    static func firstUncovered(
        track: UInt32, from: Ticks, to: Ticks, in snapshot: ProjectSnapshot
    ) -> Ticks? {
        var reached = from
        for clip in pictureClips(on: track, in: snapshot) where clip.end > reached {
            if clip.start > reached { return reached }
            reached = clip.end
            if reached >= to { return nil }

            if reached >= to { return nil }
        }
        return reached < to ? reached : nil
    }

    /// Every other track of the container covering `clip`'s whole span, front
    /// first, at most `menuLimit`. A name two listed tracks share gets " (n)",
    /// n the track's 1-based position from the back.
    static func angles(for clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> [Angle] {
        let covering = snapshot.tracks.reversed()
            .filter {
                $0.id != clip.track
                    && firstUncovered(track: $0.id, from: clip.start, to: clip.end, in: snapshot)
                        == nil
            }
            .prefix(menuLimit)
        let names = covering.map(\.name)
        return covering.map { track in
            guard names.filter({ $0 == track.name }).count > 1 else {
                return Angle(track: track.id, title: track.name)
            }
            let position = (snapshot.trackIndex(of: track.id) ?? 0) + 1
            return Angle(track: track.id, title: "\(track.name) (\(position))")
        }
    }

    /// Re-picks clip `id` from track `angle` in `container` (the handle of
    /// the container being edited). Throws for an unknown clip or track.
    static func plan(clip id: UInt32, angle: UInt32, in container: ReelProject) throws -> Answer {
        let snapshot = container.snapshot
        guard let shot = snapshot.clip(id) else {
            throw ReelCoreError(message: "no clip with id \(id)")
        }
        guard snapshot.track(angle) != nil else {
            throw ReelCoreError(message: "no track with id \(angle)")
        }
        if let why = refusal(shot, angle: angle, in: snapshot) { return .refused(why) }

        let (s, e) = (shot.start, shot.end)
        let neighbours = snapshot.clips(onTrack: shot.track).filter { $0.id != shot.id }
        let before = neighbours.last { $0.start < s && $0.end > s }
        let after = neighbours.first { $0.start > s && $0.start < e }
        var trial = Trial(project: container)

        if let why = try trial.require(.delete(clips: [id])) { return .refused(why) }
        if let a = before {
            if let why = try trial.require(.trimEnd(clip: a.id, to: s, alone: true)) {
                return .refused(why)
            }
            let reached = trial.project.snapshot.clip(a.id)?.end ?? a.end
            if reached != s { return .refused(held(a.id, reached, s, shot: id)) }
        }
        if let c = after {
            if let why = try trial.require(.trimStart(clip: c.id, to: e, alone: true)) {
                return .refused(why)
            }
            let reached = trial.project.snapshot.clip(c.id)?.start ?? c.start
            if reached != e { return .refused(held(c.id, reached, e, shot: id)) }
        }
        for range in pieceRanges(angle: angle, from: s, to: e, in: snapshot) {
            let op = ReelOp.copyPieces(
                clip: range.clip, track: shot.track, ranges: [(range.from, range.to)],
                video: shot.enabled.video, audio: shot.enabled.audio)
            if let why = try trial.require(op) { return .refused(why) }
        }
        let known = Set(snapshot.clips.map(\.id))
        let pieces = trial.project.snapshot.clips(onTrack: shot.track)
            .filter { !known.contains($0.id) }.map(\.id)

        var removed = 0
        if let a = before, let first = pieces.first {
            let back = ReelOp.trimEnd(clip: a.id, to: a.end, alone: true)
            if try trial.attempt(back, holds: { $0.clip(a.id)?.end == a.end }) {
                try trial.putBack(shot.transitionIn, on: first)
            } else {
                removed += 1
                try trial.clearTransition(on: first)
            }
        }
        if let c = after, !pieces.isEmpty {
            let back = ReelOp.trimStart(clip: c.id, to: c.start, alone: true)
            if try trial.attempt(back, holds: { $0.clip(c.id)?.start == c.start }) {
                try trial.putBack(c.transitionIn, on: c.id)
            } else {
                removed += 1
                try trial.clearTransition(on: c.id)
            }
        }
        return .plan(
            Plan(
                ops: trial.ops, actionName: removed > 0 ? removedName : actionName,
                pieces: pieces, transitionsRemoved: removed))
    }

    /// SW-15 (c)'s refusals, in order.
    private static func refusal(
        _ shot: ClipSnapshot, angle: UInt32, in snapshot: ProjectSnapshot
    ) -> String? {
        if angle == shot.track {
            return "track \(angle) is clip \(shot.id)'s own track; an angle is another track"
        }
        if snapshot.track(shot.track)?.locked == true {
            return "track \(shot.track) is locked, so clip \(shot.id) cannot be re-picked"
        }
        if let partner = shot.linked {
            return "clip \(shot.id) is linked to clip \(partner) (Detach Audio's pair); "
                + "Switch Angle re-picks a clip with no link"
        }
        if let tick = firstUncovered(track: angle, from: shot.start, to: shot.end, in: snapshot) {
            return "track \(angle) does not cover clip \(shot.id): nothing with a picture "
                + "plays on it at tick \(tick)"
        }
        return nil
    }

    /// The held-trim sentence (SW-15 (e)).
    private static func held(_ clip: UInt32, _ reached: Ticks, _ target: Ticks, shot: UInt32)
        -> String
    {
        "clip \(clip)'s edge is held at tick \(reached), short of tick \(target), so clip "
            + "\(shot) cannot be re-picked"
    }

    /// Each angle clip crossing `[from, to)` and the part of it a piece takes:
    /// `[max(start, from), min(end, the next one's start, to))`, empty ones
    /// skipped (SW-15 (d)).
    static func pieceRanges(
        angle: UInt32, from: Ticks, to: Ticks, in snapshot: ProjectSnapshot
    ) -> [(clip: UInt32, from: Ticks, to: Ticks)] {
        let crossing = pictureClips(on: angle, in: snapshot)
            .filter { $0.end > from && $0.start < to }
        var out: [(clip: UInt32, from: Ticks, to: Ticks)] = []
        for (index, clip) in crossing.enumerated() {
            let next = index + 1 < crossing.count ? crossing[index + 1].start : to
            let low = max(clip.start, from)
            let high = min(clip.end, next, to)
            if high > low { out.append((clip.id, low, high)) }
        }
        return out
    }

    /// The handle the plan has reached and the ops that reached it.
    struct Trial {
        var project: ReelProject
        var ops: [ReelOp] = []

        /// Applies `op`; nil when it applied or changed nothing, else the
        /// rule's sentence (nothing kept).
        mutating func require(_ op: ReelOp) throws -> String? {
            switch try project.applying(op) {
            case .applied(let next):
                project = next
                ops.append(op)
                return nil
            case .identity:
                ops.append(op)
                return nil
            case .refused(let refusal):
                return refusal.reason
            }
        }

        /// Keeps `op` only when it applied and the result `holds`.
        mutating func attempt(_ op: ReelOp, holds: (ProjectSnapshot) -> Bool) throws -> Bool {
            guard case .applied(let next) = try project.applying(op), holds(next.snapshot)
            else { return false }
            project = next
            ops.append(op)
            return true
        }

        /// The kind and style of `transition` on `clip`, when there was one.
        mutating func putBack(_ transition: TransitionSnapshot?, on clip: UInt32) throws {
            guard let transition else { return }
            _ = try require(.setTransition(clip: clip, kind: transition.kind))
            _ = try require(
                .setTransitionStyle(
                    clip: clip, curve: transition.curve, audio: transition.audio,
                    audioShape: transition.audioShape))
        }

        /// A left-out edge's clip keeps no transition.
        mutating func clearTransition(on clip: UInt32) throws {
            guard project.snapshot.clip(clip)?.transitionIn != nil else { return }
            _ = try require(.setTransition(clip: clip, kind: nil))
        }
    }
}
import AppKit

/// Clip ▸ Switch Angle ▸ (road map "creator-jobs" SW1, spec §11 SW-13…SW-15):
/// the one selected clip re-picked from the chosen covering track by
/// `SwitchAngle.plan`, as one undo step through `applyEdit`, then the new
/// pieces selected. A plan's refusal beeps and reaches the inspector's
/// refusal strip. `switch_angle`'s tool mirrors it (`AgentServer+Switch.swift`).
/// The rows are `SwitchAngleMenuFiller`'s (`AppDelegate+ClipMenus.swift`).
extension EditorViewController {

    /// The one selected clip when the menu may re-pick it: exactly one clip
    /// selected, its track unlocked, no link (SW-15 (b)).
    var switchAngleClip: ClipSnapshot? {
        guard let document, selectedClips.count == 1, let clip = selectedClips.first,
            clip.linked == nil,
            document.editedProject.snapshot.track(clip.track)?.locked == false
        else { return nil }
        return clip
    }

    @objc func switchAngle(_ sender: Any?) {
        guard let document, view.window?.attachedSheet == nil,
            let track = ((sender as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value,
            let clip = switchAngleClip
        else {
            NSSound.beep()
            return
        }
        let answer: SwitchAngle.Answer
        do {
            answer = try SwitchAngle.plan(
                clip: clip.id, angle: track, in: document.editedProject)
        } catch {
            NSSound.beep()
            return
        }
        switch answer {
        case .plan(let plan):
            document.applyEdit(plan.actionName, plan.ops)
            document.selection = Set(plan.pieces)
        case .refused(let reason):
            NSSound.beep()
            NotificationCenter.default.post(
                name: .projectDocumentDidRefuse, object: document,
                userInfo: ["refusal": ReelRefusal(op: "switch_angle", reason: reason)])
        }
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case;
    /// nil for any other action. On when `switchAngleClip` exists, the item's
    /// track is still one of its angles and no sheet is up; allowed inside a
    /// nest.
    func validateSwitchAngleAction(
        _ action: Selector, item: any NSValidatedUserInterfaceItem
    ) -> Bool? {
        guard action == #selector(switchAngle(_:)) else { return nil }
        guard let document, view.window?.attachedSheet == nil, let clip = switchAngleClip,
            let track = ((item as? NSMenuItem)?.representedObject as? NSNumber)?.uint32Value
        else { return false }
        return SwitchAngle.angles(for: clip, in: document.editedProject.snapshot)
            .contains { $0.track == track }
    }
}

import Foundation

/// `reframe_clip` (road map "creator-jobs" VR2a2 and VR2b1, spec §11 VR-26…VR-28):
/// the op tool whose `subjects` the app fills from the analysis cache. It mirrors
/// Clip ▸ Follow Subject… (VR2b2, spec §11 VR-29: this op with `replace: true` per
/// selected clip and a "Backgrounds" backdrop track); every refusal is the core's
/// sentence, and Swift copies none of VR-26's or VR-27's rules (`replace` is
/// passed through as the caller sent it). It reads no `UserDefaults` (AU-68 (f)).
///
/// **Runs on the SERVER thread** (`creatorOffMainTools`), in three hops:
/// - the first main hop resolves the arguments and TRIES the op with no
///   `subjects`, scoped, on the document's project without committing (as the
///   inspector's probe does). Only the core's "no subjects" refusal (VR-26's
///   tenth, LAST so every other one answers the trial) leads to the analysis;
///   an applied, identity or other refused trial goes straight to the last
///   hop;
/// - the wait is `split_at_shots`'s: a new lane owner and CJ-25's bound. Past
///   it the same requests are wanted again on that owner, held by
///   `FramingWant` until every one has ended or the document closes, and the
///   answer is `analyzing`, with no edit;
/// - the subjects are read off main (`FramingSubjects`), and the last main hop
///   refuses a changed project or scope, then applies one op as one undo step,
///   "Reframe Clip".
///
/// `follow: cursor` (VR5, spec §11 VR-50 (i)) never waits: after the trial's "no
/// subjects" the first hop finds the media's cursor file (`AutoZoom.cursorFiles`, its
/// sentences the refusal), and the file is opened and read off main
/// (`FramingCursor.read`) in place of the analysis; the answer's `cached` is true.
///
/// `follow: speaker` (VR6a, spec §11 VR-60 (c)) waits for the analysis as a following
/// kind does; its `mics` and `mic_faces` are passed through, a call addressed to a
/// container other than the open one is refused before the trial, and the last main
/// hop adds `turns` to the subjects (`FramingSpeaker.turns`, Switch by Speaker's reading
/// of the microphones, its refusals SW-24's).
extension AgentServer {

    /// What the first main hop resolves.
    private struct FramingCall {
        let document: ProjectDocument
        let clip: UInt32
        let follow: FramingFollow
        let zoom: Double?
        let whereEmpty: FramingWhereEmpty?
        let fromWidth: UInt32?
        let fromHeight: UInt32?
        let backdrop: UInt32?
        let replace: Bool?
        let mics: [UInt32]?
        let micFaces: [UInt32]?
        /// The analysis to read, or nil when the trial needs none.
        let reading: FramingReading?
        /// The cursor file to read for `follow: cursor`, or nil.
        let cursor: CursorReading?
        let asked: ReelProject
        let scope: UInt32?

        func op(subjects: [String: Any]?) -> ReelOp {
            .reframeClip(
                clip: clip, follow: follow, zoom: zoom, whereEmpty: whereEmpty,
                fromWidth: fromWidth, fromHeight: fromHeight, backdrop: backdrop,
                replace: replace, mics: mics, micFaces: micFaces, subjects: subjects)
        }

        /// The same call reading `reading` or `cursor` instead.
        func with(reading: FramingReading?, cursor: CursorReading?) -> FramingCall {
            FramingCall(
                document: document, clip: clip, follow: follow, zoom: zoom,
                whereEmpty: whereEmpty, fromWidth: fromWidth, fromHeight: fromHeight,
                backdrop: backdrop, replace: replace, mics: mics, micFaces: micFaces,
                reading: reading, cursor: cursor, asked: asked, scope: scope)
        }
    }

    /// The clip's media, its windows and its cursor file (VR-50 (i)).
    private struct CursorReading {
        let media: MediaSnapshot
        let windows: [ClosedRange<Ticks>]
        let files: [UInt32: URL]
    }

    /// The clip's media, its windows, the cache folder and what is missing.
    private struct FramingReading {
        let media: MediaSnapshot
        let windows: [ClosedRange<Ticks>]
        let cacheDir: URL
        let requests: [AnalysisRequest]
    }

    func reframeClip(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "reframe_clip must run on the server thread — its name is missing "
                    + "from AgentServer.creatorOffMainTools.")
        }
        let call = try onMain { try self.resolveFraming(a) }
        var subjects: [String: Any]?
        if let reading = call.reading {
            if !reading.requests.isEmpty,
                let analyzing = try waitForAnalysis(
                    reading.requests, document: call.document, stop: stop,
                    unmade: "nothing was framed",
                    note: { percent in
                        "Still analyzing the media of clip \(call.clip) (\(percent) %); call "
                            + "reframe_clip again to apply."
                    })
            {
                return analyzing
            }
            subjects = FramingSubjects.read(
                media: reading.media, windows: reading.windows, cacheDir: reading.cacheDir)
        }
        if let cursor = call.cursor {
            do {
                guard let track = try AutoZoom.readTracks(cursor.files)[cursor.media.id] else {
                    throw ToolError(message: "Media \(cursor.media.id)'s cursor file was not read.")
                }
                subjects = try FramingCursor.read(
                    track, media: cursor.media, windows: cursor.windows)
            } catch let error as ToolError {
                throw error
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
        }
        let cached = call.reading?.requests.isEmpty ?? true
        return try onMain {
            let document = call.document
            guard document.project === call.asked, document.scope == call.scope else {
                throw ToolError(
                    message: "the project changed while reframe_clip read the clip's analysis, "
                        + "so nothing was framed. Call reframe_clip again.")
            }
            // VR-60 (c): who speaks when, read on this hop from the microphones' caches.
            var filled = subjects
            if call.follow == .speaker, filled != nil,
                let shown = document.editedProject.snapshot.clip(call.clip)
            {
                do {
                    filled?["turns"] = try FramingSpeaker.turns(
                        document: document, clip: shown, mics: call.mics ?? [])
                } catch let refusal as FramingSpeaker.Refusal {
                    throw ToolError(message: "reframe_clip was refused: " + refusal.sentence)
                }
            }
            return try self.editResult(
                document, FramingWant.actionName, [call.op(subjects: filled)],
                ["cached": cached])
        }
    }

    /// Every argument in the op's order, the trial, and — only when the core
    /// answered "no subjects" — what the analysis must cover.
    private func resolveFraming(_ a: [String: Any]) throws -> FramingCall {
        let document = try target(a)
        _ = try idArg(a, "clip")
        let follow = try requiredEnumArg(a, "follow", FramingFollow.self)
        let clip = try clipArg(a, "clip", document)
        var backdrop: UInt32?
        if let raw = a["backdrop"], !(raw is NSNull) {
            backdrop = try trackArg(a, "backdrop", document).id
        }
        let call = FramingCall(
            document: document, clip: clip.id, follow: follow, zoom: try doubleArg(a, "zoom"),
            whereEmpty: try enumArg(a, "where_empty", FramingWhereEmpty.self),
            fromWidth: try sideArg(a, "from_width"), fromHeight: try sideArg(a, "from_height"),
            backdrop: backdrop, replace: try boolArg(a, "replace"),
            mics: try numbersArg(a, "mics"), micFaces: try numbersArg(a, "mic_faces"),
            reading: nil, cursor: nil, asked: document.project, scope: document.scope)
        let scope = effectiveScope(document)
        if follow == .speaker, scope != document.scope {
            throw ToolError(
                message: "reframe_clip was refused: follow speaker reads its microphones on the "
                    + "open timeline; open that nest first with set_scope")
        }
        let trial: ReelEdit
        do {
            trial = try document.project.applying(call.op(subjects: nil).scoped(scope))
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        guard case .refused(let refusal) = trial,
            refusal.reason == FramingWant.noSubjects(clip.id)
        else { return call }
        let view = scope.flatMap { document.project.scoped($0) } ?? document.project
        guard let entry = FramingAnalysis.windows(clips: [clip.id], in: view).first,
            let media = view.snapshot.media(entry.media)
        else { return call }
        if follow == .cursor {
            // VR-50 (i): the cursor file in place of the analysis; never a wait.
            guard let shown = view.snapshot.clip(clip.id) else { return call }
            let files: [UInt32: URL]
            do {
                files = try AutoZoom.cursorFiles([shown], in: view.snapshot)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            return call.with(
                reading: nil,
                cursor: CursorReading(media: media, windows: entry.windows, files: files))
        }
        guard let cacheDir = document.cacheDirectory else {
            throw ToolError(message: ProjectDocument.AnalysisRequestError.noCache.localizedDescription)
        }
        let requests: [AnalysisRequest]
        do {
            requests = try FramingAnalysis.requests(clips: [clip.id], in: document, project: view)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        return call.with(
            reading: FramingReading(
                media: media, windows: entry.windows, cacheDir: cacheDir, requests: requests),
            cursor: nil)
    }

    /// `mics` / `mic_faces` (VR-60 (a)): nil when absent, else whole numbers the core
    /// checks itself (an unknown microphone, a 0, a repeat). `make_vertical_version` reads
    /// its own two through it (VR-64 (a)).
    func numbersArg(_ a: [String: Any], _ key: String) throws -> [UInt32]? {
        guard let raw = a[key], !(raw is NSNull) else { return nil }
        guard let list = raw as? [Any] else {
            throw ToolError(message: "\(key) must be a list of whole numbers.")
        }
        return try list.map { value in
            guard let number = value as? NSNumber, CFGetTypeID(number) != CFBooleanGetTypeID(),
                let n = Self.whole(number), n >= 0, n <= Int(UInt32.max)
            else { throw ToolError(message: "\(key) must be a list of whole numbers.") }
            return UInt32(n)
        }
    }

    /// A whole number of pixels for `from_width` / `from_height`, nil when
    /// absent; the core refuses a 0 itself.
    private func sideArg(_ a: [String: Any], _ key: String) throws -> UInt32? {
        guard let value = try intArg(a, key) else { return nil }
        guard value >= 0, value <= Int(UInt32.max) else {
            throw ToolError(message: "\(key) must be a whole number of pixels, not \(value).")
        }
        return UInt32(value)
    }

    /// Wants the requests (non-empty) under an owner of the call's own and
    /// waits up to CJ-25's bound: nil once every one landed; past the bound
    /// the `analyzing` answer with `note(percent)`, the want held
    /// (`FramingWant`); a failure or a Stop throws naming the kind and the
    /// media, a Stop saying "so <unmade>.". `reframe_clip`'s and
    /// `make_vertical_version`'s wait (spec §11 VR-28, VR-37).
    func waitForAnalysis(
        _ requests: [AnalysisRequest], document: ProjectDocument, stop: AgentCallCancel?,
        unmade: String, note: @escaping (Int) -> String
    ) throws -> String? {
        let lane = AnalysisLane.shared
        let owner = lane.newOwner()
        lane.want(
            requests, owner: owner,
            alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
            settled: { document.packageContentsDidChangeOnDisk() })
        let outcome = lane.wait(
            for: requests, owner: owner,
import Foundation

/// `switch_layout` (road map "creator-jobs" CO6, spec §11 CO-60…CO-66),
/// mirroring Clip ▸ Camera Layout ▸ (`switchCameraLayout` in
/// `EditorViewController+Layout.swift`, which sends this op at the playhead
/// with `duration` and `curve` left to the core): one op, one undo step
/// "Camera Layout", every refusal the core's sentence. Since CO7 (spec §11
/// CO-70) an omitted or null `focus` is filled from the camera clip's cached
/// person masks, as the menu and the Picture sub-tab's Layout section fill
/// it, and the answer carries the `focus` sent.
extension AgentServer {

    /// What the first main-thread hop resolves.
    private struct LayoutCall {
        let document: ProjectDocument
        let camera: UInt32
        let screen: UInt32?
        let layout: CameraLayoutKind
        let shape: CameraLayoutShape?
        let corner: CameraLayoutCorner?
        let at: Ticks
        let duration: Ticks?
        let curve: Curve?
        let focus: (Double, Double)?
        let nest: Bool?
        let through: Ticks?
        /// The masks to fill `focus` from, when the caller left it out.
        let inputs: CameraLayoutFocus.Inputs?
        let asked: ReelProject
        let scope: UInt32?

        func op(focus: (Double, Double)?) -> ReelOp {
            .switchLayout(
                camera: camera, screen: screen, layout: layout, shape: shape, corner: corner,
                at: at, duration: duration, curve: curve, focus: focus, nest: nest,
                through: through)
        }
    }

    /// **Runs on the SERVER thread** (`creatorOffMainTools`): one main hop resolves the
    /// arguments and the camera's cached masks, the centroid is read here, and a last main hop
    /// refuses when the project or the scope changed meanwhile and applies as one undo step.
    func switchLayout(_ a: [String: Any]) throws -> String {
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "switch_layout must run on the server thread — its name is missing "
                    + "from AgentServer.creatorOffMainTools.")
        }
        let call = try onMain { try self.resolveLayout(a) }
        let filled = call.inputs.flatMap { CameraLayoutFocus.focus($0) }
        return try onMain {
            let document = call.document
            guard document.project === call.asked, document.scope == call.scope else {
                throw ToolError(
                    message: "the project changed while switch_layout read the camera's person "
                        + "masks, so nothing was laid out. Call switch_layout again.")
            }
            var focus = call.focus ?? filled
            // A filled focus is in the camera media's pixels: never sent to the nest clip
            // that `nest: true` puts in the camera's place (CO-70).
            if call.focus == nil, filled != nil, call.nest == true,
                let nested = self.addressed([call.op(focus: filled)], document).first,
                !CameraLayoutCommand.keepsFocus(
                    nested: nested, camera: call.camera, document: document)
            {
                focus = nil
            }
            let answer: Any = focus.map { [$0.0, $0.1] } ?? NSNull()
            return try self.editResult(
                document, CameraLayoutCommand.actionName, [call.op(focus: focus)],
                ["focus": answer])
        }
    }

    /// The arguments in the op's order — every required one read before an id is looked up,
    /// so a missing one is named as missing whatever the others hold — and the camera's masks
    /// when `focus` is left out.
    private func resolveLayout(_ a: [String: Any]) throws -> LayoutCall {
        let document = try target(a)
        _ = try idArg(a, "camera")
        let layout = try requiredEnumArg(a, "layout", CameraLayoutKind.self)
        let at = try timeArg(a, "at", document)
        let camera = try clipArg(a, "camera", document)
        var screen: UInt32?
        if let raw = a["screen"], !(raw is NSNull) {
            screen = try clipArg(a, "screen", document).id
        }
        let focus = try pointArg(a, "focus")
        return LayoutCall(
            document: document, camera: camera.id, screen: screen, layout: layout,
            shape: try enumArg(a, "shape", CameraLayoutShape.self),
            corner: try enumArg(a, "corner", CameraLayoutCorner.self), at: at,
            duration: try optionalTimeArg(a, "duration", document),
            curve: try enumArg(a, "curve", Curve.self), focus: focus,
            nest: try boolArg(a, "nest"),
            through: try optionalTimeArg(a, "through", document),
            inputs: focus == nil ? CameraLayoutFocus.inputs(camera: camera.id, in: document) : nil,
            asked: document.project, scope: document.scope)
    }

    /// Two finite numbers, `[x, y]`, or nil when absent or null.
    private func pointArg(_ a: [String: Any], _ key: String) throws -> (Double, Double)? {
        guard let raw = a[key], !(raw is NSNull) else { return nil }
        let numbers = (raw as? [Any])?.compactMap { value -> Double? in
            guard let number = value as? NSNumber,
                CFGetTypeID(number) != CFBooleanGetTypeID()
            else { return nil }
            return number.doubleValue
        }
        guard let numbers, numbers.count == 2, (raw as? [Any])?.count == 2,
            numbers.allSatisfy(\.isFinite)
        else {
            throw ToolError(message: "\(key) must be two numbers, [x, y].")
        }
        return (numbers[0], numbers[1])
    }
}
/// and corner. A menu item's tag is its index in `menuRows` (CO-66).
struct CameraLayoutChoice: Equatable {
    let kind: CameraLayoutKind
    let shape: CameraLayoutShape?
    let corner: CameraLayoutCorner?

    /// Every corner shape at each corner, then the other four layouts, in
    /// the menu's order.
    static let menuRows: [CameraLayoutChoice] =
        CameraLayoutShape.allCases.flatMap { shape in
            CameraLayoutCorner.allCases.map {
                CameraLayoutChoice(kind: .corner, shape: shape, corner: $0)
            }
        }
        + [.sideBySide, .stacked, .cameraFull, .screenOnly].map {
            CameraLayoutChoice(kind: $0, shape: nil, corner: nil)
        }

    /// The row's own title: the corner inside a shape's submenu, else the
    /// layout.
    var title: String { corner?.title ?? kind.title }

    /// The core's switch length when `duration` is absent (`DEFAULT_SWITCH`, 0.5 s).
    static let defaultDuration: Ticks = 300_000

    /// The op at `at` for these roles; an absent `duration` and `curve` are the core's. `focus`
    /// is the camera crop's centre (CO-70), `nest` the offer's yes (CO-72).
    func op(
        camera: UInt32, screen: UInt32?, at: Ticks, duration: Ticks? = nil,
        focus: (Double, Double)? = nil, nest: Bool? = nil
    ) -> ReelOp {
        .switchLayout(
            camera: camera, screen: screen, layout: kind, shape: shape, corner: corner, at: at,
            duration: duration, focus: focus, nest: nest)
    }
}

/// The recorder panel's Layout rows and `record_screen`'s `camera_layout` (road map
/// "creator-jobs" CO8, spec §11 CO-80, CO-82): the five a camera beside the screen may land
/// in, each corner at the bottom right. Each raw value is the key's and the tool's spelling.
enum RecordingCameraLayout: String, CaseIterable {
    case cornerSquare = "corner_square", cornerRounded = "corner_rounded"
    case cornerCircle = "corner_circle", sideBySide = "side_by_side", cameraFull = "camera_full"

    /// The pop-up's row title.
    var title: String {
        switch self {
        case .cornerSquare: return "Corner"
        case .cornerRounded: return "Rounded Corner"
        case .cornerCircle: return "Circle"
        case .sideBySide: return "Side by Side"
        case .cameraFull: return "Camera Full"
        }
    }

    /// The `switch_layout` vocabulary: a corner kind with its shape at the bottom right, else
    /// the kind alone.
    var choice: CameraLayoutChoice {
        let corner = { (shape: CameraLayoutShape) in
            CameraLayoutChoice(kind: .corner, shape: shape, corner: .bottomRight)
        }
        switch self {
        case .cornerSquare: return corner(.square)
        case .cornerRounded: return corner(.rounded)
        case .cornerCircle: return corner(.circle)
        case .sideBySide: return CameraLayoutChoice(kind: .sideBySide, shape: nil, corner: nil)
        case .cameraFull: return CameraLayoutChoice(kind: .cameraFull, shape: nil, corner: nil)
        }
    }
}

/// Who is the camera and who the screen for the menu (CO-66).
enum CameraLayoutRoles {
    /// The track a recording's camera lands on (`RecordingLanding`).
    static let cameraTrackName = "Camera"

    /// Two selected picture clips on different tracks: the front one is the
    /// camera and the other the screen. One: it is the camera and the core
    /// finds the screen. None: the clip at the playhead on the front-most
    /// track named "Camera". nil when that yields no camera containing the
    /// playhead.
    static func roles(selected: [ClipSnapshot], playhead: Ticks, in snapshot: ProjectSnapshot)
        -> (camera: UInt32, screen: UInt32?)?
    {
        let picture = { (clip: ClipSnapshot) in
            clip.video != nil && snapshot.sourceSize(of: clip) != nil
        }
        let plays = { (clip: ClipSnapshot) in clip.start <= playhead && playhead < clip.end }
        switch selected.count {
        case 2:
            guard selected.allSatisfy(picture),
                let a = snapshot.trackIndex(of: selected[0].track),
                let b = snapshot.trackIndex(of: selected[1].track), a != b
            else { return nil }
            let (camera, screen) = a > b ? (selected[0], selected[1]) : (selected[1], selected[0])
            return plays(camera) ? (camera.id, screen.id) : nil
        case 1:
            let camera = selected[0]
            return picture(camera) && plays(camera) ? (camera.id, nil) : nil
        case 0:
            guard let track = snapshot.tracks.last(where: { $0.name == cameraTrackName }),
                let camera = snapshot.clips.first(where: {
                    $0.track == track.id && plays($0) && picture($0)
                })
            else { return nil }
            return (camera.id, nil)
        default:
            return nil
        }
    }
}
import AppKit

/// Clip ▸ Camera Layout ▸ (road map "creator-jobs" CO6, spec §11 CO-66): the
/// chosen row's `switch_layout` at the playhead in the container being
/// edited, its roles by `CameraLayoutRoles`, through `CameraLayoutCommand.run`
/// (CO7, CO-70, CO-72) — the camera's focus from its cached person masks,
/// then one undo step "Camera Layout" through `performGroupedEdit`, whose
/// refusal reaches the inspector's refusal strip, or, for a switch refused
/// because a clip zooms, the nest offer's sheet. `switch_layout`'s tool
/// mirrors it (`AgentServer+Layout.swift`).
extension EditorViewController {

    /// The camera and screen the menu would lay out, or nil.
    private var cameraLayoutRoles: (camera: UInt32, screen: UInt32?)? {
        guard let document else { return nil }
        return CameraLayoutRoles.roles(
            selected: selectedClips, playhead: document.playhead,
            in: document.editedProject.snapshot)
    }

    @objc func switchCameraLayout(_ sender: Any?) {
        guard let document, view.window?.attachedSheet == nil,
            let tag = (sender as? NSMenuItem)?.tag,
            CameraLayoutChoice.menuRows.indices.contains(tag),
            let roles = cameraLayoutRoles
        else {
            NSSound.beep()
            return
        }
        CameraLayoutCommand.run(
            CameraLayoutChoice.menuRows[tag], camera: roles.camera, screen: roles.screen,
            duration: nil, document: document, window: view.window)
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case;
    /// nil for any other action. On when the roles yield a camera containing
    /// the playhead and no sheet is on the window; allowed inside a nest.
    func validateCameraLayoutAction(_ action: Selector) -> Bool? {
        guard action == #selector(switchCameraLayout(_:)) else { return nil }
        return cameraLayoutRoles != nil && view.window?.attachedSheet == nil
    }
}

//! `switch_layout` — a camera clip and the screen behind it laid out at the
//! playhead (road map "creator-jobs" CO6, spec §11 CO-61, CO-62, CO-64).
//! One op, so Clip ▸ Camera Layout ▸ is one undo step, "Camera Layout".
//! The geometry is `layout.rs`'s; this file is who is laid out, how far,
//! and what refuses.
//!
//! - **The roles** (CO-64): the camera, playing at `at` with a picture; the
//!   screen given (on a track behind) or found — the clip playing at `at`
//!   on the front-most visible, non-matte track behind the camera's with a
//!   drawn picture. No screen refuses `side_by_side` and `stacked`; the
//!   other three lay out the camera alone.
//! - **The switch** (CO-61): per role, the clip under `at` gets a LAYOUT
//!   ACTION (all six placement keys) at clip time `at − start`, 0.5 s and
//!   `ease_in_out` unless told, clamped to the clip and to its next later
//!   layout action, at least one frame; at its first frame the layout is
//!   its base and a one-frame layout action ends there (a cut). A layout
//!   action starting at `at` is replaced; one running at `at` is shortened
//!   to end there. The REACH (`edit_layout_reach.rs`) gives every later
//!   picture clip on the role's track starting before the next layout
//!   action, `through` or the track's end the layout as its base.
//! - **The refusals** (CO-62), in order: the camera, the screen, a nest
//!   clip asked for a radius it cannot draw, a mover — a non-layout action
//!   that moves a role clip and ends after `at` (a full-placement screen
//!   exempt in the three layouts that leave it full) — then whatever the
//!   composed ops say. `nest: true` nests the moving role's clips first and
//!   lays out the nest clip, unless one of them is already laid out.
//!
//! Composed from `remove_action`, `set_action`, `add_action`,
//! `set_action_end`, `set_video` and `nest_clips`, each refusal inherited in
//! its own words.

use std::collections::HashSet;

use serde_json::json;

use crate::action_class::is_layout;
use crate::edit_adjustment::is_adjustment;
use crate::edit_clip::clip_end;
use crate::edit_layout_reach::{Role, RoleKind};
use crate::layout::{
    camera_placement, screen_placement, CameraLayout, LayoutChoice, LayoutCorner, LayoutShape,
    Placement, DEFAULT_SWITCH,
};
use crate::model::{Clip, Curve, Project, Source};
use crate::outcome::Outcome;
use crate::time::{format_timecode, Ticks};

/// `switch_layout`'s arguments, in the op's row order (`edit.rs`).
#[derive(Debug, Clone, PartialEq)]
pub struct LayoutSwitch {
    pub camera: u32,
    pub screen: Option<u32>,
    pub layout: CameraLayout,
    pub shape: Option<LayoutShape>,
    pub corner: Option<LayoutCorner>,
    pub at: Ticks,
    pub duration: Option<Ticks>,
    pub curve: Option<Curve>,
    pub focus: Option<[f64; 2]>,
    pub nest: Option<bool>,
    pub through: Option<Ticks>,
}

/// One role's writes: the clip under `at`, `at` in its clip time, its
/// layout action's end, and each later reach clip's new base.
type RoleWrites = (u32, Ticks, Placement, Vec<(u32, Placement)>);

/// One composed step: the project it applied, unchanged on an identity,
/// or the refusal handed straight back.
macro_rules! step {
    ($next:ident, $call:expr) => {
        match $call? {
            Outcome::Applied(applied) => $next = applied,
            Outcome::Identity => {}
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        }
    };
}

impl Project {
    /// Whether `clip` has a picture to lay out: a video group and a source
    /// size (CO-64).
    pub(crate) fn has_layout_picture(&self, clip: &Clip) -> bool {
        clip.video.is_some() && self.source_size(clip).is_some()
    }

    /// `at` as a timecode, for a sentence.
    pub(crate) fn layout_timecode(&self, t: Ticks) -> String {
        format_timecode(t, self.canvas.fps, self.canvas.timecode_frames)
    }

    /// Lays out `s.camera` and its screen at `s.at` (this module's doc).
    pub fn switch_layout(&self, s: &LayoutSwitch) -> Result<Outcome, String> {
        let at = self.snapped(s.at);
        if at < 0 {
